function debounce(callback, wait = 250) {
  let timeout;
  return (...args) => {
    window.clearTimeout(timeout);
    timeout = window.setTimeout(() => callback(...args), wait);
  };
}

function flushScheduledRender() {
  if (runtime.scheduledRenderFrame) {
    window.cancelAnimationFrame(runtime.scheduledRenderFrame);
    runtime.scheduledRenderFrame = 0;
  }

  if (runtime.scheduledRenderTimeout) {
    window.clearTimeout(runtime.scheduledRenderTimeout);
    runtime.scheduledRenderTimeout = 0;
  }

  const reason = runtime.scheduledRenderReason || "scheduled";
  runtime.scheduledRenderReason = "";
  runtime.lastRenderedReason = reason;
  intelligenceDebug("[scheduleRenderArticles:flush]", { reason });
  renderArticles();
}

function scheduleRenderArticles(reason = "interaction", options = {}) {
  const mode = options.mode === "timeout" ? "timeout" : "frame";
  runtime.scheduledRenderReason = reason;

  if (runtime.scheduledRenderFrame) {
    window.cancelAnimationFrame(runtime.scheduledRenderFrame);
    runtime.scheduledRenderFrame = 0;
  }

  if (runtime.scheduledRenderTimeout) {
    window.clearTimeout(runtime.scheduledRenderTimeout);
    runtime.scheduledRenderTimeout = 0;
  }

  if (mode === "timeout") {
    runtime.scheduledRenderTimeout = window.setTimeout(() => {
      runtime.scheduledRenderTimeout = 0;
      flushScheduledRender();
    }, 0);
    return;
  }

  runtime.scheduledRenderFrame = window.requestAnimationFrame(() => {
    runtime.scheduledRenderFrame = 0;
    flushScheduledRender();
  });
}

function toDate(value) {
  if (!value) {
    return new Date(0);
  }
  return new Date(value);
}

function compareArticlesByPublicationDate(left, right) {
  const leftPubDate = toDate(left?.pubDate).getTime() || 0;
  const rightPubDate = toDate(right?.pubDate).getTime() || 0;
  if (rightPubDate !== leftPubDate) {
    return rightPubDate - leftPubDate;
  }

  const leftCreatedAt = toDate(left?.createdAt).getTime() || 0;
  const rightCreatedAt = toDate(right?.createdAt).getTime() || 0;
  if (rightCreatedAt !== leftCreatedAt) {
    return rightCreatedAt - leftCreatedAt;
  }

  return String(left?.title || "").localeCompare(String(right?.title || ""));
}

function sortArticlesByPublicationDate(articles) {
  return Array.isArray(articles) ? articles.slice().sort(compareArticlesByPublicationDate) : [];
}

function promoteNewestArticleInSelectedFeedGroup(article) {
  const sources = Array.isArray(article?.sources) && article.sources.length
    ? sortArticlesByPublicationDate(article.sources)
    : [article].filter(Boolean);
  const newest = sources[0] || article;

  return {
    ...article,
    ...newest,
    sources,
    sourceCount: Number(article?.sourceCount) || sources.length,
    groupedArticlesCount: Number(article?.groupedArticlesCount) || Math.max(0, sources.length - 1),
  };
}

function prepareDateFirstGroupedArticles(articles) {
  const dateSortedArticles = sortArticlesByPublicationDate(articles);
  return sortArticlesByPublicationDate(
    groupArticlesByEvent(dateSortedArticles).map(promoteNewestArticleInSelectedFeedGroup)
  );
}

function prepareSelectedFeedGroupedArticles(articles) {
  return prepareDateFirstGroupedArticles(articles);
}

function formatDate(value) {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(toDate(value));
}

function formatRefreshAge(timestamp) {
  if (!timestamp) {
    return "Awaiting first refresh";
  }

  const deltaMs = Math.max(0, Date.now() - timestamp);
  if (deltaMs < 10000) {
    return "Updated just now";
  }
  const seconds = Math.round(deltaMs / 1000);
  if (seconds < 60) {
    return `Updated ${seconds}s ago`;
  }
  const minutes = Math.round(seconds / 60);
  return `Updated ${minutes}m ago`;
}

function updateRefreshStatus(options = {}) {
  if (!elements.connectionStatus) {
    return;
  }

  if (options.message) {
    elements.connectionStatus.textContent = options.message;
    return;
  }

  const pendingCount = Number(options.pendingCount ?? runtime.pendingBackgroundNewArticles ?? 0);
  const baseLabel = AUTO_REFRESH_MODE === "off"
    ? "Manual refresh mode"
    : "Background refresh every 60 minutes";

  elements.connectionStatus.innerHTML = "";
  const baseText = document.createTextNode(baseLabel);
  elements.connectionStatus.appendChild(baseText);

  if (pendingCount > 0) {
    const spacer = document.createTextNode(" | ");
    const refreshButton = document.createElement("button");
    refreshButton.type = "button";
    refreshButton.className = "status-inline-refresh";
    refreshButton.dataset.applyRefresh = "true";
    refreshButton.textContent = "New articles available (Refresh)";
    elements.connectionStatus.append(spacer, refreshButton);
  }
}

function markRefreshInteraction(reason = "interaction", pauseMs = REFRESH_INTERACTION_PAUSE_MS) {
  runtime.refreshPauseUntil = Math.max(runtime.refreshPauseUntil || 0, Date.now() + pauseMs);
  runtime.refreshInteractionReason = reason;
}

function isBackgroundRefreshPaused() {
  return runtime.articleGridHovered || runtime.sidebarHovered || Date.now() < runtime.refreshPauseUntil;
}

function buildArticleSnapshotSignature(articles = []) {
  if (!Array.isArray(articles) || !articles.length) {
    return "empty";
  }

  const identitySlice = articles
    .slice(0, 40)
    .map((article) => String(article?.id || article?.url || article?.title || "").trim())
    .join("|");
  const newestDate = String(articles[0]?.pubDate || "");
  return `${articles.length}:${newestDate}:${identitySlice}`;
}

function countNewArticles(previousArticles = [], nextArticles = []) {
  const previousIds = new Set(
    (Array.isArray(previousArticles) ? previousArticles : [])
      .map((article) => String(article?.id || "").trim())
      .filter(Boolean)
  );

  return (Array.isArray(nextArticles) ? nextArticles : []).reduce((count, article) => {
    const articleId = String(article?.id || "").trim();
    return articleId && !previousIds.has(articleId) ? count + 1 : count;
  }, 0);
}

function renderArticleRegionPreservingScroll({ updateSummary = true } = {}) {
  const scrollY = window.scrollY;
  if (updateSummary) {
    renderSummary();
  }
  renderArticles();
  window.requestAnimationFrame(() => {
    window.scrollTo(0, scrollY);
  });
}

function clearPendingBackgroundRefresh() {
  runtime.pendingBackgroundRefresh = false;
  runtime.pendingBackgroundRefreshReason = "";
  runtime.pendingBackgroundNewArticles = 0;
  runtime.pendingSnapshot = null;
  if (runtime.pendingRefreshTimer) {
    window.clearTimeout(runtime.pendingRefreshTimer);
    runtime.pendingRefreshTimer = 0;
  }
}

function schedulePendingBackgroundRefresh() {
  if (!runtime.pendingBackgroundRefresh) {
    return;
  }
  if (runtime.pendingRefreshTimer) {
    window.clearTimeout(runtime.pendingRefreshTimer);
  }
  const delay = Math.max(250, (runtime.refreshPauseUntil || 0) - Date.now() + 250);
  runtime.pendingRefreshTimer = window.setTimeout(() => {
    runtime.pendingRefreshTimer = 0;
    if (runtime.pendingBackgroundRefresh && !isBackgroundRefreshPaused()) {
      clearPendingBackgroundRefresh();
      renderArticleRegionPreservingScroll({ updateSummary: true });
      runtime.lastRefreshStatusAt = Date.now();
      updateRefreshStatus();
      return;
    }
    if (runtime.pendingBackgroundRefresh) {
      schedulePendingBackgroundRefresh();
    }
  }, delay);
}

function dismissNotification(notificationId) {
  const notification = elements.notificationRegion?.querySelector(`[data-notification-id="${notificationId}"]`);
  if (!notification) {
    return;
  }

  window.clearTimeout(runtime.notificationTimers.get(notificationId));
  runtime.notificationTimers.delete(notificationId);
  notification.remove();
}

function showNotification({ title, message = "", type = "info", timeout = NOTIFICATION_TIMEOUT_MS }) {
  if (!elements.notificationRegion) {
    return;
  }

  const notificationId = String((runtime.notificationId += 1));
  const notification = document.createElement("article");
  const content = document.createElement("div");
  const titleElement = document.createElement("strong");
  const messageElement = document.createElement("p");
  const closeButton = document.createElement("button");

  notification.className = `notification-toast is-${type}`;
  notification.dataset.notificationId = notificationId;
  content.className = "notification-content";
  titleElement.textContent = title;
  messageElement.textContent = message;
  closeButton.className = "notification-close";
  closeButton.type = "button";
  closeButton.setAttribute("aria-label", "Dismiss notification");
  closeButton.textContent = "Dismiss";
  closeButton.addEventListener("click", () => dismissNotification(notificationId));

  content.append(titleElement);
  if (message) {
    content.appendChild(messageElement);
  }
  notification.append(content, closeButton);
  elements.notificationRegion.appendChild(notification);

  if (timeout > 0) {
    const timer = window.setTimeout(() => dismissNotification(notificationId), timeout);
    runtime.notificationTimers.set(notificationId, timer);
  }
}

function isFilterPipelineDiagnosticsEnabled() {
  try {
    const query = new URLSearchParams(window.location.search || "");
    if (query.get("debugFilterPipeline") === "1") {
      return true;
    }
    return window.localStorage?.getItem("debugFilterPipeline") === "1";
  } catch {
    return false;
  }
}

const DEFAULT_FILTER_PIPELINE_HEAVY_DIAGNOSTICS_LIMIT = 100;

function getFilterPipelineHeavyDiagnosticsLimit() {
  try {
    const query = new URLSearchParams(window.location.search || "");
    const rawLimit = query.get("debugFilterPipelineLimit") || window.localStorage?.getItem("debugFilterPipelineLimit");
    const parsedLimit = Number.parseInt(rawLimit || "", 10);
    return Number.isFinite(parsedLimit) && parsedLimit >= 0
      ? parsedLimit
      : DEFAULT_FILTER_PIPELINE_HEAVY_DIAGNOSTICS_LIMIT;
  } catch {
    return DEFAULT_FILTER_PIPELINE_HEAVY_DIAGNOSTICS_LIMIT;
  }
}

function isSelectedFeedFullPoolEnabled() {
  try {
    const query = new URLSearchParams(window.location.search || "");
    if (query.get("enableSelectedFeedFullPool") === "1") {
      return true;
    }
    return window.localStorage?.getItem("enableSelectedFeedFullPool") === "1";
  } catch {
    return false;
  }
}

function freezeNormalizedFilterState(value) {
  if (!value || typeof value !== "object" || Object.isFrozen(value)) {
    return value;
  }

  Object.values(value).forEach((childValue) => {
    freezeNormalizedFilterState(childValue);
  });
  return Object.freeze(value);
}

function createNormalizedFilterState() {
  const selectedPersonalInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests);
  const selectedFeed = state.filters.feedId ? resolveFeedByIdentity(state.filters.feedId) : null;
  const selectedBanknoteInterests = selectedPersonalInterests.filter(
    (interestId) => PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId)?.groupId === "banknote_intelligence"
  );
  const selectedIdentityInterests = getSelectedIdentityDocumentSubinterests(selectedPersonalInterests);
  const selectedSharedSecurityInterests = getSelectedSharedSecuritySubinterests(selectedPersonalInterests);
  const selectedDigitalIdentityInterests = selectedPersonalInterests.filter(
    (interestId) => PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId)?.groupId === "digital_identity_biometrics"
  );

  return freezeNormalizedFilterState({
    feed: {
      id: state.filters.feedId || "",
      resolvedId: selectedFeed?.id || "",
      name: getSelectedFeedLabel(),
      sourceGroup: state.filters.sourceGroup || "all",
      dmvFeedId: state.filters.dmvFeedId || "",
      canadaDmvFeedPath: state.filters.canadaDmvFeedPath || "",
      canadaDmvAll: Boolean(state.filters.canadaDmvAll),
    },
    dashboard: {
      enabled: selectedPersonalInterests.length > 0,
      mode: normalizePersonalDashboardMode(state.personalDashboard.mode),
      mainDomains: getSelectedMainDomains(selectedPersonalInterests),
      selectedInterests: selectedPersonalInterests,
      banknotes: selectedBanknoteInterests,
      identityDocuments: selectedIdentityInterests,
      sharedSecurity: selectedSharedSecurityInterests,
      digitalIdentity: selectedDigitalIdentityInterests,
    },
    filters: {
      search: state.filters.search || "",
      topic: state.filters.topic || "",
      tag: state.filters.tag || "",
      signal: state.filters.signalCategory || "",
      date: state.filters.date || "",
      articleIds: Array.isArray(state.filters.articleIds) ? state.filters.articleIds.slice() : [],
      alertLabel: state.filters.alertLabel || "",
    },
    keywords: {
      include: Array.isArray(state.keywordFilters?.include) ? state.keywordFilters.include.slice() : [],
      exclude: Array.isArray(state.keywordFilters?.exclude) ? state.keywordFilters.exclude.slice() : [],
    },
    sorting: {
      mode: selectedPersonalInterests.length ? "date_desc_personal_dashboard" : "date_desc",
    },
    pagination: {
      page: Number(state.pagination?.page) || 1,
      pageSize: Number(state.pagination?.pageSize) || ARTICLE_RENDER_PAGE_SIZE,
    },
    dashboardMode: state.dashboardMode || "normal",
  });
}

function serializeNormalizedFilterState(normalizedFilterState) {
  if (!normalizedFilterState) {
    return "";
  }

  return JSON.stringify({
    feed: {
      id: normalizedFilterState.feed?.id || "",
      sourceGroup: normalizedFilterState.feed?.sourceGroup || "all",
      dmvFeedId: normalizedFilterState.feed?.dmvFeedId || "",
      canadaDmvFeedPath: normalizedFilterState.feed?.canadaDmvFeedPath || "",
      canadaDmvAll: Boolean(normalizedFilterState.feed?.canadaDmvAll),
    },
    dashboard: {
      mode: normalizedFilterState.dashboard?.mode || "balanced",
      selectedInterests: normalizedFilterState.dashboard?.selectedInterests || [],
      mainDomains: normalizedFilterState.dashboard?.mainDomains || [],
    },
    filters: {
      search: normalizedFilterState.filters?.search || "",
      topic: normalizedFilterState.filters?.topic || "",
      tag: normalizedFilterState.filters?.tag || "",
      signal: normalizedFilterState.filters?.signal || "",
      date: normalizedFilterState.filters?.date || "",
      articleIds: normalizedFilterState.filters?.articleIds || [],
      alertLabel: normalizedFilterState.filters?.alertLabel || "",
    },
    keywords: {
      include: normalizedFilterState.keywords?.include || [],
      exclude: normalizedFilterState.keywords?.exclude || [],
    },
    sorting: {
      mode: normalizedFilterState.sorting?.mode || "",
    },
    pagination: {
      page: normalizedFilterState.pagination?.page || 1,
      pageSize: normalizedFilterState.pagination?.pageSize || ARTICLE_RENDER_PAGE_SIZE,
    },
    dashboardMode: normalizedFilterState.dashboardMode || "normal",
  });
}

function getNormalizedFilterStateCacheKey(normalizedFilterState) {
  const serializedState = serializeNormalizedFilterState(normalizedFilterState);
  return serializedState ? `normalized:${serializedState}` : "";
}

function hasNormalizedAdvancedFilters(normalizedFilterState) {
  const filters = normalizedFilterState?.filters || {};
  const keywords = normalizedFilterState?.keywords || {};
  return Boolean(
    filters.search ||
      filters.topic ||
      filters.tag ||
      filters.signal ||
      filters.date ||
      filters.articleIds?.length ||
      keywords.include?.length ||
      keywords.exclude?.length
  );
}

function resolveCandidateStrategy(normalizedFilterState, candidatePoolContext = null) {
  const filters = normalizedFilterState?.filters || {};
  const dashboard = normalizedFilterState?.dashboard || {};
  const feed = normalizedFilterState?.feed || {};
  const selectedFeedFullPoolEnabled = isSelectedFeedFullPoolEnabled();
  const hasFeedScope = Boolean(feed.id);
  const hasPersonalDashboard = Boolean(dashboard.enabled);
  const hasSearch = Boolean(filters.search);
  const hasDate = Boolean(filters.date);
  const hasBackendScopedFilter = Boolean(filters.topic || filters.tag || filters.signal || filters.articleIds?.length);
  const hasRiskySelectedFeedFullPoolFilter = Boolean(hasDate || filters.topic || filters.tag || filters.signal || filters.articleIds?.length);

  let strategy = "global_newest_pool";
  let reason = "no feed, dashboard, search, or date filters active";
  let sourceScope = "all_feeds";
  let expectedCompleteness = "partial";
  let expectedCandidateSource = "legacy global in-memory candidate source";

  if (hasDate) {
    strategy = "date_scoped_pool";
    reason = "date filter active";
    sourceScope = hasFeedScope ? "selected_feed" : "all_feeds";
    expectedCompleteness = "partial";
    expectedCandidateSource = "legacy backend date-scoped query";
  } else if (hasFeedScope && hasPersonalDashboard) {
    strategy = "selected_feed_dashboard_full_pool";
    reason = "feed selected; dashboard active";
    sourceScope = "selected_feed";
    expectedCompleteness = "unknown";
    expectedCandidateSource = "legacy feed-scoped dashboard query";
  } else if (hasFeedScope) {
    strategy = "selected_feed_full_pool";
    reason = "feed selected; dashboard inactive";
    sourceScope = "selected_feed";
    expectedCompleteness = "unknown";
    expectedCandidateSource = "legacy selected-feed query/cache source";
  } else if (hasSearch) {
    strategy = "search_scoped_pool";
    reason = "search filter active";
    sourceScope = "all_feeds";
    expectedCompleteness = "partial";
    expectedCandidateSource = "legacy backend search-scoped query";
  } else if (hasPersonalDashboard) {
    strategy = "dashboard_targeted_pool";
    reason = "dashboard active; no feed selected";
    sourceScope = "all_feeds";
    expectedCompleteness = "targeted_partial";
    expectedCandidateSource = "legacy dashboard targeted backend query";
  } else if (hasBackendScopedFilter) {
    strategy = "backend_query_pool";
    reason = "backend-scoped advanced filter active";
    sourceScope = "all_feeds";
    expectedCompleteness = "partial";
    expectedCandidateSource = "legacy backend filtered query";
  }

  const candidateLimit = Number(candidatePoolContext?.candidateLimit) || MAX_ARTICLES_IN_MEMORY;
  const warnings = [
    "legacy execution",
    "candidate source not yet strategy driven",
    "strategy diagnostics only",
    "future phase will execute strategy",
  ];
  if (strategy === "selected_feed_full_pool" || strategy === "selected_feed_dashboard_full_pool") {
    warnings.push("feed total is not consulted by this diagnostics-only strategy");
    if (selectedFeedFullPoolEnabled && hasRiskySelectedFeedFullPoolFilter) {
      warnings.push("date/topic/tag/signal/article-id filters keep selected feed full pool on legacy execution for this phase");
    }
  }
  if (strategy === "selected_feed_paged_pool") {
    warnings.push("paged selected-feed strategy is defined for future large-feed execution only");
  }

  const resolvedStrategy = {
    strategy,
    strategyKey: `strategy:${strategy}`,
    reason,
    sourceScope,
    retrievalMode: candidatePoolContext?.retrievalMode || getRetrievalMode(normalizedFilterState),
    expectedCompleteness,
    expectedCandidateSource,
    expectedLimit: candidateLimit,
    candidateLimit,
    featureFlag: selectedFeedFullPoolEnabled ? "enabled" : "disabled",
    actualExecution: "legacy",
    notes: [
      "strategy now owns provider selection",
    ],
    warnings,
  };

  return freezeNormalizedFilterState(resolvedStrategy);
}

function resolveCandidateSource(candidateStrategy, normalizedFilterState, candidatePoolContext = null) {
  const strategy = candidateStrategy?.strategy || "global_newest_pool";
  const featureFlag = candidateStrategy?.featureFlag || (isSelectedFeedFullPoolEnabled() ? "enabled" : "disabled");
  const hasFeedScope = Boolean(normalizedFilterState?.feed?.id);
  const notes = [
    "candidate source router diagnostics only",
    "current execution still uses legacy candidate builder branches",
  ];
  let sourceType = "global_memory";
  let sourceName = "Global in-memory article snapshot";
  let sourceScope = candidateStrategy?.sourceScope || candidatePoolContext?.sourceScope || "all_feeds";
  let provider = "state.articles";
  let legacyBranch = "global-visible-articles";
  let supported = true;

  if (
    strategy === "dashboard_targeted_pool" ||
    strategy === "backend_query_pool" ||
    strategy === "search_scoped_pool" ||
    strategy === "date_scoped_pool"
  ) {
    sourceType = "backend_query";
    sourceName = "Backend article query";
    provider = "/api/articles";
    legacyBranch = "backend-query";
  } else if (strategy === "selected_feed_full_pool" || strategy === "selected_feed_dashboard_full_pool") {
    sourceType = "selected_feed_backend";
    sourceName = "Selected feed article pool";
    sourceScope = "selected_feed";
    provider = "/api/articles";
    legacyBranch = featureFlag === "enabled" ? "selected-feed-full-pool" : "backend-query";
    if (featureFlag !== "enabled") {
      notes.push("selected feed full pool feature flag is disabled; legacy backend query branch remains active");
    }
  } else if (strategy === "selected_feed_paged_pool") {
    sourceType = "selected_feed_backend";
    sourceName = "Paged selected feed article pool";
    sourceScope = "selected_feed";
    provider = "/api/articles";
    legacyBranch = "backend-query";
    supported = false;
    notes.push("paged selected feed source is planned but not executed in this phase");
  } else if (hasFeedScope) {
    sourceType = "backend_query";
    sourceName = "Feed-scoped backend article query";
    sourceScope = "selected_feed";
    provider = "/api/articles";
    legacyBranch = "backend-query";
  }

  return freezeNormalizedFilterState({
    sourceType,
    sourceName,
    sourceScope,
    executionMode: "legacy",
    provider,
    legacyBranch,
    featureFlag,
    supported,
    notes,
  });
}

function getExpectedCandidateStrategy(normalizedFilterState) {
  const hasFeedScope = Boolean(normalizedFilterState?.feed?.id);
  const hasPersonalDashboard = Boolean(normalizedFilterState?.dashboard?.enabled);

  if (hasFeedScope && hasPersonalDashboard) {
    return "full_selected_feed_pool_then_dashboard_filter";
  }
  if (hasFeedScope) {
    return "full_selected_feed_pool";
  }
  if (hasPersonalDashboard) {
    return "targeted_dashboard_candidate_pool";
  }
  return "global_newest_pool";
}

function getRetrievalMode(normalizedFilterState) {
  const hasFeedScope = Boolean(normalizedFilterState?.feed?.id);
  const hasPersonalDashboard = Boolean(normalizedFilterState?.dashboard?.enabled);

  if (hasFeedScope && hasPersonalDashboard) {
    return "feed_dashboard_targeted";
  }
  if (hasFeedScope) {
    return "feed";
  }
  if (hasPersonalDashboard) {
    return "dashboard_targeted";
  }
  return "global";
}

function getActualCandidateStrategy(branch, normalizedFilterState) {
  const hasFeedScope = Boolean(normalizedFilterState?.feed?.id);
  const hasPersonalDashboard = Boolean(normalizedFilterState?.dashboard?.enabled);

  if (branch === "backend-query" || branch === "backend-query-loading") {
    if (hasFeedScope && hasPersonalDashboard) {
      return "current_feed_scoped_targeted_backend_query";
    }
    if (hasPersonalDashboard) {
      return "current_targeted_backend_query";
    }
    if (hasFeedScope) {
      return "current_feed_backend_query";
    }
    return "current_filtered_backend_query";
  }
  if (branch === "selected-feed-fallback") {
    return "current_grouped_feed_cache_pool";
  }
  if (branch === "selected-feed-full-pool" || branch === "selected-feed-full-pool-loading") {
    return "selected_feed_full_pool_feature_flag";
  }
  if (branch === "date-filter") {
    return "current_date_filtered_in_memory_pool";
  }
  if (branch === "global-visible-articles") {
    return "current_global_in_memory_pool";
  }
  return "unknown";
}

function getCandidatePoolContextWarnings(context) {
  const warnings = [];
  if (!context) {
    return warnings;
  }

  if (
    context.expectedCandidateStrategy === "full_selected_feed_pool_then_dashboard_filter" &&
    context.actualCandidateStrategy === "current_feed_scoped_targeted_backend_query"
  ) {
    warnings.push("Pipeline v2 would prefer the full selected feed pool before dashboard filtering; current code uses the existing feed-scoped backend query path.");
  }
  if (
    context.expectedCandidateStrategy === "full_selected_feed_pool" &&
    context.actualCandidateStrategy === "current_feed_backend_query"
  ) {
    warnings.push("Pipeline v2 would prefer an explicit full selected feed pool; current code uses the existing backend query path and configured candidate limit.");
  }
  if (
    context.expectedCandidateStrategy === "global_newest_pool" &&
    context.actualCandidateStrategy === "current_filtered_backend_query"
  ) {
    warnings.push("Current advanced filters use the backend query path before local pipeline stages.");
  }
  if (context.branch === "selected-feed-fallback") {
    warnings.push("Selected feed fallback uses grouped feed cache instead of backend retrieval.");
  }
  if (context.branch === "selected-feed-full-pool" || context.branch === "selected-feed-full-pool-loading") {
    warnings.push("Selected feed full pool is executing behind a feature flag.");
  }
  return warnings;
}

function createCandidatePoolContext(normalizedFilterState, options = {}) {
  const branch = options.branch || "unknown";
  const context = {
    branch,
    retrievalMode: getRetrievalMode(normalizedFilterState),
    sourceScope: normalizedFilterState?.feed?.id ? "selected_feed" : "all_feeds",
    feedId: normalizedFilterState?.feed?.id || "",
    feedName: normalizedFilterState?.feed?.name || "",
    hasFeedScope: Boolean(normalizedFilterState?.feed?.id),
    hasPersonalDashboard: Boolean(normalizedFilterState?.dashboard?.enabled),
    hasAdvancedFilters: hasNormalizedAdvancedFilters(normalizedFilterState),
    expectedCandidateStrategy: getExpectedCandidateStrategy(normalizedFilterState),
    actualCandidateStrategy: getActualCandidateStrategy(branch, normalizedFilterState),
    candidateLimit: MAX_ARTICLES_IN_MEMORY,
    backendRequests: [],
    cacheKey: "",
    warnings: [],
  };

  context.warnings = getCandidatePoolContextWarnings(context);
  return context;
}

function updateCandidatePoolContext(diagnostics, updates = {}) {
  if (!diagnostics?.enabled || !diagnostics.candidatePoolContext) {
    return;
  }

  Object.assign(diagnostics.candidatePoolContext, updates);
  if (Object.prototype.hasOwnProperty.call(updates, "branch")) {
    diagnostics.candidatePoolContext.actualCandidateStrategy = getActualCandidateStrategy(
      diagnostics.candidatePoolContext.branch,
      diagnostics.normalizedFilterState
    );
  }
  diagnostics.candidatePoolContext.warnings = getCandidatePoolContextWarnings(diagnostics.candidatePoolContext);
}

function normalizeCandidateProviderResult(resolved = {}) {
  const articles = Array.isArray(resolved.articles) ? resolved.articles : [];
  const candidatePool = Array.isArray(resolved.candidatePool) ? resolved.candidatePool : articles;
  const candidateSource = Array.isArray(resolved.candidateSource) ? resolved.candidateSource : candidatePool;
  const filteredRawArticles = Array.isArray(resolved.filteredRawArticles) ? resolved.filteredRawArticles : articles;
  const groupedArticles = Array.isArray(resolved.groupedArticles) ? resolved.groupedArticles : articles;
  const branch = resolved.branch || "unknown";
  const backendRequests = resolved.backendRequests || [];
  const groupedCount = Number(resolved.groupedArticlesCount) || groupedArticles.length;

  return {
    articles,
    groupedArticles,
    candidateSource,
    candidatePool,
    filteredRawArticles,
    groupedArticlesCount: groupedCount,
    feedDebugRawMatches: Array.isArray(resolved.feedDebugRawMatches) ? resolved.feedDebugRawMatches : [],
    feedDebugAfterRelevanceMatches: Array.isArray(resolved.feedDebugAfterRelevanceMatches)
      ? resolved.feedDebugAfterRelevanceMatches
      : [],
    feedRenderFilteredCount: Number(resolved.feedRenderFilteredCount) || 0,
    feedRenderGroupedCount: Number(resolved.feedRenderGroupedCount) || 0,
    branch,
    retrievalMode: resolved.retrievalMode || "",
    sourceScope: resolved.sourceScope || "",
    backendRequests,
    cacheKey: resolved.cacheKey || "",
    cacheHit: Boolean(resolved.cacheHit),
    candidateLimit: resolved.candidateLimit || MAX_ARTICLES_IN_MEMORY,
    warnings: Array.isArray(resolved.warnings) ? resolved.warnings.slice() : [],
    diagnostics: resolved.diagnostics || {},
    expectedTotal: Number.isFinite(Number(resolved.expectedTotal)) ? Number(resolved.expectedTotal) : null,
    partial: Boolean(resolved.partial),
    candidateSourceCount: candidateSource.length,
    candidateCount: candidatePool.length,
    filteredCount: filteredRawArticles.length,
    groupedCount,
    pending: Boolean(resolved.pending),
    notes: [
      "candidate builder is provider-result normalizer only",
      "provider result normalized by candidate builder",
      ...(Array.isArray(resolved.notes) ? resolved.notes : []),
    ],
  };
}

function resolveCandidateProvider(candidateStrategy, candidateSource, normalizedFilterState, candidatePoolContext) {
  const strategy = String(candidateStrategy?.strategy || "");
  const sourceType = String(candidateSource?.sourceType || "");
  const legacyBranch = String(candidateSource?.legacyBranch || candidatePoolContext?.branch || "");
  let providerId = "global_memory_provider";
  let providerType = "memory";

  if (
    sourceType === "selected_feed_backend" ||
    strategy === "selected_feed_full_pool" ||
    strategy === "selected_feed_dashboard_full_pool" ||
    strategy === "selected_feed_paged_pool" ||
    legacyBranch === "selected-feed-fallback" ||
    normalizedFilterState?.feed?.id
  ) {
    providerId = "selected_feed_provider";
    providerType = "backend_or_cache";
  } else if (
    sourceType === "backend_query" ||
    legacyBranch === "backend-query" ||
    strategy === "backend_query_pool" ||
    strategy === "dashboard_targeted_pool" ||
    strategy === "search_scoped_pool"
  ) {
    providerId = "backend_query_provider";
    providerType = "backend";
  } else if (
    strategy === "date_scoped_pool" ||
    sourceType === "date_memory" ||
    legacyBranch === "date-filter" ||
    normalizedFilterState?.filters?.date
  ) {
    providerId = "date_filter_provider";
    providerType = "memory";
  }

  return Object.freeze({
    providerId,
    providerType,
    executionMode: "legacy",
    legacyImplementation: legacyBranch || strategy || "global-visible-articles",
    supported: true,
    pending: false,
    notes: Object.freeze([
      "candidate provider metadata only",
      "candidate provider owns legacy retrieval execution",
      "provider executes supplied strategy plan",
      "provider dispatcher owns retrieval branch execution",
      ...(providerId === "selected_feed_provider" ? ["selected feed provider extracted"] : []),
      ...(providerId === "backend_query_provider" ? [
        "backend query provider decomposed into named stages",
        "backend query behavior unchanged",
      ] : []),
      ...(providerId === "global_memory_provider" ? ["global memory provider extracted"] : []),
      ...(providerId === "date_filter_provider" ? ["date provider extracted"] : []),
      "legacy retrieval implementation remains unchanged",
    ]),
  });
}

function summarizeCandidateProvider(candidateProvider) {
  if (!candidateProvider) {
    return null;
  }

  return {
    providerId: candidateProvider.providerId || "",
    providerType: candidateProvider.providerType || "",
    executionMode: candidateProvider.executionMode || "legacy",
    legacyImplementation: candidateProvider.legacyImplementation || "",
    supported: candidateProvider.supported !== false,
    pending: Boolean(candidateProvider.pending),
    notes: Array.isArray(candidateProvider.notes) ? candidateProvider.notes.slice() : [],
  };
}

function buildStrategyExecutionPlan(candidateStrategy, candidateProvider, normalizedFilterState, candidatePoolContext, options = {}) {
  const activeFeedId = options.activeFeedId || normalizedFilterState?.feed?.id || "";
  const useBackendQuery = Boolean(options.useBackendQuery);
  const hasSelectedFeedFullPoolAttempt = Boolean(
    activeFeedId &&
      isSelectedFeedFullPoolEnabled() &&
      !normalizedFilterState?.filters?.date
  );
  let dispatchMode = "global_memory";
  let executionReason = "global memory candidate source";
  let selectedProvider = "global_memory_provider";

  if (hasSelectedFeedFullPoolAttempt) {
    dispatchMode = "selected_feed_full_pool_then_legacy";
    selectedProvider = "selected_feed_provider";
    executionReason = "selected feed full pool feature flag can attempt before legacy provider dispatch";
  } else if (useBackendQuery) {
    dispatchMode = "backend_query";
    selectedProvider = "backend_query_provider";
    executionReason = "strategy selected backend query provider";
  } else if (activeFeedId && !normalizedFilterState?.filters?.date) {
    dispatchMode = "selected_feed";
    selectedProvider = "selected_feed_provider";
    executionReason = "strategy selected selected-feed provider";
  } else if (normalizedFilterState?.filters?.date) {
    dispatchMode = "date_filter";
    selectedProvider = "date_filter_provider";
    executionReason = "strategy selected date filter provider";
  }

  return Object.freeze({
    strategy: candidateStrategy?.strategy || "",
    provider: selectedProvider,
    retrievalMode: candidateStrategy?.retrievalMode || candidatePoolContext?.retrievalMode || "",
    sourceScope: candidateStrategy?.sourceScope || candidatePoolContext?.sourceScope || "",
    executionPlan: dispatchMode,
    expectedLimit: Number(candidateStrategy?.expectedLimit || candidateStrategy?.candidateLimit || candidatePoolContext?.candidateLimit || 0),
    pendingAllowed: dispatchMode === "backend_query" || dispatchMode === "selected_feed_full_pool_then_legacy",
    selectedStrategy: candidateStrategy?.strategy || "",
    selectedProvider,
    executionAuthority: "candidate_strategy",
    executionReason,
    dispatchMode,
    notes: Object.freeze([
      "strategy now owns provider selection",
      "strategy execution plan owns provider selection",
    ]),
    warnings: Object.freeze([]),
  });
}

