function recordPipelineCount(diagnostics, stage, count) {
  if (!diagnostics?.enabled || !Object.prototype.hasOwnProperty.call(diagnostics.counts, stage)) {
    return;
  }
  diagnostics.counts[stage] = Number(count) || 0;
}

function recordDiagnosticsReplayMetadata(diagnostics, metadata = {}) {
  if (!diagnostics?.enabled) {
    return;
  }
  diagnostics.diagnosticsReplay = {
    ...(diagnostics.diagnosticsReplay || {}),
    ...metadata,
    traceStoreSize: diagnostics.filterDecisionTraceMap instanceof Map
      ? diagnostics.filterDecisionTraceMap.size
      : 0,
    heavyDiagnosticsEvaluated: Number(diagnostics.diagnosticsPerformance?.heavyDiagnosticsEvaluated) || 0,
    heavyDiagnosticsSkipped: Number(diagnostics.diagnosticsPerformance?.heavyDiagnosticsSkipped) || 0,
  };
}

function getPipelineDiagnosticsArchitecture(diagnostics) {
  const branch = String(diagnostics?.branch || "");
  const backendQueryBranch = branch === "backend-query" || branch === "backend-query-loading";
  const pipelineExecutorExpectedForBranch = true;
  const pipelineExecutorPresent = Boolean(diagnostics?.pipelineExecutor);
  const candidateBuilderResultPresent = Boolean(diagnostics?.candidateBuilderResult);
  const pipelineOrchestratorPresent = Boolean(diagnostics?.pipelineOrchestrator);
  const missingPipelineFields = [
    !pipelineOrchestratorPresent ? "pipelineOrchestrator" : "",
    !candidateBuilderResultPresent ? "candidateBuilderResult" : "",
    !pipelineExecutorPresent ? "pipelineExecutor" : "",
  ].filter(Boolean);

  return {
    backendQueryBypassesPipelineExecutor: false,
    pipelineExecutorExpectedForBranch,
    pipelineExecutorPresent,
    candidateBuilderResultPresent,
    pipelineOrchestratorPresent,
    missingPipelineFields,
    diagnosticsAuthorityForBranch: missingPipelineFields.length
      ? [
          "backendProviderStages",
          "filterPipeline",
          "diagnosticsReplay",
        ]
      : [
          "pipelineOrchestrator",
          "candidateBuilderResult",
          "pipelineExecutor",
          "filterPipeline",
          "diagnosticsReplay",
        ],
    summaryPopulationSource: diagnostics?.diagnosticsReplay?.diagnosticsInputSource || "filterDecisionTraceMap",
    reasonPipelineExecutorIsNull: !pipelineExecutorPresent
      ? backendQueryBranch
        ? "unexpected: backend-query should run through executePipelineOrchestrator; check diagnosticsReplay for an early diagnostics replay failure"
        : "unexpected: renderArticles calls executePipelineOrchestrator for all article renders"
      : "",
    notes: [
      "backend-query is expected to run through Pipeline Executor in the current architecture",
      "filterPipeline can be recorded before later executor/orchestrator summaries if diagnostics replay aborts early",
      "production filtering remains legacy-authoritative",
    ],
  };
}

function addFilterPipelineNote(diagnostics, note) {
  if (!diagnostics?.enabled || !note) {
    return;
  }
  diagnostics.notes.push(note);
}

function setFilterPipelineBranch(diagnostics, branch) {
  if (!diagnostics?.enabled) {
    return;
  }
  diagnostics.branch = branch || diagnostics.branch;
  updateCandidatePoolContext(diagnostics, { branch: diagnostics.branch });
}

function recordPipelineRejection(diagnostics, stage, category, article, reason = "") {
  if (!diagnostics?.enabled || !diagnostics.rejections?.[stage]) {
    return;
  }
  const bucket = diagnostics.rejections[stage];
  const normalizedCategory = Object.prototype.hasOwnProperty.call(bucket, category) ? category : "unknown";
  bucket[normalizedCategory] += 1;

  const examplesByCategory = diagnostics.rejectionExamples[stage];
  if (!examplesByCategory[normalizedCategory]) {
    examplesByCategory[normalizedCategory] = [];
  }
  if (examplesByCategory[normalizedCategory].length < 10) {
    examplesByCategory[normalizedCategory].push({
      title: article?.title || "Untitled article",
      reason: reason || normalizedCategory,
    });
  }
}

function getFilterDecisionTraceArticleId(article) {
  const rawId =
    article?.id ||
    article?._id ||
    article?.articleId ||
    article?.canonicalLink ||
    article?.link ||
    article?.url ||
    article?.title ||
    "";
  return String(rawId || "");
}

function reserveHeavyDiagnosticsSlot(diagnostics) {
  const performance = diagnostics?.diagnosticsPerformance;
  if (!performance?.enabled) {
    return false;
  }
  const limit = Math.max(0, Number(performance.heavyDiagnosticsLimit) || 0);
  if (performance.heavyDiagnosticsEvaluated < limit) {
    performance.heavyDiagnosticsEvaluated += 1;
    return true;
  }
  performance.heavyDiagnosticsSkipped += 1;
  return false;
}

function isHeavyDiagnosticsTrace(trace) {
  return Boolean(trace?.heavyDiagnosticsEnabled);
}

function getHeavyDiagnosticsTraces(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return [];
  }
  return Array.from(diagnostics.filterDecisionTraceMap.values()).filter(isHeavyDiagnosticsTrace);
}

function getFilterDecisionTrace(diagnostics, article) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap || !article) {
    return null;
  }

  const articleId = getFilterDecisionTraceArticleId(article);
  if (!articleId) {
    return null;
  }

  if (!diagnostics.filterDecisionTraceMap.has(articleId)) {
    const heavyDiagnosticsEnabled = reserveHeavyDiagnosticsSlot(diagnostics);
    const articleEvidence = heavyDiagnosticsEnabled
      ? buildArticleEvidence(article)
      : {
          articleId,
          skipped: true,
          reason: "performance_guard",
          evidence: {},
        };
    const evidenceParity = heavyDiagnosticsEnabled
      ? compareArticleEvidenceParity(article)
      : {
          articleId,
          title: article?.title || "Untitled article",
          skipped: true,
          reason: "performance_guard",
          parityWarnings: [],
          evidenceSummary: {},
        };
    const v3Decision = heavyDiagnosticsEnabled
      ? buildV3DecisionDiagnostics(article, { articleEvidence })
      : null;
    const identityIssuance = heavyDiagnosticsEnabled
      ? getIdentityLifecyclePatternMatches(article, articleEvidence)
      : null;
    const identityFraudVerification = heavyDiagnosticsEnabled
      ? getIdentityFraudVerificationPatternMatches(article, articleEvidence)
      : null;
    const identityBorderControl = heavyDiagnosticsEnabled
      ? getIdentityBorderControlPatternMatches(article, articleEvidence)
      : null;
    const sharedSecurity = heavyDiagnosticsEnabled
      ? getSharedSecurityPatternMatches(article, articleEvidence)
      : null;
    const sharedSecurityBridge = heavyDiagnosticsEnabled
      ? getSharedSecurityBridgeDecision(article)
      : null;
    const professionalDecision = heavyDiagnosticsEnabled
      ? buildProfessionalDecisionDiagnostics(article, {
          articleEvidence,
          confidenceDiagnostics: v3Decision?.confidenceDiagnostics,
        })
      : null;
    const passportDecision = heavyDiagnosticsEnabled
      ? buildPassportDecisionDiagnostics(article, {
          articleEvidence,
          confidenceDiagnostics: v3Decision?.confidenceDiagnostics,
        })
      : null;
    const passportDecisionTree = heavyDiagnosticsEnabled
      ? tracePassportDecisionTree(article)
      : null;
    const passportDecisionV3 = heavyDiagnosticsEnabled
      ? PassportDecisionEngineV3(article, { articleEvidence })
      : null;
    const passportDecisionComparison = heavyDiagnosticsEnabled
      ? comparePassportDecisionV3WithLegacy(passportDecisionV3, passportDecisionTree)
      : null;
    const passportProfessionalAlignment = heavyDiagnosticsEnabled
      ? getPassportProfessionalAlignmentDiagnostics(article, articleEvidence)
      : null;
    const idCardDecision = heavyDiagnosticsEnabled
      ? evaluateIdCardDecisionRules(article)
      : null;
    const residencePermitDecision = heavyDiagnosticsEnabled
      ? evaluateResidencePermitDecisionRules(article)
      : null;
    const visaDecision = heavyDiagnosticsEnabled
      ? evaluateVisaDecisionRules(article)
      : null;
    const selectedIdentityInterestsForTrace = getSelectedIdentityDocumentSubinterests();
    const visaNoise = heavyDiagnosticsEnabled && selectedIdentityInterestsForTrace.includes("visas")
      ? getVisaNoiseDiagnostics(article, {
          articleEvidence,
          visaDecision,
        })
      : null;
    const driverLicenseDecision = heavyDiagnosticsEnabled
      ? evaluateDriverLicenseDecisionRules(article)
      : null;
    const driverLicenseNoise = heavyDiagnosticsEnabled
      ? getDriverLicenseNoiseDiagnostics(article, {
          articleEvidence,
          driverLicenseDecision,
        })
      : null;
    diagnostics.filterDecisionTraceMap.set(articleId, {
      articleId,
      title: article?.title || "Untitled article",
      heavyDiagnosticsEnabled,
      enteredPipeline: {
        renderId: diagnostics.renderId,
        timestamp: diagnostics.timestamp,
        branch: diagnostics.branch || "unknown",
      },
      evidenceDiagnostics: articleEvidence,
      evidenceParityDiagnostics: evidenceParity,
      identityIssuanceDiagnostics: identityIssuance,
      identityFraudVerificationDiagnostics: identityFraudVerification,
      identityBorderControlDiagnostics: identityBorderControl,
      sharedSecurityDiagnostics: sharedSecurity,
      sharedSecurityBridgeDiagnostics: sharedSecurityBridge,
      v3DecisionDiagnostics: v3Decision,
      professionalDecisionDiagnostics: professionalDecision,
      passportDecisionDiagnostics: passportDecision,
      passportDecisionTreeDiagnostics: passportDecisionTree,
      passportDecisionV3Diagnostics: passportDecisionV3,
      passportDecisionComparison,
      passportProfessionalAlignmentDiagnostics: passportProfessionalAlignment,
      idCardDecisionDiagnostics: idCardDecision,
      residencePermitDecisionDiagnostics: residencePermitDecision,
      visaDecisionDiagnostics: visaDecision,
      visaNoiseDiagnostics: visaNoise,
      driverLicenseDecisionDiagnostics: driverLicenseDecision,
      driverLicenseNoiseDiagnostics: driverLicenseNoise,
      stages: [],
      finalResult: "",
      finalReason: "",
    });
  }

  return diagnostics.filterDecisionTraceMap.get(articleId);
}

function recordFilterDecisionStage(diagnostics, article, stageEntry = {}) {
  const trace = getFilterDecisionTrace(diagnostics, article);
  if (!trace || Object.isFrozen(trace)) {
    return;
  }

  const metadata = stageEntry.metadata && typeof stageEntry.metadata === "object" ? { ...stageEntry.metadata } : {};
  if (!metadata.evidenceBuilder && diagnostics?.enabled && isHeavyDiagnosticsTrace(trace)) {
    metadata.evidenceBuilder = getCompactArticleEvidenceDiagnosticsFromEvidence(article, trace.evidenceDiagnostics);
  }

  trace.stages.push({
    stage: stageEntry.stage || "unknown",
    result: stageEntry.result || "unknown",
    reason: stageEntry.reason || "",
    score: Number.isFinite(stageEntry.score) ? stageEntry.score : null,
    notes: Array.isArray(stageEntry.notes) ? stageEntry.notes.filter(Boolean) : [],
    metadata,
  });
}

function finalizeFilterDecisionTrace(diagnostics, article, finalResult, finalReason) {
  const trace = getFilterDecisionTrace(diagnostics, article);
  if (!trace || Object.isFrozen(trace)) {
    return;
  }

  trace.finalResult = finalResult || trace.finalResult || "survived";
  trace.finalReason = finalReason || trace.finalReason || "article survived traced filter pipeline";
}

function freezeFilterDecisionTrace(trace) {
  if (!trace || Object.isFrozen(trace)) {
    return trace;
  }

  if (trace.v3DecisionDiagnostics && typeof trace.v3DecisionDiagnostics === "object") {
    trace.v3DecisionDiagnostics.legacyComparison = {
      finalResult: trace.finalResult || "survived",
      finalReason: trace.finalReason || "article survived traced filter pipeline",
      personalDashboardPassed: (trace.stages || []).some((stage) =>
        stage.stage === "personal_dashboard" && stage.result === "passed"
      ),
      advancedFiltersPassed: (trace.stages || []).some((stage) =>
        stage.stage === "advanced_filters" && stage.result === "passed"
      ),
    };
  }
  if (trace.heavyDiagnosticsEnabled && trace.v3DecisionDiagnostics) {
    trace.decisionParityDiagnostics = compareLegacyDecisionWithV3Decision(trace);
  }
  if (trace.heavyDiagnosticsEnabled && trace.professionalDecisionDiagnostics) {
    finalizeProfessionalDecisionDiagnostics(trace);
  }
  if (trace.heavyDiagnosticsEnabled && trace.passportDecisionDiagnostics) {
    finalizePassportDecisionDiagnostics(trace);
  }

  const frozenStages = (Array.isArray(trace.stages) ? trace.stages : []).map((stage) =>
    Object.freeze({
      ...stage,
      notes: Object.freeze(Array.isArray(stage.notes) ? stage.notes.slice() : []),
      metadata: Object.freeze(stage.metadata && typeof stage.metadata === "object" ? { ...stage.metadata } : {}),
    })
  );

  return Object.freeze({
    articleId: trace.articleId,
    title: trace.title,
    heavyDiagnosticsEnabled: Boolean(trace.heavyDiagnosticsEnabled),
    enteredPipeline: Object.freeze({
      ...(trace.enteredPipeline || {}),
    }),
    evidenceDiagnostics: Object.freeze(trace.evidenceDiagnostics || {}),
    evidenceParityDiagnostics: Object.freeze(trace.evidenceParityDiagnostics || {}),
    identityIssuanceDiagnostics: Object.freeze(trace.identityIssuanceDiagnostics || {}),
    identityFraudVerificationDiagnostics: Object.freeze(trace.identityFraudVerificationDiagnostics || {}),
    identityBorderControlDiagnostics: Object.freeze(trace.identityBorderControlDiagnostics || {}),
    sharedSecurityDiagnostics: Object.freeze(trace.sharedSecurityDiagnostics || {}),
    sharedSecurityBridgeDiagnostics: Object.freeze(trace.sharedSecurityBridgeDiagnostics || {}),
    v3DecisionDiagnostics: Object.freeze(trace.v3DecisionDiagnostics || {}),
    decisionParityDiagnostics: Object.freeze(trace.decisionParityDiagnostics || {}),
    professionalDecisionDiagnostics: Object.freeze(trace.professionalDecisionDiagnostics || {}),
    passportDecisionDiagnostics: Object.freeze(trace.passportDecisionDiagnostics || {}),
    passportDecisionTreeDiagnostics: Object.freeze(trace.passportDecisionTreeDiagnostics || {}),
    passportDecisionV3Diagnostics: Object.freeze(trace.passportDecisionV3Diagnostics || {}),
    passportDecisionComparison: Object.freeze(trace.passportDecisionComparison || {}),
    passportProfessionalAlignmentDiagnostics: Object.freeze(trace.passportProfessionalAlignmentDiagnostics || {}),
    idCardDecisionDiagnostics: Object.freeze(trace.idCardDecisionDiagnostics || {}),
    residencePermitDecisionDiagnostics: Object.freeze(trace.residencePermitDecisionDiagnostics || {}),
    visaDecisionDiagnostics: Object.freeze(trace.visaDecisionDiagnostics || {}),
    visaNoiseDiagnostics: Object.freeze(trace.visaNoiseDiagnostics || {}),
    driverLicenseDecisionDiagnostics: Object.freeze(trace.driverLicenseDecisionDiagnostics || {}),
    driverLicenseNoiseDiagnostics: Object.freeze(trace.driverLicenseNoiseDiagnostics || {}),
    stages: Object.freeze(frozenStages),
    finalResult: trace.finalResult || "survived",
    finalReason: trace.finalReason || "article survived traced filter pipeline",
  });
}

function finalizeFilterDecisionTraces(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return;
  }

  diagnostics.filterDecisionTraceMap.forEach((trace, articleId) => {
    if (trace.enteredPipeline && !Object.isFrozen(trace.enteredPipeline)) {
      trace.enteredPipeline.branch = diagnostics.branch || trace.enteredPipeline.branch || "unknown";
    }
    if (!trace.finalResult) {
      trace.finalResult = "survived";
      trace.finalReason = "article survived traced filter pipeline";
    }
    diagnostics.filterDecisionTraceMap.set(articleId, freezeFilterDecisionTrace(trace));
  });
}

function getFilterDecisionTraceSummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = Array.from(diagnostics.filterDecisionTraceMap.values());
  const tracedArticles = traces.length;
  const rejectedArticles = traces.filter((trace) => trace.finalResult === "rejected").length;
  const survivingArticles = tracedArticles - rejectedArticles;
  const totalStagesVisited = traces.reduce((sum, trace) => sum + (Array.isArray(trace.stages) ? trace.stages.length : 0), 0);

  return {
    tracedArticles,
    rejectedArticles,
    survivingArticles,
    averageStagesVisited: tracedArticles ? Number((totalStagesVisited / tracedArticles).toFixed(2)) : 0,
  };
}

