function getMatchedEvidenceIds(articleEvidence, evidenceGroup, ids = []) {
  const normalizedIds = ids.map((id) => normalizeEvidenceId(id)).filter(Boolean);
  if (!normalizedIds.length) {
    return [];
  }
  return Array.from(new Set(
    getEvidenceEntriesForGroup(articleEvidence, evidenceGroup)
      .map((entry) => normalizeEvidenceId(entry?.id || ""))
      .filter((id) => normalizedIds.includes(id))
  ));
}

function summarizeArticleEvidenceForParity(articleEvidence) {
  const evidence = articleEvidence?.evidence || {};
  return {
    domainObjects: evidence.domainObjects?.length || 0,
    documentTypes: evidence.documentTypes?.length || 0,
    vendors: evidence.vendors?.length || 0,
    materials: evidence.materials?.length || 0,
    technologies: evidence.technologies?.length || 0,
    eventSignals: evidence.eventSignals?.length || 0,
    professionalSignals: evidence.professionalSignals?.length || 0,
    noiseSignals: evidence.noiseSignals?.length || 0,
    sourceEvidence: evidence.sourceEvidence?.length || 0,
  };
}

function normalizeDiagnosticsText(value) {
  return String(value || "").trim().toLowerCase();
}

function getCompactEvidenceEntriesForDiagnostics(articleEvidence, evidenceGroup, ids = null) {
  const normalizedIds = Array.isArray(ids) ? ids.map((id) => normalizeEvidenceId(id)).filter(Boolean) : null;
  return getEvidenceEntriesForGroup(articleEvidence, evidenceGroup)
    .filter((entry) => !normalizedIds || normalizedIds.includes(normalizeEvidenceId(entry?.id || "")))
    .map((entry) => ({
      id: entry?.id || "",
      term: entry?.term || "",
      matchedTerm: entry?.matchedTerm || entry?.term || "",
      locations: Array.isArray(entry?.locations) ? entry.locations.slice() : [],
      strength: entry?.strength || "",
      sourceHelper: entry?.sourceHelper || "",
    }));
}

function getIdCardLegacyScoreEvidenceSummary(article, legacyIdCardsBoost, legacyIdentitySubinterest) {
  const profile = calculateIdentityProfileScore(article, "id_cards");
  const signals = getIdentityDocumentInterestSignals(article);
  return {
    idCardsScore: Number(legacyIdCardsBoost?.score) || 0,
    idCardsMatched: Boolean(legacyIdCardsBoost?.matched),
    profileScore: Number(profile?.score) || 0,
    profileMatchedStrong: Array.isArray(profile?.matchedStrong) ? profile.matchedStrong.slice() : [],
    profileMatchedMedium: Array.isArray(profile?.matchedMedium) ? profile.matchedMedium.slice() : [],
    profileMatchedWeak: Array.isArray(profile?.matchedWeak) ? profile.matchedWeak.slice() : [],
    subinterestScore: Number(legacyIdentitySubinterest?.score) || 0,
    bestSelectedScore: Number(legacyIdentitySubinterest?.bestSelectedScore) || 0,
    matchedSubinterest: legacyIdentitySubinterest?.matchedSubinterest || "",
    selectedSubinterest: legacyIdentitySubinterest?.selectedSubinterest || "",
    signalCounts: {
      idCardHits: Number(signals?.idCardHits || 0),
      polycarbonateHits: Number(signals?.polycarbonateHits || 0),
      issuanceHits: Number(signals?.issuanceHits || 0),
      passportHits: Number(signals?.passportHits || 0),
      noisyHits: Number(signals?.noisyHits || 0),
    },
  };
}

function getIdCardEvidenceGapReason(legacySummary, explicitEvidence, relatedIdentityEvidence, weakEvidence) {
  if (explicitEvidence.length) {
    return "explicit_id_card_evidence_selected";
  }
  if (weakEvidence.length) {
    return "weak_or_indirect_id_card_evidence_selected";
  }
  const genericProfileTerms = [
    ...(legacySummary.profileMatchedMedium || []),
    ...(legacySummary.profileMatchedWeak || []),
  ].filter((term) => ["identity documents", "identity document"].includes(normalizeDiagnosticsText(term)));
  if (relatedIdentityEvidence.length && genericProfileTerms.length) {
    return "legacy_score_from_generic_identity_profile_terms";
  }
  if (relatedIdentityEvidence.length && legacySummary.signalCounts?.idCardHits > 0) {
    return "legacy_id_card_hits_not_mapped_to_explicit_evidence";
  }
  if (relatedIdentityEvidence.length) {
    return "generic_identity_evidence_selected";
  }
  if ((legacySummary.idCardsScore || 0) > 0) {
    return "legacy_positive_score_without_selected_id_card_evidence";
  }
  return "no_id_card_gap";
}

function getIdCardEvidenceGapExplanation(article, articleEvidence, legacyIdCardsBoost, legacyIdentitySubinterest) {
  const explicitEvidence = getCompactEvidenceEntriesForDiagnostics(
    articleEvidence,
    "documentTypes",
    EXPLICIT_ID_CARD_EVIDENCE_IDS
  );
  const relatedIdentityEvidence = getCompactEvidenceEntriesForDiagnostics(articleEvidence, "documentTypes", [
    "identity_documents",
    "identity_document",
    "secure_documents",
  ]);
  const weakEvidence = getCompactEvidenceEntriesForDiagnostics(articleEvidence, "documentTypes", [
    "card_issuance",
    "polycarbonate_id",
    "identity_card_design",
  ]);
  const legacyEvidence = getIdCardLegacyScoreEvidenceSummary(article, legacyIdCardsBoost, legacyIdentitySubinterest);
  const ruleSetDecision = evaluateIdCardDecisionRules(article);

  return {
    legacyEvidence,
    selectedRuleSetEvidence: {
      documentType: ruleSetDecision.documentType,
      matchedRuleId: ruleSetDecision.matchedRuleId,
      rejected: Boolean(ruleSetDecision.rejected),
      rejectionCategory: ruleSetDecision.rejectionCategory || "",
      rejectionReason: ruleSetDecision.rejectionReason || "",
      matchedRuleEvidence: ruleSetDecision.matchedRule?.evidence || {},
      matchedRuleScoreBreakdown: ruleSetDecision.matchedRule?.scoreBreakdown || {},
    },
    selectedEvidence: {
      explicitIdCardEvidence: explicitEvidence,
      relatedIdentityEvidence,
      weakOrIndirectIdCardEvidence: weakEvidence,
    },
    reason: getIdCardEvidenceGapReason(legacyEvidence, explicitEvidence, relatedIdentityEvidence, weakEvidence),
    notes: [
      "diagnostics only",
      "legacy filtering remains authoritative",
      "ID Card evidence explanation compares legacy scoring signals with selected Evidence Builder entries",
    ],
  };
}

function compareArticleEvidenceParity(article) {
  const articleEvidence = buildArticleEvidence(article);
  const evidenceSummary = summarizeArticleEvidenceForParity(articleEvidence);
  const legacyIdCardsBoost = computePersonalInterestBoost(article, "id_cards");
  const legacyIdentitySubinterest = getIdentityDocumentSubinterestScore(article, ["id_cards"]);
  const legacyKeesingIdentityRelevance = getKeesingIdentityRelevance(article);
  const legacyHighConfidencePassportAssessment = getHighConfidencePassportAssessment(article);
  const legacyIdentityDocumentRelevance = getIdentityDocumentRelevance(article);
  const legacyUiRelevant = isUiRelevantIntelligenceArticle(article);
  const legacyShouldRejectPassport = shouldRejectPassportArticle(article);
  const legacyHardPassportNoise = isHardPassportNoise(article);
  const legacyLowRelevancePassport = isLowRelevancePassportArticle(article);
  const legacyProfessionalIdentityRescue = shouldRescueProfessionalIdentityArticle(article);
  const passportProfessionalAlignment = getPassportProfessionalAlignmentDiagnostics(article, articleEvidence);
  const evidenceHasIdentityObject = evidenceEntriesContainTerm(articleEvidence, "domainObjects", [
    "identity",
    "id document",
    "identity document",
    "identity card",
    "id card",
    "passport",
    "travel document",
    "eid",
  ]);
  const evidenceHasIdCardDocumentType = evidenceEntriesContainTerm(articleEvidence, "documentTypes", [
    "id card",
    "identity card",
    "national id",
    "eid",
  ]);
  const evidenceHasPassportDocumentType = evidenceEntriesContainTerm(articleEvidence, "documentTypes", [
    "passport",
    "passports",
    "travel document",
  ]);
  const evidenceHasExplicitPassportEvidence = evidenceEntriesContainId(articleEvidence, "documentTypes", [
    "passport",
    "passports",
    "travel_document",
    "passport_issuance",
    "passport_renewal",
    "passport_application",
    "passport_office",
  ]) || evidenceHasPassportDocumentType;
  const evidenceHasCitizenshipOrTravelEvidence = evidenceEntriesContainId(articleEvidence, "professionalSignals", [
    "citizenship",
    "proof_of_citizenship",
    "airport_border_delay",
  ]) || evidenceEntriesContainId(articleEvidence, "documentTypes", ["passport_deadline"]);
  const evidenceHasConsumerPassportNoise = evidenceEntriesContainId(articleEvidence, "noiseSignals", [
    "consumer_passport",
    "passport_noise",
    "travel_advice",
    "lost_passport",
  ]);
  const evidenceHasExplicitIdCardEvidence = evidenceEntriesContainId(
    articleEvidence,
    "documentTypes",
    EXPLICIT_ID_CARD_EVIDENCE_IDS
  );
  const evidenceHasRelatedIdentityEvidence = evidenceEntriesContainId(articleEvidence, "documentTypes", [
    "identity_documents",
  ]) || evidenceHasIdentityObject;
  const evidenceHasWeakOrIndirectIdCardEvidence = evidenceEntriesContainId(articleEvidence, "documentTypes", [
    "card_issuance",
    "polycarbonate_id",
    "identity_card_design",
  ]);
  const evidenceHasVendor = evidenceSummary.vendors > 0;
  const evidenceHasTechnology = evidenceSummary.technologies > 0;
  const evidenceHasEventSignal = evidenceSummary.eventSignals > 0;
  const evidenceHasNoiseSignal = evidenceSummary.noiseSignals > 0;
  const evidenceHasProfessionalSignal = getEvidenceEntriesForGroup(articleEvidence, "professionalSignals")
    .some((entry) => Boolean(entry?.category || entry?.sourceHelper));
  const idCardEvidenceGapExplanation = getIdCardEvidenceGapExplanation(
    article,
    articleEvidence,
    legacyIdCardsBoost,
    legacyIdentitySubinterest
  );
  const parityWarnings = [];

  if (getArticleDominantDomain(article) === "identity_documents" && !evidenceHasIdentityObject) {
    parityWarnings.push("legacy_identity_domain_without_identity_object_evidence");
  }
  if ((legacyIdCardsBoost?.score || 0) > 0 && !evidenceHasExplicitIdCardEvidence) {
    if (evidenceHasRelatedIdentityEvidence) {
      parityWarnings.push("legacy_id_cards_score_with_related_identity_evidence_only");
    } else if (evidenceHasWeakOrIndirectIdCardEvidence) {
      parityWarnings.push("legacy_id_cards_score_from_weak_or_indirect_evidence");
    } else {
      parityWarnings.push("legacy_id_cards_score_without_any_id_or_identity_document_evidence");
    }
  }
  if (legacyShouldRejectPassport) {
    if (passportProfessionalAlignment.professionalRescueCandidate) {
      parityWarnings.push("legacy_passport_guard_aligned_professional_passport_rescue_candidate");
    } else if (evidenceHasProfessionalSignal && evidenceHasExplicitPassportEvidence) {
      parityWarnings.push("legacy_passport_guard_with_professional_and_document_signal");
    } else if (evidenceHasProfessionalSignal && evidenceHasNoiseSignal) {
      parityWarnings.push("legacy_passport_guard_with_professional_and_noise_signal");
    } else if (evidenceHasProfessionalSignal) {
      parityWarnings.push("legacy_passport_guard_with_professional_signal_only");
    } else if (evidenceHasExplicitPassportEvidence && !evidenceHasNoiseSignal) {
      parityWarnings.push("legacy_passport_guard_with_passport_document_evidence_only");
    } else if (!evidenceHasExplicitPassportEvidence && evidenceHasCitizenshipOrTravelEvidence && !evidenceHasConsumerPassportNoise) {
      parityWarnings.push("legacy_passport_guard_with_citizenship_or_travel_evidence_only");
    } else if (!evidenceHasExplicitPassportEvidence && evidenceHasConsumerPassportNoise) {
      parityWarnings.push("legacy_passport_guard_with_consumer_passport_noise_only");
    } else if (!evidenceHasExplicitPassportEvidence && !evidenceHasNoiseSignal) {
      parityWarnings.push("legacy_passport_guard_without_document_noise_or_professional_signal");
    }
  }
  if (legacyProfessionalIdentityRescue && !evidenceHasVendor && !evidenceHasProfessionalSignal) {
    parityWarnings.push("legacy_professional_rescue_without_professional_signal");
  }
  if (legacyKeesingIdentityRelevance?.hasRequiredComponent && !evidenceHasProfessionalSignal) {
    parityWarnings.push("legacy_keesing_identity_without_professional_signal");
  }
  if (legacyHighConfidencePassportAssessment?.kept && !evidenceHasProfessionalSignal) {
    parityWarnings.push("legacy_high_confidence_passport_without_professional_signal");
  }
  if (legacyUiRelevant && !evidenceHasProfessionalSignal && !evidenceHasEventSignal) {
    parityWarnings.push("legacy_ui_relevance_without_professional_signal");
  }
  if ((legacyIdentityDocumentRelevance || 0) >= IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD && !evidenceHasProfessionalSignal) {
    parityWarnings.push("legacy_identity_relevance_without_professional_signal");
  }
  if (legacyHardPassportNoise && !evidenceHasNoiseSignal) {
    parityWarnings.push("legacy_hard_passport_noise_without_noise_evidence");
  } else if (legacyLowRelevancePassport && !evidenceHasNoiseSignal) {
    parityWarnings.push("legacy_low_relevance_passport_without_noise_evidence");
  }
  if (legacyUiRelevant && !evidenceHasEventSignal) {
    parityWarnings.push("legacy_ui_relevant_without_event_evidence");
  }

  return {
    articleId: getFilterDecisionTraceArticleId(article),
    title: article?.title || "Untitled article",
    source: article?.source || article?.feedTitle || article?.feedName || "",
    evidenceHasIdentityObject,
    evidenceHasIdCardDocumentType,
    evidenceHasPassportDocumentType,
    evidenceHasExplicitPassportEvidence,
    evidenceHasCitizenshipOrTravelEvidence,
    evidenceHasConsumerPassportNoise,
    evidenceHasExplicitIdCardEvidence,
    evidenceHasRelatedIdentityEvidence,
    evidenceHasWeakOrIndirectIdCardEvidence,
    evidenceHasVendor,
    evidenceHasTechnology,
    evidenceHasEventSignal,
    evidenceHasNoiseSignal,
    evidenceHasProfessionalSignal,
    legacyDominantDomain: getArticleDominantDomain(article),
    legacyIdCardsScore: legacyIdCardsBoost?.score || 0,
    legacyIdentitySubinterestScore: legacyIdentitySubinterest?.score || 0,
    legacyUiRelevant,
    legacyShouldRejectPassport,
    legacyHardPassportNoise,
    legacyLowRelevancePassport,
    legacyKeesingIdentityRelevance,
    legacyHighConfidencePassportAssessment,
    legacyIdentityDocumentRelevance,
    legacyProfessionalIdentityRescue,
    passportProfessionalAlignment,
    idCardEvidenceGapExplanation,
    evidenceSummary,
    parityWarnings,
  };
}

function incrementParityAgreement(counts, key, agreed) {
  if (!counts[key]) {
    counts[key] = { agree: 0, mismatch: 0 };
  }
  counts[key][agreed ? "agree" : "mismatch"] += 1;
}

function getTopParityWarnings(warnings, limit = 10) {
  return Array.from(warnings.entries())
    .map(([warning, count]) => ({ warning, count }))
    .sort((left, right) => right.count - left.count || left.warning.localeCompare(right.warning))
    .slice(0, limit);
}

function getEvidenceBuilderParitySummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const agreements = {};
  const warnings = new Map();
  let warningCount = 0;

  traces.forEach((trace) => {
    const parity = trace.evidenceParityDiagnostics;
    if (!parity) {
      return;
    }
    incrementParityAgreement(agreements, "identityObjectAgreement",
      parity.legacyDominantDomain !== "identity_documents" || parity.evidenceHasIdentityObject);
    incrementParityAgreement(agreements, "idCardsEvidenceVsScorePositive",
      !(parity.legacyIdCardsScore > 0) || parity.evidenceHasExplicitIdCardEvidence);
    incrementParityAgreement(agreements, "passportEvidenceVsPassportGuard",
      !parity.legacyShouldRejectPassport || parity.evidenceHasExplicitPassportEvidence || parity.evidenceHasConsumerPassportNoise || parity.evidenceHasProfessionalSignal);
    incrementParityAgreement(agreements, "vendorEvidenceVsProfessionalRescue",
      !parity.legacyProfessionalIdentityRescue || parity.evidenceHasVendor || parity.evidenceHasProfessionalSignal);
    incrementParityAgreement(agreements, "noiseEvidenceVsLegacyNoise",
      !(parity.legacyHardPassportNoise || parity.legacyLowRelevancePassport) || parity.evidenceHasNoiseSignal);
    incrementParityAgreement(agreements, "uiRelevantVsEventEvidence",
      !parity.legacyUiRelevant || parity.evidenceHasEventSignal);
    (parity.parityWarnings || []).forEach((warning) => {
      warningCount += 1;
      warnings.set(warning, (warnings.get(warning) || 0) + 1);
    });
  });

  return {
    enabled: true,
    evaluatedArticles: traces.length,
    identityObjectAgreement: agreements.identityObjectAgreement || { agree: 0, mismatch: 0 },
    idCardsEvidenceVsScorePositive: agreements.idCardsEvidenceVsScorePositive || { agree: 0, mismatch: 0 },
    passportEvidenceVsPassportGuard: agreements.passportEvidenceVsPassportGuard || { agree: 0, mismatch: 0 },
    vendorEvidenceVsProfessionalRescue: agreements.vendorEvidenceVsProfessionalRescue || { agree: 0, mismatch: 0 },
    noiseEvidenceVsLegacyNoise: agreements.noiseEvidenceVsLegacyNoise || { agree: 0, mismatch: 0 },
    uiRelevantVsEventEvidence: agreements.uiRelevantVsEventEvidence || { agree: 0, mismatch: 0 },
    warningCount,
    topWarnings: getTopParityWarnings(warnings),
  };
}

function getEvidenceBuilderIdCardsParitySummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const idCardEvidenceCounts = new Map();
  const missingEvidenceWarnings = new Map();
  const evidenceGapReasonCounts = new Map();
  const evidenceGapExamplesByReason = new Map();
  let legacyPositiveIdCardsScore = 0;
  let explicitIdCardEvidenceCount = 0;
  let relatedIdentityEvidenceOnlyCount = 0;
  let noIdOrIdentityEvidenceCount = 0;
  let weakOrIndirectEvidenceCount = 0;

  traces.forEach((trace) => {
    const parity = trace.evidenceParityDiagnostics;
    if (!parity) {
      return;
    }
    const hasPositiveIdCardsScore = (parity.legacyIdCardsScore || 0) > 0;
    if (hasPositiveIdCardsScore) {
      legacyPositiveIdCardsScore += 1;
    }
    if (parity.evidenceHasExplicitIdCardEvidence) {
      explicitIdCardEvidenceCount += 1;
    } else if (hasPositiveIdCardsScore && parity.evidenceHasRelatedIdentityEvidence) {
      relatedIdentityEvidenceOnlyCount += 1;
    } else if (hasPositiveIdCardsScore && parity.evidenceHasWeakOrIndirectIdCardEvidence) {
      weakOrIndirectEvidenceCount += 1;
    } else if (hasPositiveIdCardsScore) {
      noIdOrIdentityEvidenceCount += 1;
    }
    const gapReason = parity.idCardEvidenceGapExplanation?.reason || "";
    if (hasPositiveIdCardsScore && gapReason) {
      incrementReasonCount(evidenceGapReasonCounts, gapReason);
      if (!evidenceGapExamplesByReason.has(gapReason)) {
        evidenceGapExamplesByReason.set(gapReason, []);
      }
      const examples = evidenceGapExamplesByReason.get(gapReason);
      if (examples.length < 5) {
        examples.push({
          articleId: parity.articleId,
          title: parity.title,
          source: parity.source || "",
          legacyIdCardsScore: parity.legacyIdCardsScore,
          matchedRuleId: parity.idCardEvidenceGapExplanation?.selectedRuleSetEvidence?.matchedRuleId || "",
          selectedEvidence: parity.idCardEvidenceGapExplanation?.selectedEvidence || {},
          legacyEvidence: parity.idCardEvidenceGapExplanation?.legacyEvidence || {},
        });
      }
    }

    getEvidenceEntriesForGroup(trace.evidenceDiagnostics, "documentTypes")
      .filter((entry) => [
        "id_cards",
        "id_card",
        "identity_card",
        "national_id",
        "electronic_identity_card",
        "eid_card",
        "secure_id_documents",
        "id_documents",
        "identity_card_issuance",
        "physical_identity_documents",
        "card_issuance",
        "polycarbonate_id",
        "identity_card_design",
        "identity_document_protection",
        "national_identity_guard",
        "national_id_documents",
        "hybrid_id_documents",
        "identity_documents",
      ].includes(entry.id))
      .forEach((entry) => incrementEvidenceCount(idCardEvidenceCounts, entry));
    (parity.parityWarnings || [])
      .filter((warning) => warning.startsWith("legacy_id_cards_score_"))
      .forEach((warning) => missingEvidenceWarnings.set(warning, (missingEvidenceWarnings.get(warning) || 0) + 1));
  });

  return {
    enabled: true,
    evaluatedArticles: traces.length,
    legacyPositiveIdCardsScore,
    explicitIdCardEvidenceCount,
    relatedIdentityEvidenceOnlyCount,
    noIdOrIdentityEvidenceCount,
    weakOrIndirectEvidenceCount,
    topMatchedIdCardEvidence: getTopEvidenceCounts(idCardEvidenceCounts),
    topMissingEvidenceWarnings: getTopParityWarnings(missingEvidenceWarnings),
    topEvidenceGapReasons: getTopV3DecisionReasons(evidenceGapReasonCounts, 10),
    evidenceGapExamplesByReason: Object.fromEntries(evidenceGapExamplesByReason.entries()),
  };
}

function getEvidenceBuilderPassportParitySummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const passportEvidenceCounts = new Map();
  const missingEvidenceWarnings = new Map();
  let legacyPassportGuardTriggered = 0;
  let explicitPassportEvidenceCount = 0;
  let citizenshipOrTravelEvidenceOnlyCount = 0;
  let consumerPassportNoiseEvidenceCount = 0;
  let noPassportOrNoiseEvidenceCount = 0;

  traces.forEach((trace) => {
    const parity = trace.evidenceParityDiagnostics;
    if (!parity) {
      return;
    }
    if (parity.legacyShouldRejectPassport) {
      legacyPassportGuardTriggered += 1;
      if (parity.evidenceHasConsumerPassportNoise) {
        consumerPassportNoiseEvidenceCount += 1;
      }
      if (parity.evidenceHasExplicitPassportEvidence) {
        explicitPassportEvidenceCount += 1;
      } else if (parity.evidenceHasCitizenshipOrTravelEvidence) {
        citizenshipOrTravelEvidenceOnlyCount += 1;
      } else {
        noPassportOrNoiseEvidenceCount += 1;
      }
    }

    ["documentTypes", "professionalSignals", "noiseSignals"].forEach((group) => {
      getEvidenceEntriesForGroup(trace.evidenceDiagnostics, group)
        .filter((entry) => [
          "passport",
          "passports",
          "passport_issuance",
          "passport_renewal",
          "passport_application",
          "travel_document",
          "citizenship",
          "proof_of_citizenship",
          "passport_counter",
          "passport_office",
          "passport_deadline",
          "airport_border_delay",
          "travel_advice",
          "lost_passport",
          "consumer_passport",
          "passport_noise",
        ].includes(entry.id))
        .forEach((entry) => incrementEvidenceCount(passportEvidenceCounts, entry));
    });
    (parity.parityWarnings || [])
      .filter((warning) => warning.startsWith("legacy_passport_guard_"))
      .forEach((warning) => missingEvidenceWarnings.set(warning, (missingEvidenceWarnings.get(warning) || 0) + 1));
  });

  return {
    enabled: true,
    evaluatedArticles: traces.length,
    legacyPassportGuardTriggered,
    explicitPassportEvidenceCount,
    citizenshipOrTravelEvidenceOnlyCount,
    consumerPassportNoiseEvidenceCount,
    noPassportOrNoiseEvidenceCount,
    topMatchedPassportEvidence: getTopEvidenceCounts(passportEvidenceCounts),
    topMissingEvidenceWarnings: getTopParityWarnings(missingEvidenceWarnings),
  };
}

function incrementEvidenceCategoryCount(counts, entry) {
  const category = entry?.category || "uncategorized";
  const existing = counts.get(category) || {
    category,
    count: 0,
  };
  existing.count += 1;
  counts.set(category, existing);
}

function getTopEvidenceCategoryCounts(counts, limit = 10) {
  return Array.from(counts.values())
    .sort((left, right) => right.count - left.count || left.category.localeCompare(right.category))
    .slice(0, limit);
}

function getEvidenceBuilderNoiseSummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const categoryCounts = new Map();
  const termCounts = new Map();
  const warningCounts = new Map();
  let articlesWithNoise = 0;

  traces.forEach((trace) => {
    const noiseEntries = getEvidenceEntriesForGroup(trace.evidenceDiagnostics, "noiseSignals");
    if (noiseEntries.length) {
      articlesWithNoise += 1;
    }
    noiseEntries.forEach((entry) => {
      incrementEvidenceCategoryCount(categoryCounts, entry);
      incrementEvidenceCount(termCounts, {
        id: entry?.id || normalizeEvidenceId(entry?.matchedTerm || entry?.term || ""),
        term: entry?.matchedTerm || entry?.term || entry?.id || "",
      });
    });
    (trace.evidenceParityDiagnostics?.parityWarnings || [])
      .filter((warning) => /noise|passport_guard|consumer|travel/i.test(warning))
      .forEach((warning) => warningCounts.set(warning, (warningCounts.get(warning) || 0) + 1));
  });

  return {
    enabled: true,
    evaluatedArticles: traces.length,
    articlesWithNoise,
    topNoiseCategories: getTopEvidenceCategoryCounts(categoryCounts),
    topNoiseTerms: getTopEvidenceCounts(termCounts),
    parityWarnings: getTopParityWarnings(warningCounts),
  };
}

