function getEvidenceBuilderProfessionalParitySummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const professionalSignalCounts = new Map();
  const professionalWarningCounts = new Map();
  let legacyProfessionalGuardTriggered = 0;
  let professionalSignalCoverageCount = 0;
  let professionalAndDocumentCoverageCount = 0;
  let professionalAndNoiseCoverageCount = 0;
  let noProfessionalEvidenceCount = 0;

  traces.forEach((trace) => {
    const parity = trace.evidenceParityDiagnostics;
    if (!parity) {
      return;
    }
    const legacyProfessionalTriggered = Boolean(
      parity.legacyShouldRejectPassport
      || parity.legacyProfessionalIdentityRescue
      || parity.legacyKeesingIdentityRelevance?.hasRequiredComponent
      || parity.legacyHighConfidencePassportAssessment?.kept
      || (parity.legacyIdentityDocumentRelevance || 0) >= IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD
      || parity.legacyUiRelevant
    );
    if (legacyProfessionalTriggered) {
      legacyProfessionalGuardTriggered += 1;
      if (parity.evidenceHasProfessionalSignal) {
        professionalSignalCoverageCount += 1;
      } else {
        noProfessionalEvidenceCount += 1;
      }
      if (parity.evidenceHasProfessionalSignal && (parity.evidenceHasExplicitPassportEvidence || parity.evidenceHasIdCardDocumentType || parity.evidenceHasIdentityObject)) {
        professionalAndDocumentCoverageCount += 1;
      }
      if (parity.evidenceHasProfessionalSignal && parity.evidenceHasNoiseSignal) {
        professionalAndNoiseCoverageCount += 1;
      }
    }

    getEvidenceEntriesForGroup(trace.evidenceDiagnostics, "professionalSignals")
      .forEach((entry) => incrementEvidenceCount(professionalSignalCounts, entry));
    (parity.parityWarnings || [])
      .filter((warning) => /professional|keesing|high_confidence|identity_relevance|ui_relevance|passport_guard/i.test(warning))
      .forEach((warning) => professionalWarningCounts.set(warning, (professionalWarningCounts.get(warning) || 0) + 1));
  });

  return {
    enabled: true,
    evaluatedArticles: traces.length,
    legacyProfessionalGuardTriggered,
    professionalSignalCoverageCount,
    professionalAndDocumentCoverageCount,
    professionalAndNoiseCoverageCount,
    noProfessionalEvidenceCount,
    topProfessionalParityWarnings: getTopParityWarnings(professionalWarningCounts),
    topProfessionalSignalCoverage: getTopEvidenceCounts(professionalSignalCounts),
  };
}

function summarizeV3EvidenceGroup(articleEvidence, evidenceGroup) {
  const entries = getEvidenceEntriesForGroup(articleEvidence, evidenceGroup);
  const categoryCounts = new Map();
  entries.forEach((entry) => incrementEvidenceCategoryCount(categoryCounts, entry));
  return {
    count: entries.length,
    strongCount: entries.filter((entry) => entry?.strength === "strong").length,
    mediumCount: entries.filter((entry) => entry?.strength === "medium").length,
    weakCount: entries.filter((entry) => entry?.strength === "weak").length,
    categories: getTopEvidenceCategoryCounts(categoryCounts, 5),
    examples: entries.slice(0, 5).map((entry) => ({
      id: entry?.id || "",
      term: entry?.term || entry?.matchedTerm || "",
      category: entry?.category || "",
      strength: entry?.strength || "",
    })),
  };
}

function getV3ConfidenceBand(confidenceScore) {
  if (confidenceScore >= 95) {
    return "very_high";
  }
  if (confidenceScore >= 80) {
    return "high";
  }
  if (confidenceScore >= 60) {
    return "medium";
  }
  if (confidenceScore >= 40) {
    return "low";
  }
  return "very_low";
}

function summarizeV3ConfidenceSignals(entries = []) {
  return entries.slice(0, 5).map((entry) => ({
    id: entry?.id || "",
    term: entry?.term || entry?.matchedTerm || "",
    category: entry?.category || "",
    strength: entry?.strength || "",
  }));
}

function buildV3Confidence(article, options = {}) {
  const articleEvidence = options.articleEvidence || buildArticleEvidence(article);
  const v3DecisionDiagnostics = options.v3DecisionDiagnostics || null;
  const documentEntries = []
    .concat(getEvidenceEntriesForGroup(articleEvidence, "domainObjects"))
    .concat(getEvidenceEntriesForGroup(articleEvidence, "documentTypes"));
  const professionalEntries = getEvidenceEntriesForGroup(articleEvidence, "professionalSignals");
  const noiseEntries = getEvidenceEntriesForGroup(articleEvidence, "noiseSignals");
  const eventEntries = getEvidenceEntriesForGroup(articleEvidence, "eventSignals");
  const strongDocumentEntries = documentEntries.filter((entry) => entry?.strength === "strong");
  const strongProfessionalEntries = professionalEntries.filter((entry) => entry?.strength === "strong");
  const strongNoiseEntries = noiseEntries.filter((entry) => entry?.strength === "strong");
  const positiveEvidence = {
    documentEvidence: documentEntries.length,
    strongDocumentEvidence: strongDocumentEntries.length,
    professionalEvidence: professionalEntries.length,
    strongProfessionalEvidence: strongProfessionalEntries.length,
    eventEvidence: eventEntries.length,
  };
  const negativeEvidence = {
    noiseEvidence: noiseEntries.length,
    strongNoiseEvidence: strongNoiseEntries.length,
    conflictingEvidence: professionalEntries.length > 0 && noiseEntries.length > 0,
    missingDocumentEvidence: documentEntries.length === 0,
    weakProfessionalEvidence: professionalEntries.length === 0,
    driverLicenseOperationalNoise: (v3DecisionDiagnostics?.reasons || []).includes("driver_license_operational_noise"),
    driverLicenseOperationalNoiseRescued: (v3DecisionDiagnostics?.reasons || []).includes("driver_license_operational_noise_rescued_by_strong_intelligence"),
    visaConsumerNoise: (v3DecisionDiagnostics?.reasons || []).includes("visa_consumer_travel_noise"),
    visaConsumerNoiseRescued: (v3DecisionDiagnostics?.reasons || []).includes("visa_consumer_noise_rescued_by_strong_intelligence"),
  };
  let confidenceScore = 35;

  confidenceScore += Math.min(25, documentEntries.length * 4 + strongDocumentEntries.length * 6);
  confidenceScore += Math.min(25, professionalEntries.length * 3 + strongProfessionalEntries.length * 7);
  confidenceScore += Math.min(10, eventEntries.length * 2);
  confidenceScore -= Math.min(30, noiseEntries.length * 4 + strongNoiseEntries.length * 10);
  if (negativeEvidence.conflictingEvidence) {
    confidenceScore -= 12;
  }
  if (negativeEvidence.missingDocumentEvidence) {
    confidenceScore -= 25;
  }
  if (v3DecisionDiagnostics?.suggestedDecision === "uncertain") {
    confidenceScore -= 10;
  }
  if (negativeEvidence.driverLicenseOperationalNoise && !negativeEvidence.driverLicenseOperationalNoiseRescued) {
    confidenceScore -= 18;
  }
  if (negativeEvidence.visaConsumerNoise && !negativeEvidence.visaConsumerNoiseRescued) {
    confidenceScore -= 18;
  }
  confidenceScore = Math.max(0, Math.min(100, Math.round(confidenceScore)));
  const confidenceBand = getV3ConfidenceBand(confidenceScore);
  const strongestSignals = summarizeV3ConfidenceSignals(
    strongProfessionalEntries.concat(strongDocumentEntries, eventEntries, professionalEntries, documentEntries)
  );
  const weakestSignals = summarizeV3ConfidenceSignals(
    strongNoiseEntries.concat(noiseEntries)
  );
  const explanation = [
    documentEntries.length ? "document evidence present" : "no document evidence",
    professionalEntries.length ? "professional evidence present" : "weak professional evidence",
    noiseEntries.length ? "noise evidence present" : "low noise",
    eventEntries.length ? "event evidence present" : "limited event evidence",
    negativeEvidence.conflictingEvidence ? "professional and noise evidence conflict" : "",
    negativeEvidence.driverLicenseOperationalNoise
      ? negativeEvidence.driverLicenseOperationalNoiseRescued
        ? "Driver License operational noise rescued by strong intelligence"
        : "Driver License operational noise detected"
      : "",
    negativeEvidence.visaConsumerNoise
      ? negativeEvidence.visaConsumerNoiseRescued
        ? "Visa consumer travel noise rescued by strong intelligence"
        : "Visa consumer travel noise detected"
      : "",
  ].filter(Boolean).join("; ");

  return {
    confidenceScore,
    confidenceBand,
    positiveEvidence,
    negativeEvidence,
    strongestSignals,
    weakestSignals,
    explanation,
  };
}

function buildV3DecisionDiagnostics(article, options = {}) {
  const articleEvidence = options.articleEvidence || buildArticleEvidence(article);
  const evidence = articleEvidence?.evidence || {};
  const documentEntries = []
    .concat(getEvidenceEntriesForGroup(articleEvidence, "domainObjects"))
    .concat(getEvidenceEntriesForGroup(articleEvidence, "documentTypes"));
  const professionalEntries = getEvidenceEntriesForGroup(articleEvidence, "professionalSignals");
  const noiseEntries = getEvidenceEntriesForGroup(articleEvidence, "noiseSignals");
  const eventEntries = getEvidenceEntriesForGroup(articleEvidence, "eventSignals");
  const strongDocumentCount = documentEntries.filter((entry) => entry?.strength === "strong").length;
  const strongProfessionalCount = professionalEntries.filter((entry) => entry?.strength === "strong").length;
  const strongNoiseCount = noiseEntries.filter((entry) => entry?.strength === "strong").length;
  const eventCount = eventEntries.length;
  const selectedIdentityInterests = getSelectedIdentityDocumentSubinterests();
  const driverLicenseDashboardActive =
    selectedIdentityInterests.length === 1 && selectedIdentityInterests[0] === "drivers_licenses";
  const visaDashboardActive = selectedIdentityInterests.includes("visas");
  const driverLicenseOperationalNoise = driverLicenseDashboardActive
    ? getDriverLicensePatternMatches(article, getDriverLicenseOperationalNoisePatternDefinitions())
    : [];
  const driverLicenseStrongIntelligence = driverLicenseDashboardActive
    ? getDriverLicensePatternMatches(article, getDriverLicenseStrongIntelligencePatternDefinitions())
    : [];
  const visaConsumerNoise = visaDashboardActive
    ? getVisaPatternMatches(article, getVisaNoisePatternDefinitions())
    : [];
  const visaStrongIntelligence = visaDashboardActive
    ? getVisaPatternMatches(article, getVisaStrongIntelligencePatternDefinitions())
    : [];
  const hasDriverLicenseOperationalNoise = driverLicenseOperationalNoise.length > 0;
  const hasDriverLicenseStrongIntelligence = driverLicenseStrongIntelligence.length > 0;
  const hasVisaConsumerNoise = visaConsumerNoise.length > 0;
  const hasVisaStrongIntelligence = visaStrongIntelligence.length > 0;
  const reasons = [];

  if (hasDriverLicenseOperationalNoise) {
    reasons.push("driver_license_operational_noise");
  }
  if (hasDriverLicenseOperationalNoise && hasDriverLicenseStrongIntelligence) {
    reasons.push("driver_license_operational_noise_rescued_by_strong_intelligence");
  }
  if (hasVisaConsumerNoise) {
    reasons.push("visa_consumer_travel_noise");
  }
  if (hasVisaConsumerNoise && hasVisaStrongIntelligence) {
    reasons.push("visa_consumer_noise_rescued_by_strong_intelligence");
  }

  if (strongProfessionalCount > 0) {
    reasons.push("strong_professional_evidence");
  } else if (professionalEntries.length > 0) {
    reasons.push("professional_evidence");
  } else {
    reasons.push("weak_professional_evidence");
  }

  if (strongDocumentCount > 0) {
    reasons.push("strong_document_evidence");
  } else if (documentEntries.length > 0) {
    reasons.push("document_evidence");
  } else {
    reasons.push("weak_document_evidence");
  }

  if (strongNoiseCount > 0) {
    reasons.push("strong_noise_evidence");
  } else if (noiseEntries.length > 0) {
    reasons.push("noise_evidence");
  } else {
    reasons.push("low_noise");
  }

  if (eventCount > 0) {
    reasons.push("event_evidence");
  }

  let suggestedDecision = "uncertain";
  let confidence = 0.45;
  if (hasDriverLicenseOperationalNoise && !hasDriverLicenseStrongIntelligence) {
    suggestedDecision = "reject_candidate";
    confidence = 0.82;
  } else if (hasVisaConsumerNoise && !hasVisaStrongIntelligence) {
    suggestedDecision = "reject_candidate";
    confidence = 0.84;
  } else if (strongProfessionalCount > 0 && strongDocumentCount > 0 && strongNoiseCount === 0) {
    suggestedDecision = "include_candidate";
    confidence = Math.min(0.95, 0.68 + (strongProfessionalCount * 0.05) + (strongDocumentCount * 0.04) + (eventCount ? 0.05 : 0));
  } else if (strongNoiseCount > 0 && strongProfessionalCount === 0) {
    suggestedDecision = "reject_candidate";
    confidence = Math.min(0.95, 0.7 + (strongNoiseCount * 0.05));
  } else if (professionalEntries.length && documentEntries.length && strongNoiseCount === 0) {
    suggestedDecision = "include_candidate";
    confidence = 0.62;
  } else if (noiseEntries.length && !professionalEntries.length) {
    suggestedDecision = "reject_candidate";
    confidence = 0.6;
  }
  const preliminaryDecision = {
    suggestedDecision,
    confidence,
    reasons,
    driverLicenseOperationalNoise,
    driverLicenseStrongIntelligence,
    visaConsumerNoise,
    visaStrongIntelligence,
  };
  const confidenceDiagnostics = buildV3Confidence(article, {
    articleEvidence,
    v3DecisionDiagnostics: preliminaryDecision,
  });

  return {
    articleId: articleEvidence?.articleId || getFilterDecisionTraceArticleId(article),
    title: article?.title || "Untitled article",
    suggestedDecision,
    confidence: confidenceDiagnostics.confidenceScore,
    confidenceBand: confidenceDiagnostics.confidenceBand,
    confidenceExplanation: confidenceDiagnostics.explanation,
    confidenceDiagnostics,
    reasons,
    evidenceSummary: {
      domainObjects: evidence.domainObjects?.length || 0,
      documentTypes: evidence.documentTypes?.length || 0,
      vendors: evidence.vendors?.length || 0,
      materials: evidence.materials?.length || 0,
      technologies: evidence.technologies?.length || 0,
      sourceEvidence: evidence.sourceEvidence?.length || 0,
    },
    professionalSummary: summarizeV3EvidenceGroup(articleEvidence, "professionalSignals"),
    noiseSummary: summarizeV3EvidenceGroup(articleEvidence, "noiseSignals"),
    eventSummary: summarizeV3EvidenceGroup(articleEvidence, "eventSignals"),
    driverLicenseOperationalNoise: {
      detected: hasDriverLicenseOperationalNoise,
      patterns: driverLicenseOperationalNoise.map((entry) => entry.pattern),
      matchedSignals: driverLicenseOperationalNoise.flatMap((entry) => entry.matchedSignals || []).slice(0, 12),
      rescuedByStrongIntelligence: hasDriverLicenseOperationalNoise && hasDriverLicenseStrongIntelligence,
      rescuePatterns: driverLicenseStrongIntelligence.map((entry) => entry.pattern),
      rescueReason: hasDriverLicenseOperationalNoise && hasDriverLicenseStrongIntelligence
        ? "strong Driver License intelligence overrides operational service noise in shadow diagnostics"
        : "",
    },
    visaConsumerNoise: {
      detected: hasVisaConsumerNoise,
      patterns: visaConsumerNoise.map((entry) => entry.pattern),
      matchedSignals: visaConsumerNoise.flatMap((entry) => entry.matchedSignals || []).slice(0, 12),
      rescuedByStrongIntelligence: hasVisaConsumerNoise && hasVisaStrongIntelligence,
      rescuePatterns: visaStrongIntelligence.map((entry) => entry.pattern),
      rescueReason: hasVisaConsumerNoise && hasVisaStrongIntelligence
        ? "strong Visa document/security/issuance intelligence overrides consumer travel noise in shadow diagnostics"
        : "",
    },
    legacyComparison: {
      finalResult: options.trace?.finalResult || "",
      finalReason: options.trace?.finalReason || "",
      personalDashboardPassed: (options.trace?.stages || []).some((stage) =>
        stage.stage === "personal_dashboard" && stage.result === "passed"
      ),
      advancedFiltersPassed: (options.trace?.stages || []).some((stage) =>
        stage.stage === "advanced_filters" && stage.result === "passed"
      ),
    },
  };
}

function incrementReasonCount(counts, reason) {
  if (!reason) {
    return;
  }
  counts.set(reason, (counts.get(reason) || 0) + 1);
}

function getTopV3DecisionReasons(counts, limit = 10) {
  return Array.from(counts.entries())
    .map(([reason, count]) => ({ reason, count }))
    .sort((left, right) => right.count - left.count || left.reason.localeCompare(right.reason))
    .slice(0, limit);
}

function getV3DecisionEngineDiagnosticsSummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const includeReasonCounts = new Map();
  const rejectReasonCounts = new Map();
  const uncertainReasonCounts = new Map();
  const legacyAgreement = {
    includeVisible: 0,
    includeRejected: 0,
    rejectVisible: 0,
    rejectRejected: 0,
    uncertainVisible: 0,
    uncertainRejected: 0,
  };
  let includeCandidateCount = 0;
  let rejectCandidateCount = 0;
  let uncertainCount = 0;
  let confidenceTotal = 0;

  traces.forEach((trace) => {
    const decision = trace.v3DecisionDiagnostics;
    if (!decision) {
      return;
    }
    confidenceTotal += Number(decision.confidence || 0);
    const reasonTarget = decision.suggestedDecision === "include_candidate"
      ? includeReasonCounts
      : decision.suggestedDecision === "reject_candidate"
        ? rejectReasonCounts
        : uncertainReasonCounts;
    (decision.reasons || []).forEach((reason) => incrementReasonCount(reasonTarget, reason));

    const legacyVisible = trace.finalResult !== "rejected";
    if (decision.suggestedDecision === "include_candidate") {
      includeCandidateCount += 1;
      legacyAgreement[legacyVisible ? "includeVisible" : "includeRejected"] += 1;
    } else if (decision.suggestedDecision === "reject_candidate") {
      rejectCandidateCount += 1;
      legacyAgreement[legacyVisible ? "rejectVisible" : "rejectRejected"] += 1;
    } else {
      uncertainCount += 1;
      legacyAgreement[legacyVisible ? "uncertainVisible" : "uncertainRejected"] += 1;
    }
  });

  return {
    enabled: true,
    evaluatedArticles: traces.length,
    includeCandidateCount,
    rejectCandidateCount,
    uncertainCount,
    averageConfidence: traces.length ? Number((confidenceTotal / traces.length).toFixed(2)) : 0,
    topIncludeReasons: getTopV3DecisionReasons(includeReasonCounts),
    topRejectReasons: getTopV3DecisionReasons(rejectReasonCounts),
    topUncertainReasons: getTopV3DecisionReasons(uncertainReasonCounts),
    legacyAgreementSummary: legacyAgreement,
  };
}

function incrementConfidenceBand(distribution, confidenceBand) {
  const normalizedBand = confidenceBand || "unknown";
  distribution[normalizedBand] = (distribution[normalizedBand] || 0) + 1;
}

function getTopConfidenceSignals(counts, limit = 10) {
  return Array.from(counts.entries())
    .map(([signal, count]) => ({ signal, count }))
    .sort((left, right) => right.count - left.count || left.signal.localeCompare(right.signal))
    .slice(0, limit);
}

function incrementConfidenceSignalCounts(counts, signals = []) {
  signals.forEach((signal) => {
    const key = signal?.id || normalizeEvidenceId(signal?.term || "");
    if (!key) {
      return;
    }
    counts.set(key, (counts.get(key) || 0) + 1);
  });
}

function getV3ConfidenceSummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }

  const traces = getHeavyDiagnosticsTraces(diagnostics);
  const confidenceDistribution = {
    very_high: 0,
    high: 0,
    medium: 0,
    low: 0,
    very_low: 0,
  };
  const byDecision = new Map();
  const strongestSignalCounts = new Map();
  const weakestSignalCounts = new Map();
  let evaluatedArticles = 0;
  let totalConfidence = 0;
  let highestConfidence = 0;
  let lowestConfidence = 100;

  traces.forEach((trace) => {
    const confidence = trace.v3DecisionDiagnostics?.confidenceDiagnostics;
    if (!confidence) {
      return;
    }
    evaluatedArticles += 1;
    totalConfidence += confidence.confidenceScore;
    highestConfidence = Math.max(highestConfidence, confidence.confidenceScore);
    lowestConfidence = Math.min(lowestConfidence, confidence.confidenceScore);
    incrementConfidenceBand(confidenceDistribution, confidence.confidenceBand);
    incrementConfidenceSignalCounts(strongestSignalCounts, confidence.strongestSignals);
    incrementConfidenceSignalCounts(weakestSignalCounts, confidence.weakestSignals);

    const decision = trace.v3DecisionDiagnostics?.suggestedDecision || "uncertain";
    const decisionBucket = byDecision.get(decision) || { decision, count: 0, totalConfidence: 0 };
    decisionBucket.count += 1;
    decisionBucket.totalConfidence += confidence.confidenceScore;
    byDecision.set(decision, decisionBucket);
  });

  return {
    enabled: true,
    evaluatedArticles,
    averageConfidence: evaluatedArticles ? Number((totalConfidence / evaluatedArticles).toFixed(1)) : 0,
    highestConfidence: evaluatedArticles ? highestConfidence : 0,
    lowestConfidence: evaluatedArticles ? lowestConfidence : 0,
    confidenceDistribution,
    averageByDecision: Array.from(byDecision.values()).map((entry) => ({
      decision: entry.decision,
      count: entry.count,
      averageConfidence: entry.count ? Number((entry.totalConfidence / entry.count).toFixed(1)) : 0,
    })),
    strongestSignals: getTopConfidenceSignals(strongestSignalCounts),
    weakestSignals: getTopConfidenceSignals(weakestSignalCounts),
  };
}

function buildProfessionalDecisionDiagnostics(article, options = {}) {
  const articleEvidence = options.articleEvidence || buildArticleEvidence(article);
  const confidenceDiagnostics = options.confidenceDiagnostics || buildV3Confidence(article, { articleEvidence });
  const documentEntries = []
    .concat(getEvidenceEntriesForGroup(articleEvidence, "domainObjects"))
    .concat(getEvidenceEntriesForGroup(articleEvidence, "documentTypes"));
  const professionalEntries = getEvidenceEntriesForGroup(articleEvidence, "professionalSignals");
  const noiseEntries = getEvidenceEntriesForGroup(articleEvidence, "noiseSignals");
  const eventEntries = getEvidenceEntriesForGroup(articleEvidence, "eventSignals");
  const strongDocumentCount = documentEntries.filter((entry) => entry?.strength === "strong").length;
  const strongProfessionalCount = professionalEntries.filter((entry) => entry?.strength === "strong").length;
  const strongNoiseCount = noiseEntries.filter((entry) => entry?.strength === "strong").length;
  const positiveFactors = [];
  const negativeFactors = [];
  const eventFactors = [];
  const noiseFactors = [];

  if (strongProfessionalCount > 0) {
    positiveFactors.push("strong_professional_signals");
  } else if (professionalEntries.length > 0) {
    positiveFactors.push("professional_signals");
  } else {
    negativeFactors.push("weak_professional_signals");
  }
  if (strongDocumentCount > 0) {
    positiveFactors.push("strong_document_evidence");
  } else if (documentEntries.length > 0) {
    positiveFactors.push("document_evidence");
  } else {
    negativeFactors.push("missing_document_evidence");
  }
  if (strongNoiseCount > 0) {
    noiseFactors.push("strong_noise_signals");
    negativeFactors.push("strong_noise_signals");
  } else if (noiseEntries.length > 0) {
    noiseFactors.push("noise_signals");
  } else {
    positiveFactors.push("low_noise");
  }
  if (eventEntries.length > 0) {
    eventFactors.push("event_signals");
  }
  if (professionalEntries.length > 0 && noiseEntries.length > 0) {
    negativeFactors.push("professional_noise_conflict");
  }

  let professionalDecision = "professional_uncertain";
  if (strongProfessionalCount > 0 && strongDocumentCount > 0 && strongNoiseCount === 0) {
    professionalDecision = "professional_include_candidate";
  } else if (strongNoiseCount > 0 && strongProfessionalCount === 0) {
    professionalDecision = "professional_reject_candidate";
  } else if (professionalEntries.length && documentEntries.length && !strongNoiseCount) {
    professionalDecision = "professional_include_candidate";
  } else if (noiseEntries.length && !professionalEntries.length) {
    professionalDecision = "professional_reject_candidate";
  }

  return {
    articleId: articleEvidence?.articleId || getFilterDecisionTraceArticleId(article),
    title: article?.title || "Untitled article",
    professionalDecision,
    confidence: confidenceDiagnostics.confidenceScore,
    confidenceBand: confidenceDiagnostics.confidenceBand,
    positiveFactors,
    negativeFactors,
    eventFactors,
    noiseFactors,
    explanation: [
      positiveFactors.length ? `positive: ${positiveFactors.join(", ")}` : "",
      negativeFactors.length ? `negative: ${negativeFactors.join(", ")}` : "",
      eventFactors.length ? `event: ${eventFactors.join(", ")}` : "",
    ].filter(Boolean).join("; "),
    legacyComparison: {},
  };
}

function getIdentityProfessionalGuardStage(trace) {
  return (Array.isArray(trace?.stages) ? trace.stages : []).find(
    (stage) => stage.stage === "identity_professional_relevance_guard"
  ) || null;
}

function getLegacyProfessionalDecision(trace) {
  const guardStage = getIdentityProfessionalGuardStage(trace);
  if (!guardStage) {
    return {
      legacyProfessionalDecision: "not_evaluated",
      legacyProfessionalPassed: null,
      legacyReason: "legacy professional relevance guard was not active",
    };
  }
  return {
    legacyProfessionalDecision: guardStage.result === "passed"
      ? "professional_include_candidate"
      : "professional_reject_candidate",
    legacyProfessionalPassed: guardStage.result === "passed",
    legacyReason: guardStage.reason || "",
  };
}

function getProfessionalDecisionParityReason(legacyDecision, professionalDecision, factors = []) {
  if (legacyDecision === "not_evaluated") {
    return "legacy professional guard not evaluated";
  }
  if (legacyDecision === professionalDecision) {
    return "legacy professional guard and V3 professional decision agree";
  }
  if (professionalDecision === "professional_uncertain") {
    return "V3 professional decision is uncertain";
  }
  if (legacyDecision === "professional_include_candidate" && professionalDecision === "professional_reject_candidate") {
    return factors.includes("strong_noise_signals")
      ? "V3 sees strong noise signals on a legacy professional pass"
      : "V3 professional decision rejected a legacy professional pass";
  }
  if (legacyDecision === "professional_reject_candidate" && professionalDecision === "professional_include_candidate") {
    return factors.includes("strong_professional_signals")
      ? "V3 sees strong professional signals on a legacy professional rejection"
      : "V3 professional decision included a legacy professional rejection";
  }
  return "professional decision mismatch";
}

function finalizeProfessionalDecisionDiagnostics(trace) {
  if (!trace?.professionalDecisionDiagnostics) {
    return null;
  }
  const legacyComparison = getLegacyProfessionalDecision(trace);
  const professionalDecision = trace.professionalDecisionDiagnostics.professionalDecision || "professional_uncertain";
  const parity = legacyComparison.legacyProfessionalDecision === "not_evaluated"
    ? "not_evaluated"
    : legacyComparison.legacyProfessionalDecision === professionalDecision
      ? "match"
      : professionalDecision === "professional_uncertain"
        ? "uncertain"
        : "mismatch";
  trace.professionalDecisionDiagnostics.legacyComparison = {
    ...legacyComparison,
    parity,
    parityReason: getProfessionalDecisionParityReason(
      legacyComparison.legacyProfessionalDecision,
      professionalDecision,
      trace.professionalDecisionDiagnostics.positiveFactors
        .concat(trace.professionalDecisionDiagnostics.negativeFactors || [])
    ),
  };
  return trace.professionalDecisionDiagnostics;
}

function getProfessionalDecisionDiagnostics(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return [];
  }
  return getHeavyDiagnosticsTraces(diagnostics)
    .map((trace) => trace.professionalDecisionDiagnostics || null)
    .filter(Boolean);
}

function getProfessionalDecisionDiagnosticsSummary(diagnostics) {
  const decisions = getProfessionalDecisionDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const decisionCounts = {
    professional_include_candidate: 0,
    professional_reject_candidate: 0,
    professional_uncertain: 0,
  };
  const factorCounts = new Map();
  decisions.forEach((decision) => {
    decisionCounts[decision.professionalDecision] = (decisionCounts[decision.professionalDecision] || 0) + 1;
    (decision.positiveFactors || []).concat(decision.negativeFactors || [], decision.eventFactors || [], decision.noiseFactors || [])
      .forEach((factor) => incrementReasonCount(factorCounts, factor));
  });
  return {
    enabled: true,
    evaluatedArticles: decisions.length,
    ...decisionCounts,
    topFactors: getTopV3DecisionReasons(factorCounts),
  };
}

function getProfessionalDecisionParitySummary(diagnostics) {
  const decisions = getProfessionalDecisionDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const matchReasons = new Map();
  const mismatchReasons = new Map();
  let legacyProfessionalPassed = 0;
  let legacyProfessionalRejected = 0;
  let v3ProfessionalInclude = 0;
  let v3ProfessionalReject = 0;
  let v3ProfessionalUncertain = 0;
  let matches = 0;
  let mismatches = 0;
  let uncertain = 0;

  decisions.forEach((decision) => {
    const legacyComparison = decision.legacyComparison || {};
    if (legacyComparison.legacyProfessionalPassed === true) {
      legacyProfessionalPassed += 1;
    } else if (legacyComparison.legacyProfessionalPassed === false) {
      legacyProfessionalRejected += 1;
    }
    if (decision.professionalDecision === "professional_include_candidate") {
      v3ProfessionalInclude += 1;
    } else if (decision.professionalDecision === "professional_reject_candidate") {
      v3ProfessionalReject += 1;
    } else {
      v3ProfessionalUncertain += 1;
    }
    if (legacyComparison.parity === "match") {
      matches += 1;
      incrementReasonCount(matchReasons, legacyComparison.parityReason);
    } else if (legacyComparison.parity === "mismatch") {
      mismatches += 1;
      incrementReasonCount(mismatchReasons, legacyComparison.parityReason);
    } else if (legacyComparison.parity === "uncertain") {
      uncertain += 1;
      incrementReasonCount(mismatchReasons, legacyComparison.parityReason);
    }
  });

  return {
    enabled: true,
    evaluatedArticles: decisions.length,
    legacyProfessionalPassed,
    legacyProfessionalRejected,
    v3ProfessionalInclude,
    v3ProfessionalReject,
    v3ProfessionalUncertain,
    matches,
    mismatches,
    uncertain,
    matchPercentage: decisions.length ? Number(((matches / decisions.length) * 100).toFixed(1)) : 0,
    topMatchReasons: getTopV3DecisionReasons(matchReasons),
    topMismatchReasons: getTopV3DecisionReasons(mismatchReasons),
  };
}

function getProfessionalDecisionExamples(diagnostics, limit = 10) {
  return getProfessionalDecisionDiagnostics(diagnostics)
    .slice(0, limit)
    .map((decision) => ({
      articleId: decision.articleId,
      title: decision.title,
      professionalDecision: decision.professionalDecision,
      confidence: decision.confidence,
      confidenceBand: decision.confidenceBand,
      legacyComparison: decision.legacyComparison,
    }));
}

function getProfessionalDecisionMismatchExamples(diagnostics, limit = 10) {
  return getProfessionalDecisionDiagnostics(diagnostics)
    .filter((decision) => ["mismatch", "uncertain"].includes(decision.legacyComparison?.parity))
    .slice(0, limit)
    .map((decision) => ({
      articleId: decision.articleId,
      title: decision.title,
      professionalDecision: decision.professionalDecision,
      confidence: decision.confidence,
      confidenceBand: decision.confidenceBand,
      legacyComparison: decision.legacyComparison,
      explanation: decision.explanation,
    }));
}

function buildPassportDecisionDiagnostics(article, options = {}) {
  const articleEvidence = options.articleEvidence || buildArticleEvidence(article);
  const confidenceDiagnostics = options.confidenceDiagnostics || buildV3Confidence(article, { articleEvidence });
  const documentEntries = []
    .concat(getEvidenceEntriesForGroup(articleEvidence, "domainObjects"))
    .concat(getEvidenceEntriesForGroup(articleEvidence, "documentTypes"));
  const professionalEntries = getEvidenceEntriesForGroup(articleEvidence, "professionalSignals");
  const noiseEntries = getEvidenceEntriesForGroup(articleEvidence, "noiseSignals");
  const eventEntries = getEvidenceEntriesForGroup(articleEvidence, "eventSignals");
  const strongDocumentCount = documentEntries.filter((entry) => entry?.strength === "strong").length;
  const strongProfessionalCount = professionalEntries.filter((entry) => entry?.strength === "strong").length;
  const strongNoiseCount = noiseEntries.filter((entry) => entry?.strength === "strong").length;
  const hasPassportEvidence = evidenceEntriesContainId(articleEvidence, "documentTypes", [
    "passport",
    "passports",
    "travel_document",
    "passport_issuance",
    "passport_renewal",
    "passport_application",
    "passport_office",
  ]);
  const positiveFactors = [];
  const negativeFactors = [];
  const noiseFactors = [];
  const professionalFactors = [];
  const eventFactors = [];
  const legacyShouldReject = shouldRejectPassportArticle(article);
  const hardPassportNoise = isHardPassportNoise(article);
  const lowRelevancePassportArticle = isLowRelevancePassportArticle(article);
  const highConfidencePassportAssessment = getHighConfidencePassportAssessment(article);
  const keesingIdentityRelevance = getKeesingIdentityRelevance(article);
  const uiRelevantIntelligenceArticle = isUiRelevantIntelligenceArticle(article);

  if (hasPassportEvidence || strongDocumentCount > 0) {
    positiveFactors.push("passport_or_document_evidence");
  } else {
    negativeFactors.push("weak_passport_document_evidence");
  }
  if (strongProfessionalCount > 0) {
    professionalFactors.push("strong_professional_signals");
    positiveFactors.push("strong_professional_signals");
  } else if (professionalEntries.length > 0) {
    professionalFactors.push("professional_signals");
  } else {
    negativeFactors.push("weak_professional_signals");
  }
  if (strongNoiseCount > 0) {
    noiseFactors.push("strong_noise_signals");
    negativeFactors.push("strong_noise_signals");
  } else if (noiseEntries.length > 0) {
    noiseFactors.push("noise_signals");
  } else {
    positiveFactors.push("low_noise");
  }
  if (eventEntries.length > 0) {
    eventFactors.push("event_signals");
  }
  if (hardPassportNoise) {
    noiseFactors.push("hard_passport_noise");
    negativeFactors.push("hard_passport_noise");
  }
  if (lowRelevancePassportArticle) {
    noiseFactors.push("low_relevance_passport_article");
    negativeFactors.push("low_relevance_passport_article");
  }
  if (highConfidencePassportAssessment?.kept) {
    professionalFactors.push("high_confidence_passport_assessment");
    positiveFactors.push("high_confidence_passport_assessment");
  } else if (highConfidencePassportAssessment?.rejectedReason) {
    negativeFactors.push(`high_confidence_passport_${highConfidencePassportAssessment.rejectedReason}`);
  }
  if (keesingIdentityRelevance?.hasRequiredComponent) {
    professionalFactors.push("keesing_identity_required_component");
    positiveFactors.push("keesing_identity_required_component");
  }
  if (uiRelevantIntelligenceArticle) {
    professionalFactors.push("ui_relevant_intelligence_article");
  }
  let passportDecision = "passport_uncertain";
  if (
    (hasPassportEvidence || strongDocumentCount > 0 || highConfidencePassportAssessment?.kept) &&
    (strongProfessionalCount > 0 || keesingIdentityRelevance?.hasRequiredComponent) &&
    !hardPassportNoise &&
    !lowRelevancePassportArticle &&
    strongNoiseCount === 0
  ) {
    passportDecision = "passport_include_candidate";
  } else if ((hardPassportNoise || lowRelevancePassportArticle || strongNoiseCount > 0) && strongProfessionalCount === 0) {
    passportDecision = "passport_reject_candidate";
  } else if (noiseEntries.length && !professionalEntries.length) {
    passportDecision = "passport_reject_candidate";
  } else if (hasPassportEvidence && professionalEntries.length && !strongNoiseCount) {
    passportDecision = "passport_include_candidate";
  }

  return {
    articleId: articleEvidence?.articleId || getFilterDecisionTraceArticleId(article),
    title: article?.title || "Untitled article",
    passportDecision,
    confidence: confidenceDiagnostics.confidenceScore,
    confidenceBand: confidenceDiagnostics.confidenceBand,
    positiveFactors,
    negativeFactors,
    noiseFactors,
    professionalFactors,
    eventFactors,
    explanation: [
      positiveFactors.length ? `positive: ${positiveFactors.join(", ")}` : "",
      negativeFactors.length ? `negative: ${negativeFactors.join(", ")}` : "",
      professionalFactors.length ? `professional: ${professionalFactors.join(", ")}` : "",
      noiseFactors.length ? `noise: ${noiseFactors.join(", ")}` : "",
      eventFactors.length ? `event: ${eventFactors.join(", ")}` : "",
    ].filter(Boolean).join("; "),
    legacyComparison: {
      legacyShouldReject,
      legacyDecision: legacyShouldReject ? "passport_reject_candidate" : "passport_include_candidate",
      hardPassportNoise,
      lowRelevancePassportArticle,
      highConfidencePassportAssessment,
      keesingIdentityRelevance,
      uiRelevantIntelligenceArticle,
    },
  };
}

function getPassportDecisionParityReason(legacyDecision, passportDecision, factors = []) {
  if (legacyDecision === passportDecision) {
    return "legacy shouldRejectPassportArticle and V3 passport decision agree";
  }
  if (passportDecision === "passport_uncertain") {
    return "V3 passport decision is uncertain";
  }
  if (legacyDecision === "passport_include_candidate" && passportDecision === "passport_reject_candidate") {
    return factors.includes("strong_noise_signals")
      ? "V3 sees strong noise signals on a legacy passport keep"
      : "V3 passport decision rejected a legacy passport keep";
  }
  if (legacyDecision === "passport_reject_candidate" && passportDecision === "passport_include_candidate") {
    return factors.includes("strong_professional_signals")
      ? "V3 sees strong professional signals on a legacy passport rejection"
      : "V3 passport decision included a legacy passport rejection";
  }
  return "passport decision mismatch";
}

function finalizePassportDecisionDiagnostics(trace) {
  if (!trace?.passportDecisionDiagnostics) {
    return null;
  }
  const legacyDecision = trace.passportDecisionDiagnostics.legacyComparison?.legacyDecision || "passport_include_candidate";
  const passportDecision = trace.passportDecisionDiagnostics.passportDecision || "passport_uncertain";
  const parity = legacyDecision === passportDecision
    ? "match"
    : passportDecision === "passport_uncertain"
      ? "uncertain"
      : "mismatch";
  trace.passportDecisionDiagnostics.legacyComparison = {
    ...(trace.passportDecisionDiagnostics.legacyComparison || {}),
    parity,
    parityReason: getPassportDecisionParityReason(
      legacyDecision,
      passportDecision,
      trace.passportDecisionDiagnostics.positiveFactors
        .concat(trace.passportDecisionDiagnostics.negativeFactors || [])
    ),
  };
  return trace.passportDecisionDiagnostics;
}

function getPassportDecisionDiagnostics(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return [];
  }
  return getHeavyDiagnosticsTraces(diagnostics)
    .map((trace) => trace.passportDecisionDiagnostics || null)
    .filter(Boolean);
}

function getPassportDecisionDiagnosticsSummary(diagnostics) {
  const decisions = getPassportDecisionDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const includeReasons = new Map();
  const rejectReasons = new Map();
  const uncertainReasons = new Map();
  let includeCandidateCount = 0;
  let rejectCandidateCount = 0;
  let uncertainCount = 0;
  let confidenceTotal = 0;
  decisions.forEach((decision) => {
    confidenceTotal += Number(decision.confidence || 0);
    const reasons = (decision.positiveFactors || []).concat(decision.negativeFactors || [], decision.noiseFactors || [], decision.professionalFactors || [], decision.eventFactors || []);
    if (decision.passportDecision === "passport_include_candidate") {
      includeCandidateCount += 1;
      reasons.forEach((reason) => incrementReasonCount(includeReasons, reason));
    } else if (decision.passportDecision === "passport_reject_candidate") {
      rejectCandidateCount += 1;
      reasons.forEach((reason) => incrementReasonCount(rejectReasons, reason));
    } else {
      uncertainCount += 1;
      reasons.forEach((reason) => incrementReasonCount(uncertainReasons, reason));
    }
  });
  return {
    enabled: true,
    evaluatedArticles: decisions.length,
    includeCandidateCount,
    rejectCandidateCount,
    uncertainCount,
    averageConfidence: decisions.length ? Number((confidenceTotal / decisions.length).toFixed(1)) : 0,
    topIncludeReasons: getTopV3DecisionReasons(includeReasons),
    topRejectReasons: getTopV3DecisionReasons(rejectReasons),
    topUncertainReasons: getTopV3DecisionReasons(uncertainReasons),
  };
}

function getPassportDecisionParitySummary(diagnostics) {
  const decisions = getPassportDecisionDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const matchReasons = new Map();
  const mismatchReasons = new Map();
  let legacyShouldRejectTriggered = 0;
  let legacyShouldKeep = 0;
  let v3PassportInclude = 0;
  let v3PassportReject = 0;
  let v3PassportUncertain = 0;
  let matches = 0;
  let mismatches = 0;
  let uncertain = 0;
  decisions.forEach((decision) => {
    const legacyComparison = decision.legacyComparison || {};
    if (legacyComparison.legacyShouldReject) {
      legacyShouldRejectTriggered += 1;
    } else {
      legacyShouldKeep += 1;
    }
    if (decision.passportDecision === "passport_include_candidate") {
      v3PassportInclude += 1;
    } else if (decision.passportDecision === "passport_reject_candidate") {
      v3PassportReject += 1;
    } else {
      v3PassportUncertain += 1;
    }
    if (legacyComparison.parity === "match") {
      matches += 1;
      incrementReasonCount(matchReasons, legacyComparison.parityReason);
    } else if (legacyComparison.parity === "mismatch") {
      mismatches += 1;
      incrementReasonCount(mismatchReasons, legacyComparison.parityReason);
    } else if (legacyComparison.parity === "uncertain") {
      uncertain += 1;
      incrementReasonCount(mismatchReasons, legacyComparison.parityReason);
    }
  });
  return {
    enabled: true,
    evaluatedArticles: decisions.length,
    legacyShouldRejectTriggered,
    legacyShouldKeep,
    v3PassportInclude,
    v3PassportReject,
    v3PassportUncertain,
    matches,
    mismatches,
    uncertain,
    matchPercentage: decisions.length ? Number(((matches / decisions.length) * 100).toFixed(1)) : 0,
    topMatchReasons: getTopV3DecisionReasons(matchReasons),
    topMismatchReasons: getTopV3DecisionReasons(mismatchReasons),
  };
}

