function createPassportDecisionTreeStep(helper, result, explanation = "", metadata = {}) {
  return {
    helper,
    condition: metadata.condition || helper,
    result,
    score: Number.isFinite(metadata.score) ? metadata.score : null,
    threshold: Number.isFinite(metadata.threshold) ? metadata.threshold : null,
    matchedSignals: Object.freeze(Array.isArray(metadata.matchedSignals) ? metadata.matchedSignals.slice() : []),
    rejected: Boolean(metadata.rejected),
    exitPoint: metadata.exitPoint || "",
    explanation,
    metadata,
  };
}

function getPassportDecisionTreeText(article) {
  return [
    article?.title,
    article?.summary,
    article?.description,
    article?.source,
    article?.topic,
    article?.topicType,
    getArticleTags(article).join(" "),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function collectPassportDecisionTreeSignalMatches(article, keywordGroups = {}) {
  const text = getPassportDecisionTreeText(article);
  if (!text) {
    return [];
  }
  const matches = [];
  Object.entries(keywordGroups).forEach(([group, keywords]) => {
    normalizeKeywordList(keywords).forEach((keyword) => {
      if (textMatchesKeyword(text, keyword)) {
        matches.push(`${group}:${keyword}`);
      }
    });
  });
  return Array.from(new Set(matches)).slice(0, 25);
}

function getPassportDecisionTreeHighConfidenceExitReason(assessment) {
  const rejectedReason = String(assessment?.rejectedReason || "").toLowerCase();
  if (rejectedReason.includes("no central identity signal")) {
    return "no_central_identity_signal";
  }
  if (rejectedReason.includes("primary subject unrelated")) {
    return "unrelated_passport_usage";
  }
  if (rejectedReason.includes("below high-confidence threshold")) {
    return "low_high_confidence_score";
  }
  return "weak_passport_identity_confidence";
}

function getPassportDecisionTreeNegativeContextExitReason(context = {}) {
  if (context.genericTravel) {
    return "travel_advisory_context";
  }
  if (context.unrelatedLifestyle) {
    return "consumer_passport_context";
  }
  if (context.education) {
    return "passport_fee_or_renewal_noise";
  }
  if (context.entertainment || context.sports || context.pets) {
    return "unrelated_passport_usage";
  }
  return "consumer_passport_context";
}

function getPassportDecisionTreeExitReason(tree) {
  return tree?.finalDecision?.exitReason || "unknown";
}

function tracePassportDecisionTree(article) {
  const articleId = getFilterDecisionTraceArticleId(article);
  const title = article?.title || "Untitled article";
  const steps = [];
  const helpersVisited = [];
  const helpersSkipped = [];
  const directHelperOrder = [
    "isPassportOrIdentityTopicArticle",
    "getHighConfidencePassportAssessment",
    "isHighConfidencePassportIntelligence",
    "getKeesingIdentityRelevance",
    "getIdentityContextSignals",
    "getIdentityDocumentRelevance",
  ];
  const markVisited = (helper) => {
    if (!helpersVisited.includes(helper)) {
      helpersVisited.push(helper);
    }
  };
  const markSkipped = (helper) => {
    if (!helpersVisited.includes(helper) && !helpersSkipped.includes(helper)) {
      helpersSkipped.push(helper);
    }
  };
  const skipRemaining = () => {
    directHelperOrder.forEach(markSkipped);
  };
  const addStep = (helper, result, explanation = "", metadata = {}) => {
    markVisited(helper);
    steps.push(createPassportDecisionTreeStep(helper, result, explanation, metadata));
  };
  const finish = (legacyReject, exitHelper, exitReason, explanation, options = {}) => {
    skipRemaining();
    const decisionPath = steps.map((step) => `${step.helper}:${String(step.result)}`);
    const legacyHelperResult = shouldRejectPassportArticle(article);
    const finalMatchedSignals = Array.from(new Set(
      steps.flatMap((step) => Array.isArray(step.matchedSignals) ? step.matchedSignals : [])
    ));
    return {
      articleId,
      title,
      steps,
      finalDecision: {
        legacyReject,
        legacyHelperResult,
        exitPoint: exitHelper,
        exitReason,
        explanation,
      },
      decisionPath,
      decisionDepth: steps.length,
      exitHelper,
      exitReason,
      helpersVisited,
      helpersSkipped,
      helpersSkippedCount: helpersSkipped.length,
      helpersVisitedCount: helpersVisited.length,
      matchedSignals: finalMatchedSignals,
      matchedRejectSignals: legacyReject ? finalMatchedSignals : [],
      matchedKeepSignals: legacyReject ? [] : finalMatchedSignals,
      relatedHelperDiagnostics: {
        isHardPassportNoise: isHardPassportNoise(article),
        isLowRelevancePassportArticle: isLowRelevancePassportArticle(article),
        isUiRelevantIntelligenceArticle: isUiRelevantIntelligenceArticle(article),
      },
      clarity: options.clarity || (exitReason === "unknown" ? "unclear" : "clear"),
      mismatchWithLegacyHelper: legacyReject !== legacyHelperResult,
    };
  };

  const passportOrIdentityTopic = isPassportOrIdentityTopicArticle(article);
  addStep(
    "isPassportOrIdentityTopicArticle",
    passportOrIdentityTopic,
    passportOrIdentityTopic
      ? "article is in passport or identity topic scope"
      : "article is outside passport or identity topic scope",
    {
      condition: "if (!isPassportOrIdentityTopicArticle(article)) return false",
      matchedSignals: collectPassportDecisionTreeSignalMatches(article, {
        passport: ["passport", "passports", "travel document"],
        identity: ["identity document", "identity documents", "digital identity", "visa", "border"],
      }),
      rejected: false,
      exitPoint: passportOrIdentityTopic ? "" : "isPassportOrIdentityTopicArticle",
    }
  );
  if (!passportOrIdentityTopic) {
    return finish(false, "isPassportOrIdentityTopicArticle", "outside_passport_identity_scope", "legacy helper exits early and keeps non-passport/non-identity article");
  }

  const highConfidencePassportAssessment = getHighConfidencePassportAssessment(article);
  const highConfidencePassportIntelligence = isHighConfidencePassportIntelligence(article);
  addStep(
    "getHighConfidencePassportAssessment",
    Boolean(highConfidencePassportAssessment?.kept),
    highConfidencePassportAssessment?.kept
      ? "high-confidence passport assessment kept article"
      : highConfidencePassportAssessment?.rejectedReason || "high-confidence passport assessment rejected article",
    {
      ...highConfidencePassportAssessment,
      condition: "if (!isHighConfidencePassportIntelligence(article)) return true",
      score: Number(highConfidencePassportAssessment?.score),
      threshold: HIGH_CONFIDENCE_PASSPORT_THRESHOLD,
      matchedSignals: collectPassportDecisionTreeSignalMatches(article, {
        positive: HIGH_CONFIDENCE_PASSPORT_POSITIVE_SIGNALS,
        negative: HIGH_CONFIDENCE_PASSPORT_NEGATIVE_SIGNALS,
        sourcePositive: PRIMARY_PASSPORT_SOURCE_POSITIVE_SIGNALS,
        sourceNegative: PRIMARY_PASSPORT_SOURCE_NEGATIVE_SIGNALS,
      }),
      rejected: !highConfidencePassportAssessment?.kept,
      exitPoint: highConfidencePassportAssessment?.kept ? "" : "getHighConfidencePassportAssessment",
    }
  );
  addStep(
    "isHighConfidencePassportIntelligence",
    Boolean(highConfidencePassportIntelligence),
    highConfidencePassportIntelligence
      ? "wrapper result kept article"
      : "wrapper result rejected article because high-confidence assessment was not kept",
    {
      condition: "if (!isHighConfidencePassportIntelligence(article)) return true",
      score: Number(highConfidencePassportAssessment?.score),
      threshold: HIGH_CONFIDENCE_PASSPORT_THRESHOLD,
      matchedSignals: collectPassportDecisionTreeSignalMatches(article, {
        positive: HIGH_CONFIDENCE_PASSPORT_POSITIVE_SIGNALS,
        negative: HIGH_CONFIDENCE_PASSPORT_NEGATIVE_SIGNALS,
      }),
      rejected: !highConfidencePassportIntelligence,
      exitPoint: highConfidencePassportIntelligence ? "" : "isHighConfidencePassportIntelligence",
    }
  );
  if (!highConfidencePassportIntelligence) {
    return finish(
      true,
      "isHighConfidencePassportIntelligence",
      getPassportDecisionTreeHighConfidenceExitReason(highConfidencePassportAssessment),
      "legacy helper rejects when high-confidence passport intelligence is false"
    );
  }

  const keesingAssessment = getKeesingIdentityRelevance(article);
  addStep(
    "getKeesingIdentityRelevance",
    Boolean(keesingAssessment?.hasRequiredComponent),
    keesingAssessment?.hasRequiredComponent
      ? "Keesing relevance has required component"
      : "Keesing relevance missing required component",
    {
      ...keesingAssessment,
      condition: "if (!keesingAssessment.hasRequiredComponent) return true",
      score: Number(keesingAssessment?.score),
      threshold: KEESING_RELEVANCE_THRESHOLD,
      matchedSignals: collectPassportDecisionTreeSignalMatches(article, {
        positive: Object.values(KEESING_POSITIVE_SIGNALS).flat(),
        negative: Object.values(KEESING_NEGATIVE_SIGNALS).flat(),
        hardKeep: KEESING_HARD_KEEP_SIGNALS,
        required: KEESING_REQUIRED_COMPONENT_SIGNALS,
      }),
      rejected: !keesingAssessment?.hasRequiredComponent,
      exitPoint: keesingAssessment?.hasRequiredComponent ? "" : "getKeesingIdentityRelevance.hasRequiredComponent",
    }
  );
  if (!keesingAssessment?.hasRequiredComponent) {
    return finish(true, "getKeesingIdentityRelevance.hasRequiredComponent", "weak_keesing_identity_relevance", "legacy helper rejects when required Keesing component is missing");
  }
  addStep(
    "getKeesingIdentityRelevance.primarySubject",
    keesingAssessment.primarySubject !== "unrelated",
    keesingAssessment.primarySubject === "unrelated"
      ? "Keesing primary subject is unrelated"
      : `Keesing primary subject is ${keesingAssessment.primarySubject || "unknown"}`,
    {
      condition: "if (keesingAssessment.primarySubject === \"unrelated\") return true",
      matchedSignals: [`primarySubject:${keesingAssessment.primarySubject || "unknown"}`],
      rejected: keesingAssessment.primarySubject === "unrelated",
      exitPoint: keesingAssessment.primarySubject === "unrelated" ? "getKeesingIdentityRelevance.primarySubject" : "",
    }
  );
  if (keesingAssessment.primarySubject === "unrelated") {
    return finish(true, "getKeesingIdentityRelevance.primarySubject", "unrelated_passport_usage", "legacy helper rejects unrelated Keesing primary subject");
  }
  addStep(
    "getKeesingIdentityRelevance.score",
    Number(keesingAssessment.score || 0) >= KEESING_RELEVANCE_THRESHOLD,
    `Keesing score ${Number(keesingAssessment.score || 0)} compared to threshold ${KEESING_RELEVANCE_THRESHOLD}`,
    {
      condition: `if (keesingAssessment.score < ${KEESING_RELEVANCE_THRESHOLD}) return true`,
      score: keesingAssessment.score,
      threshold: KEESING_RELEVANCE_THRESHOLD,
      matchedSignals: collectPassportDecisionTreeSignalMatches(article, {
        positive: Object.values(KEESING_POSITIVE_SIGNALS).flat(),
        negative: Object.values(KEESING_NEGATIVE_SIGNALS).flat(),
      }),
      rejected: Number(keesingAssessment.score || 0) < KEESING_RELEVANCE_THRESHOLD,
      exitPoint: Number(keesingAssessment.score || 0) < KEESING_RELEVANCE_THRESHOLD ? "getKeesingIdentityRelevance.score" : "",
    }
  );
  if (Number(keesingAssessment.score || 0) < KEESING_RELEVANCE_THRESHOLD) {
    return finish(true, "getKeesingIdentityRelevance.score", "weak_keesing_identity_relevance", "legacy helper rejects below Keesing relevance threshold");
  }

  const context = getIdentityContextSignals(article);
  const hasStrongPositiveContext = context.government
    || context.border
    || context.immigration
    || context.fraud
    || context.security
    || context.issuance
    || context.infrastructure
    || context.travelRule;
  addStep(
    "getIdentityContextSignals.strongPositiveContext",
    Boolean(hasStrongPositiveContext),
    hasStrongPositiveContext
      ? "strong positive identity context found"
      : "no strong positive identity context found",
    {
      ...context,
      condition: "if (hasStrongPositiveContext) return false",
      matchedSignals: Object.entries(context)
        .filter(([, value]) => Boolean(value))
        .map(([key]) => `identityContext:${key}`),
      rejected: false,
      exitPoint: hasStrongPositiveContext ? "getIdentityContextSignals.strongPositiveContext" : "",
    }
  );
  if (hasStrongPositiveContext) {
    markSkipped("getIdentityDocumentRelevance");
    return finish(false, "getIdentityContextSignals.strongPositiveContext", "kept_by_professional_identity_signal", "legacy helper keeps article when strong positive identity context is found");
  }

  const negativeContextCount = [
    context.unrelatedLifestyle,
    context.sports,
    context.pets,
    context.entertainment,
    context.education,
    context.genericTravel,
  ].filter(Boolean).length;
  addStep(
    "getIdentityContextSignals.negativeContext",
    negativeContextCount > 0,
    negativeContextCount > 0
      ? `${negativeContextCount} negative context flags found`
      : "no negative context flags found",
    {
      condition: "return negativeContextCount > 0 && getIdentityDocumentRelevance(article) < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD",
      negativeContextCount,
      context,
      matchedSignals: Object.entries(context)
        .filter(([, value]) => Boolean(value))
        .map(([key]) => `identityContext:${key}`),
      rejected: false,
    }
  );
  if (!negativeContextCount) {
    markSkipped("getIdentityDocumentRelevance");
    return finish(false, "getIdentityContextSignals.negativeContext", "kept_by_high_confidence_passport", "legacy helper keeps article because no negative context flags are present");
  }

  const identityDocumentRelevance = getIdentityDocumentRelevance(article);
  addStep(
    "getIdentityDocumentRelevance",
    identityDocumentRelevance < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD,
    `identity document relevance ${identityDocumentRelevance} compared to threshold ${IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD}`,
    {
      condition: `return negativeContextCount > 0 && identityDocumentRelevance < ${IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD}`,
      identityDocumentRelevance,
      threshold: IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD,
      score: identityDocumentRelevance,
      matchedSignals: Object.entries(context)
        .filter(([, value]) => Boolean(value))
        .map(([key]) => `identityContext:${key}`),
      rejected: identityDocumentRelevance < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD,
      exitPoint: "getIdentityDocumentRelevance",
    }
  );
  return finish(
    identityDocumentRelevance < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD,
    "getIdentityDocumentRelevance",
    identityDocumentRelevance < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD
      ? getPassportDecisionTreeNegativeContextExitReason(context)
      : "kept_by_high_confidence_passport",
    identityDocumentRelevance < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD
      ? "legacy helper rejects negative-context article below identity-document relevance threshold"
      : "legacy helper keeps negative-context article at or above identity-document relevance threshold"
  );
}

function getPassportDecisionTreeDiagnostics(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return [];
  }
  return getHeavyDiagnosticsTraces(diagnostics)
    .map((trace) => trace.passportDecisionTreeDiagnostics || null)
    .filter(Boolean);
}

function getPassportDecisionTreeSummary(diagnostics) {
  const decisionTrees = getPassportDecisionTreeDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const exitHelperCounts = new Map();
  const helperExecutionCounts = new Map();
  const helperSkipCounts = new Map();
  const decisionPathCounts = new Map();
  let totalDecisionDepth = 0;

  decisionTrees.forEach((tree) => {
    totalDecisionDepth += Number(tree.decisionDepth || 0);
    incrementReasonCount(exitHelperCounts, tree.exitHelper || "unknown");
    (tree.helpersVisited || []).forEach((helper) => incrementReasonCount(helperExecutionCounts, helper));
    (tree.helpersSkipped || []).forEach((helper) => incrementReasonCount(helperSkipCounts, helper));
    incrementReasonCount(decisionPathCounts, (tree.decisionPath || []).join(" > ") || "unknown");
  });

  return {
    enabled: true,
    evaluatedArticles: decisionTrees.length,
    mostCommonExitHelpers: getTopV3DecisionReasons(exitHelperCounts),
    averageDecisionDepth: decisionTrees.length ? Number((totalDecisionDepth / decisionTrees.length).toFixed(2)) : 0,
    helperExecutionFrequency: getTopV3DecisionReasons(helperExecutionCounts, 20),
    helperSkipFrequency: getTopV3DecisionReasons(helperSkipCounts, 20),
    mostCommonDecisionPaths: getTopV3DecisionReasons(decisionPathCounts, 20),
  };
}

function getPassportDecisionTreeV2Summary(diagnostics) {
  const decisionTrees = getPassportDecisionTreeDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const exitReasonCounts = new Map();
  const exitHelperCounts = new Map();
  const rejectSignalCounts = new Map();
  const keepSignalCounts = new Map();
  let rejectCount = 0;
  let keepCount = 0;
  let totalDecisionDepth = 0;

  decisionTrees.forEach((tree) => {
    const legacyReject = Boolean(tree.finalDecision?.legacyReject);
    if (legacyReject) {
      rejectCount += 1;
      (tree.matchedRejectSignals || []).forEach((signal) => incrementReasonCount(rejectSignalCounts, signal));
    } else {
      keepCount += 1;
      (tree.matchedKeepSignals || []).forEach((signal) => incrementReasonCount(keepSignalCounts, signal));
    }
    totalDecisionDepth += Number(tree.decisionDepth || 0);
    incrementReasonCount(exitReasonCounts, tree.exitReason || getPassportDecisionTreeExitReason(tree));
    incrementReasonCount(exitHelperCounts, tree.exitHelper || "unknown");
  });

  return {
    enabled: true,
    evaluatedArticles: decisionTrees.length,
    rejectCount,
    keepCount,
    mostCommonExitReasons: getTopV3DecisionReasons(exitReasonCounts, 20),
    mostCommonExitHelpers: getTopV3DecisionReasons(exitHelperCounts, 20),
    averageDecisionDepth: decisionTrees.length ? Number((totalDecisionDepth / decisionTrees.length).toFixed(2)) : 0,
    topMatchedRejectSignals: getTopV3DecisionReasons(rejectSignalCounts, 20),
    topMatchedKeepSignals: getTopV3DecisionReasons(keepSignalCounts, 20),
  };
}

function getPassportDecisionTreeExamples(diagnostics, limit = 10) {
  return getPassportDecisionTreeDiagnostics(diagnostics)
    .slice(0, limit)
    .map((tree) => ({
      articleId: tree.articleId,
      title: tree.title,
      finalDecision: tree.finalDecision,
      decisionDepth: tree.decisionDepth,
      exitHelper: tree.exitHelper,
      helpersVisited: tree.helpersVisited,
      helpersSkipped: tree.helpersSkipped,
      decisionPath: tree.decisionPath,
    }));
}

function getPassportDecisionTreeExamplesByDecision(diagnostics, decisionType, limit = 10) {
  return getPassportDecisionTreeDiagnostics(diagnostics)
    .filter((tree) => {
      if (decisionType === "reject") {
        return Boolean(tree.finalDecision?.legacyReject);
      }
      if (decisionType === "keep") {
        return !tree.finalDecision?.legacyReject;
      }
      return tree.clarity === "unclear" || Boolean(tree.mismatchWithLegacyHelper);
    })
    .slice(0, limit)
    .map((tree) => ({
      articleId: tree.articleId,
      title: tree.title,
      finalDecision: tree.finalDecision,
      decisionDepth: tree.decisionDepth,
      exitHelper: tree.exitHelper,
      exitReason: tree.exitReason,
      matchedSignals: tree.matchedSignals,
      decisionPath: tree.decisionPath,
    }));
}

function getPassportDecisionPaths(diagnostics, limit = 25) {
  const pathCounts = new Map();
  getPassportDecisionTreeDiagnostics(diagnostics).forEach((tree) => {
    incrementReasonCount(pathCounts, (tree.decisionPath || []).join(" > ") || "unknown");
  });
  return getTopV3DecisionReasons(pathCounts, limit);
}

function getPassportDecisionExitReasons(diagnostics, limit = 25) {
  const exitReasonCounts = new Map();
  getPassportDecisionTreeDiagnostics(diagnostics).forEach((tree) => {
    incrementReasonCount(exitReasonCounts, tree.exitReason || getPassportDecisionTreeExitReason(tree));
  });
  return getTopV3DecisionReasons(exitReasonCounts, limit);
}

function getPassportDecisionExitHelpers(diagnostics, limit = 25) {
  const exitHelperCounts = new Map();
  getPassportDecisionTreeDiagnostics(diagnostics).forEach((tree) => {
    incrementReasonCount(exitHelperCounts, tree.exitHelper || "unknown");
  });
  return getTopV3DecisionReasons(exitHelperCounts, limit);
}

function getPassportDecisionV3Confidence(options = {}) {
  const {
    finalDecision,
    exitReason,
    highConfidencePassportAssessment,
    keesingAssessment,
    identityDocumentRelevance,
    hasStrongPositiveContext,
    negativeContextCount,
  } = options;
  let confidence = finalDecision === "keep" ? 62 : finalDecision === "reject" ? 68 : 48;
  if (exitReason === "outside_passport_identity_scope") {
    confidence = 92;
  } else if (exitReason === "kept_by_professional_identity_signal") {
    confidence = 88;
  } else if (exitReason === "no_central_identity_signal" || exitReason === "unrelated_passport_usage") {
    confidence = 86;
  } else if (exitReason === "weak_keesing_identity_relevance") {
    confidence = 82;
  } else if (exitReason === "low_high_confidence_score") {
    const scoreGap = HIGH_CONFIDENCE_PASSPORT_THRESHOLD - Number(highConfidencePassportAssessment?.score || 0);
    confidence = Math.max(55, Math.min(86, 62 + scoreGap * 2));
  } else if (exitReason === "consumer_passport_context" || exitReason === "travel_advisory_context") {
    const scoreGap = IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD - Number(identityDocumentRelevance || 0);
    confidence = Math.max(58, Math.min(84, 64 + negativeContextCount * 5 + scoreGap * 2));
  } else if (exitReason === "kept_by_high_confidence_passport") {
    confidence = negativeContextCount > 0 ? 70 : 78;
  }
  if (hasStrongPositiveContext) {
    confidence += 4;
  }
  if (Number(keesingAssessment?.score || 0) >= KEESING_RELEVANCE_THRESHOLD + 10) {
    confidence += 3;
  }
  return Math.max(0, Math.min(100, Math.round(confidence)));
}

function getPassportDecisionV3Category(exitReason, finalDecision) {
  if (finalDecision === "keep") {
    if (exitReason === "outside_passport_identity_scope") {
      return "out_of_scope_keep";
    }
    if (exitReason === "kept_by_professional_identity_signal") {
      return "professional_identity_keep";
    }
    return "passport_identity_keep";
  }
  if (finalDecision === "uncertain") {
    return "passport_identity_uncertain";
  }
  if (exitReason === "hard_passport_noise") {
    return "hard_noise";
  }
  if (exitReason === "weak_keesing_identity_relevance") {
    return "professional_relevance";
  }
  if (
    exitReason === "consumer_passport_context" ||
    exitReason === "travel_advisory_context" ||
    exitReason === "passport_fee_or_renewal_noise" ||
    exitReason === "citizenship_debate_context"
  ) {
    return "consumer_passport_noise";
  }
  if (exitReason === "ui_relevance_false") {
    return "ui_relevance";
  }
  if (exitReason === "unrelated_passport_usage") {
    return "unrelated_usage";
  }
  return "passport_identity_confidence";
}

function getPassportDecisionV3NoiseContextReason(noiseSignals = [], fallbackContext = {}) {
  const noiseText = noiseSignals
    .map((signal) => [
      signal?.id,
      signal?.category,
      signal?.term,
      signal?.matchedTerm,
    ].filter(Boolean).join(" "))
    .join(" ")
    .toLowerCase();
  if (noiseText.includes("citizenship")) {
    return "citizenship_debate_context";
  }
  if (noiseText.includes("renewal") || noiseText.includes("fee") || noiseText.includes("appointment")) {
    return "passport_fee_or_renewal_noise";
  }
  if (noiseText.includes("travel") || noiseText.includes("tourism") || fallbackContext.genericTravel) {
    return "travel_advisory_context";
  }
  return getPassportDecisionTreeNegativeContextExitReason(fallbackContext);
}

function PassportDecisionEngineV3(article, options = {}) {
  const articleId = getFilterDecisionTraceArticleId(article);
  const title = article?.title || "Untitled article";
  const articleEvidence = options.articleEvidence || buildArticleEvidence(article);
  const evidence = articleEvidence?.evidence || {};
  const professionalSignals = getEvidenceEntriesForGroup(articleEvidence, "professionalSignals");
  const noiseSignals = getEvidenceEntriesForGroup(articleEvidence, "noiseSignals");
  const eventSignals = getEvidenceEntriesForGroup(articleEvidence, "eventSignals");
  const triggeredRules = [];
  const decisionPath = [];
  const scoreBreakdown = {};
  const addRule = (rule, result, metadata = {}) => {
    triggeredRules.push({
      rule,
      result,
      metadata,
    });
    decisionPath.push(`${rule}:${String(result)}`);
  };
  const finish = (finalDecision, exitRule, rejectionReason, options = {}) => {
    const exitReason = rejectionReason || (finalDecision === "keep" ? "kept_by_high_confidence_passport" : "unknown");
    const confidence = getPassportDecisionV3Confidence({
      ...options,
      finalDecision,
      exitReason,
    });
    return {
      articleId,
      title,
      decision: finalDecision,
      finalDecision,
      accepted: finalDecision === "keep",
      rejected: finalDecision === "reject",
      confidence,
      decisionPath,
      triggeredRules,
      rejectionReason: finalDecision === "reject" || finalDecision === "uncertain" ? exitReason : "",
      rejectionCategory: getPassportDecisionV3Category(exitReason, finalDecision),
      exitRule,
      exitReason,
      evidence,
      professionalSignals,
      noiseSignals,
      eventSignals,
      scoreBreakdown,
    };
  };

  const passportOrIdentityTopic = isPassportOrIdentityTopicArticle(article);
  addRule("isPassportOrIdentityTopicArticle", passportOrIdentityTopic);
  if (!passportOrIdentityTopic) {
    return finish("keep", "isPassportOrIdentityTopicArticle", "outside_passport_identity_scope");
  }

  const hardPassportNoise = isHardPassportNoise(article);
  scoreBreakdown.hardPassportNoise = {
    matched: Boolean(hardPassportNoise),
  };
  addRule("isHardPassportNoise", Boolean(hardPassportNoise), scoreBreakdown.hardPassportNoise);
  if (hardPassportNoise) {
    return finish("reject", "isHardPassportNoise", "hard_passport_noise");
  }

  const highConfidencePassportAssessment = getHighConfidencePassportAssessment(article);
  scoreBreakdown.highConfidencePassport = {
    score: Number(highConfidencePassportAssessment?.score || 0),
    threshold: HIGH_CONFIDENCE_PASSPORT_THRESHOLD,
    primarySubject: highConfidencePassportAssessment?.primarySubject || "",
    kept: Boolean(highConfidencePassportAssessment?.kept),
    rejectedReason: highConfidencePassportAssessment?.rejectedReason || "",
  };
  addRule("getHighConfidencePassportAssessment", Boolean(highConfidencePassportAssessment?.kept), scoreBreakdown.highConfidencePassport);
  addRule("isHighConfidencePassportIntelligence", Boolean(highConfidencePassportAssessment?.kept), scoreBreakdown.highConfidencePassport);
  if (!highConfidencePassportAssessment?.kept) {
    return finish(
      "reject",
      "isHighConfidencePassportIntelligence",
      getPassportDecisionTreeHighConfidenceExitReason(highConfidencePassportAssessment),
      { highConfidencePassportAssessment }
    );
  }

  const keesingAssessment = getKeesingIdentityRelevance(article);
  scoreBreakdown.keesingIdentity = {
    score: Number(keesingAssessment?.score || 0),
    threshold: KEESING_RELEVANCE_THRESHOLD,
    primarySubject: keesingAssessment?.primarySubject || "",
    hasRequiredComponent: Boolean(keesingAssessment?.hasRequiredComponent),
  };
  addRule("getKeesingIdentityRelevance", Boolean(keesingAssessment?.hasRequiredComponent), scoreBreakdown.keesingIdentity);
  if (!keesingAssessment?.hasRequiredComponent) {
    return finish("reject", "getKeesingIdentityRelevance.hasRequiredComponent", "weak_keesing_identity_relevance", { keesingAssessment });
  }
  addRule("getKeesingIdentityRelevance.primarySubject", keesingAssessment.primarySubject !== "unrelated", {
    primarySubject: keesingAssessment.primarySubject,
  });
  if (keesingAssessment.primarySubject === "unrelated") {
    return finish("reject", "getKeesingIdentityRelevance.primarySubject", "unrelated_passport_usage", { keesingAssessment });
  }
  addRule("getKeesingIdentityRelevance.score", Number(keesingAssessment.score || 0) >= KEESING_RELEVANCE_THRESHOLD, scoreBreakdown.keesingIdentity);
  if (Number(keesingAssessment.score || 0) < KEESING_RELEVANCE_THRESHOLD) {
    return finish("reject", "getKeesingIdentityRelevance.score", "weak_keesing_identity_relevance", { keesingAssessment });
  }

  const uiRelevant = isUiRelevantIntelligenceArticle(article);
  const hasStrongProfessionalSignals = professionalSignals.some((signal) => signal?.strength === "strong");
  scoreBreakdown.uiRelevance = {
    uiRelevant,
    hasStrongProfessionalSignals,
    professionalSignalCount: professionalSignals.length,
  };
  addRule("isUiRelevantIntelligenceArticle", Boolean(uiRelevant), scoreBreakdown.uiRelevance);
  if (!uiRelevant && !hasStrongProfessionalSignals) {
    return finish("uncertain", "isUiRelevantIntelligenceArticle", "ui_relevance_false", {
      keesingAssessment,
    });
  }

  const context = getIdentityContextSignals(article);
  const hasStrongPositiveContext = context.government
    || context.border
    || context.immigration
    || context.fraud
    || context.security
    || context.issuance
    || context.infrastructure
    || context.travelRule;
  scoreBreakdown.identityContext = { ...context, hasStrongPositiveContext };
  addRule("getIdentityContextSignals.strongPositiveContext", Boolean(hasStrongPositiveContext), scoreBreakdown.identityContext);
  if (hasStrongPositiveContext || hasStrongProfessionalSignals) {
    return finish("keep", "getIdentityContextSignals.strongPositiveContext", "kept_by_professional_identity_signal", {
      keesingAssessment,
      hasStrongPositiveContext,
    });
  }

  const negativeContextCount = [
    context.unrelatedLifestyle,
    context.sports,
    context.pets,
    context.entertainment,
    context.education,
    context.genericTravel,
  ].filter(Boolean).length;
  const noiseContextReason = getPassportDecisionV3NoiseContextReason(noiseSignals, context);
  addRule("getIdentityContextSignals.negativeContext", negativeContextCount > 0, {
    negativeContextCount,
    context,
    noiseContextReason,
  });
  if (!negativeContextCount) {
    return finish("keep", "getIdentityContextSignals.negativeContext", "kept_by_high_confidence_passport", {
      keesingAssessment,
      negativeContextCount,
    });
  }

  const identityDocumentRelevance = getIdentityDocumentRelevance(article);
  scoreBreakdown.identityDocumentRelevance = {
    score: Number(identityDocumentRelevance || 0),
    threshold: IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD,
  };
  const relevanceBelowThreshold = identityDocumentRelevance < IDENTITY_DOCUMENT_RELEVANCE_THRESHOLD;
  addRule("getIdentityDocumentRelevance", relevanceBelowThreshold, scoreBreakdown.identityDocumentRelevance);
  return finish(
    relevanceBelowThreshold ? "reject" : "keep",
    "getIdentityDocumentRelevance",
    relevanceBelowThreshold ? noiseContextReason : "kept_by_high_confidence_passport",
    {
      keesingAssessment,
      identityDocumentRelevance,
      negativeContextCount,
    }
  );
}

function normalizePassportLegacyDecision(tree) {
  const legacyReject = Boolean(tree?.finalDecision?.legacyReject);
  return legacyReject ? "reject" : "keep";
}

function getPassportLegacyCategory(tree) {
  return getPassportDecisionV3Category(tree?.exitReason || getPassportDecisionTreeExitReason(tree), normalizePassportLegacyDecision(tree));
}

function comparePassportDecisionV3WithLegacy(passportDecisionV3, legacyTree) {
  if (!passportDecisionV3 || !legacyTree) {
    return null;
  }
  const legacyDecision = normalizePassportLegacyDecision(legacyTree);
  const v3Decision = passportDecisionV3.finalDecision || "";
  const legacyReason = legacyTree.exitReason || getPassportDecisionTreeExitReason(legacyTree);
  const v3Reason = passportDecisionV3.rejectionReason || passportDecisionV3.exitReason || "";
  const legacyCategory = getPassportLegacyCategory(legacyTree);
  const v3Category = passportDecisionV3.rejectionCategory || "";
  const legacyDecisionPath = Array.isArray(legacyTree.decisionPath) ? legacyTree.decisionPath : [];
  const v3DecisionPath = Array.isArray(passportDecisionV3.decisionPath) ? passportDecisionV3.decisionPath : [];
  return {
    legacyDecision,
    v3Decision,
    sameDecision: legacyDecision === v3Decision,
    legacyReason,
    v3Reason,
    sameReason: legacyReason === v3Reason,
    legacyCategory,
    v3Category,
    sameCategory: legacyCategory === v3Category,
    legacyDecisionPath,
    v3DecisionPath,
    sameDecisionPath: legacyDecisionPath.join(" > ") === v3DecisionPath.join(" > "),
    confidenceDifference: Number((100 - Number(passportDecisionV3.confidence || 0)).toFixed(1)),
    decisionDifference: legacyDecision === v3Decision ? "same" : `${legacyDecision}_vs_${v3Decision}`,
  };
}

function getPassportDecisionV3Diagnostics(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return [];
  }
  return getHeavyDiagnosticsTraces(diagnostics)
    .map((trace) => trace.passportDecisionV3Diagnostics || null)
    .filter(Boolean);
}

function getPassportDecisionComparisonDiagnostics(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return [];
  }
  return getHeavyDiagnosticsTraces(diagnostics)
    .map((trace) => trace.passportDecisionComparison || null)
    .filter(Boolean);
}

function getPassportDecisionComparisonSummary(diagnostics) {
  const comparisons = getPassportDecisionComparisonDiagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  let legacyKept = 0;
  let legacyRejected = 0;
  let v3Kept = 0;
  let v3Rejected = 0;
  let v3Uncertain = 0;
  let perfectMatches = 0;
  let decisionMismatches = 0;
  let categoryMismatches = 0;
  let reasonMismatches = 0;
  let pathMismatches = 0;
  comparisons.forEach((comparison) => {
    if (comparison.legacyDecision === "reject") {
      legacyRejected += 1;
    } else {
      legacyKept += 1;
    }
    if (comparison.v3Decision === "reject") {
      v3Rejected += 1;
    } else if (comparison.v3Decision === "uncertain") {
      v3Uncertain += 1;
    } else {
      v3Kept += 1;
    }
    if (comparison.sameDecision && comparison.sameCategory && comparison.sameReason && comparison.sameDecisionPath) {
      perfectMatches += 1;
    }
    if (!comparison.sameDecision) {
      decisionMismatches += 1;
    }
    if (!comparison.sameCategory) {
      categoryMismatches += 1;
    }
    if (!comparison.sameReason) {
      reasonMismatches += 1;
    }
    if (!comparison.sameDecisionPath) {
      pathMismatches += 1;
    }
  });
  return {
    enabled: true,
    totalEvaluated: comparisons.length,
    legacyKept,
    legacyRejected,
    v3Kept,
    v3Rejected,
    v3Uncertain,
    perfectMatches,
    decisionMismatches,
    categoryMismatches,
    reasonMismatches,
    pathMismatches,
    parityPercentage: comparisons.length ? Number(((perfectMatches / comparisons.length) * 100).toFixed(1)) : 0,
  };
}

function getPassportDecisionParityV3(diagnostics) {
  const summary = getPassportDecisionComparisonSummary(diagnostics);
  if (!summary?.enabled) {
    return summary;
  }
  const comparisons = getPassportDecisionComparisonDiagnostics(diagnostics);
  const confidenceDifferenceTotal = comparisons.reduce(
    (sum, comparison) => sum + (Number(comparison.confidenceDifference) || 0),
    0
  );
  return {
    enabled: true,
    evaluated: summary.totalEvaluated,
    legacyKept: summary.legacyKept,
    legacyRejected: summary.legacyRejected,
    v3Kept: summary.v3Kept,
    v3Rejected: summary.v3Rejected,
    v3Uncertain: summary.v3Uncertain,
    perfectMatches: summary.perfectMatches,
    decisionMismatch: summary.decisionMismatches,
    reasonMismatch: summary.reasonMismatches,
    categoryMismatch: summary.categoryMismatches,
    confidenceDifference: comparisons.length ? Number((confidenceDifferenceTotal / comparisons.length).toFixed(1)) : 0,
    parityPercentage: summary.parityPercentage,
  };
}

function getPassportDecisionV3Summary(diagnostics) {
  const diagnosticsList = getPassportDecisionV3Diagnostics(diagnostics);
  if (!diagnostics?.enabled) {
    return null;
  }
  const reasonCounts = new Map();
  const categoryCounts = new Map();
  let accepted = 0;
  let rejected = 0;
  let uncertain = 0;
  let confidenceTotal = 0;
  diagnosticsList.forEach((entry) => {
    if (entry.decision === "reject") {
      rejected += 1;
    } else if (entry.decision === "uncertain") {
      uncertain += 1;
    } else {
      accepted += 1;
    }
    confidenceTotal += Number(entry.confidence || 0);
    incrementReasonCount(reasonCounts, entry.rejectionReason || entry.exitReason || "kept");
    incrementReasonCount(categoryCounts, entry.rejectionCategory || "unknown");
  });
  return {
    enabled: true,
    evaluatedArticles: diagnosticsList.length,
    kept: accepted,
    rejected,
    uncertain,
    averageConfidence: diagnosticsList.length ? Number((confidenceTotal / diagnosticsList.length).toFixed(1)) : 0,
    topReasons: getTopV3DecisionReasons(reasonCounts, 20),
    topCategories: getTopV3DecisionReasons(categoryCounts, 20),
  };
}

function getIdCardDecisionEngineSummary(diagnostics) {
  if (!diagnostics?.enabled || !diagnostics.filterDecisionTraceMap) {
    return null;
  }
  const ruleCounts = new Map();
  let evaluated = 0;
  let rejected = 0;
  let kept = 0;
  let explicitIdCardEvidenceCount = 0;
  let relatedIdentityEvidenceOnlyCount = 0;
  getHeavyDiagnosticsTraces(diagnostics).forEach((trace) => {
    const idCardDecision = trace.idCardDecisionDiagnostics;
    if (!idCardDecision) {
      return;
    }
    evaluated += 1;
    if (idCardDecision.rejected) {
      rejected += 1;
    } else {
      kept += 1;
    }
    if (trace.evidenceParityDiagnostics?.evidenceHasExplicitIdCardEvidence) {
      explicitIdCardEvidenceCount += 1;
    } else if (trace.evidenceParityDiagnostics?.evidenceHasRelatedIdentityEvidence) {
      relatedIdentityEvidenceOnlyCount += 1;
    }
    incrementReasonCount(ruleCounts, idCardDecision.matchedRuleId || "unknown");
  });

  return {
    enabled: true,
    evaluated,
    ruleSetActive: true,
    documentType: ID_CARD_RULE_SET.documentType,
    explicitIdCardEvidenceCount,
    relatedIdentityEvidenceOnlyCount,
    kept,
    rejected,
    topMatchedRules: getTopV3DecisionReasons(ruleCounts, 10),
    notes: [
      "ID Card rule set runs in shadow diagnostics only",
      "Generic DocumentDecisionEngine supports Passport and ID Cards",
      "Legacy filtering remains authoritative",
    ],
  };
}

