function buildArticleIntelligenceContext(article) {
  return getCachedArticleValue(article, "personalBoostContext", () => {
    const normalizedEvent = article?._intelligence?.normalizedEvent || normalizeIntelligenceEvent(article);
    const signalIds = getArticleSignalCategories(article);
    const signalLabels = signalIds
      .map((signalId) => getSignalCategoryById(signalId)?.label || signalId)
      .join(" ")
      .toLowerCase();
    const sourceText = [
      article?.source,
      article?.sourceName,
      article?.feedTitle,
      getFeedName(article?.feedId),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    const domainText = [
      getFeedMatchDomain(article?.canonicalLink || article?.link || ""),
      getFeedMatchDomain(article?.feedUrl || ""),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    return {
      titleText: [article?.title, article?.normalizedTitle].filter(Boolean).join(" ").toLowerCase(),
      tagText: [
        Array.isArray(article?.tags) ? article.tags.join(" ") : "",
        Array.isArray(article?.keywords) ? article.keywords.join(" ") : "",
        getArticleFilterTags(article).join(" "),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase(),
      metadataText: [
        article?.topic,
        sourceText,
        signalLabels,
        normalizedEvent?.canonicalEventType,
        normalizedEvent?.domain,
        normalizedEvent?.action,
        normalizedEvent?.documentType,
        normalizedEvent?.currency,
        normalizedEvent?.operationalContext,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase(),
      bodyText: [article?.summary, article?.summaryShort, article?.contentSnippet].filter(Boolean).join(" ").toLowerCase(),
      sourceText,
      domainText,
      topicType: String(article?.topicType || ""),
      topic: normalizeFilterTag(article?.topic || ""),
      signalIds,
      eventType: String(normalizedEvent?.canonicalEventType || ""),
      domain: String(normalizedEvent?.domain || ""),
    };
  });
}

function getPersonalBoostContext(article) {
  return buildArticleIntelligenceContext(article);
}

function normalizeEvidenceId(term) {
  return String(term || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function getArticleEvidenceTextSections(context) {
  return {
    title: context?.titleText || "",
    metadata: context?.metadataText || "",
    body: context?.bodyText || "",
    source: [context?.sourceText, context?.domainText].filter(Boolean).join(" "),
    tags: context?.tagText || "",
  };
}

function getArticleEvidenceLocationsForTerm(context, term) {
  return Object.entries(getArticleEvidenceTextSections(context))
    .filter(([, text]) => textMatchesKeyword(text, term))
    .map(([location]) => location);
}

function collectArticleEvidenceEntries(context, terms = [], options = {}) {
  const sections = getArticleEvidenceTextSections(context);
  const strength = options.strength || "medium";
  const entries = [];
  const seen = new Set();
  normalizeKeywordList(terms).forEach((term) => {
    const locations = Object.entries(sections)
      .filter(([, text]) => textMatchesKeyword(text, term))
      .map(([location]) => location);
    if (!locations.length) {
      return;
    }
    const id = options.idPrefix
      ? `${options.idPrefix}_${normalizeEvidenceId(term)}`
      : normalizeEvidenceId(term);
    const key = `${id}:${term}:${locations.join("|")}`;
    if (seen.has(key)) {
      return;
    }
    seen.add(key);
    entries.push({
      id,
      term,
      matchedTerm: term,
      locations,
      strength,
      ...(options.category ? { category: options.category } : {}),
      ...(options.sourceHelper ? { sourceHelper: options.sourceHelper } : {}),
    });
  });
  return entries;
}

