function collectIdentityVerificationSourceMatches(sourceMap, terms = []) {
  const matchesBySignal = new Map();
  const normalizedTerms = normalizeKeywordList(terms);
  Object.entries(sourceMap || {}).forEach(([source, text]) => {
    normalizedTerms.forEach((term) => {
      if (!textMatchesKeyword(text, term)) {
        return;
      }
      const existing = matchesBySignal.get(term) || {
        signal: term,
        sources: [],
      };
      if (!existing.sources.includes(source)) {
        existing.sources.push(source);
      }
      matchesBySignal.set(term, existing);
    });
  });
  return Array.from(matchesBySignal.values());
}

function getIdentityVerificationMatchedExcerpt(text, term, maxLength = 240) {
  const normalizedText = normalizeIdentityVerificationTrustedText(text);
  const normalizedTerm = normalizeKeyword(term);
  if (!normalizedText) {
    return "";
  }
  const termIndex = normalizedTerm ? normalizedText.indexOf(normalizedTerm) : -1;
  if (termIndex === -1 || normalizedText.length <= maxLength) {
    return normalizedText.slice(0, maxLength);
  }
  const contextPadding = Math.max(20, Math.floor((maxLength - normalizedTerm.length) / 2));
  const start = Math.max(0, termIndex - contextPadding);
  const end = Math.min(normalizedText.length, start + maxLength);
  const excerpt = normalizedText.slice(start, end).trim();
  return `${start > 0 ? "..." : ""}${excerpt}${end < normalizedText.length ? "..." : ""}`;
}

function normalizeIdentityVerificationTrustedText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function isIdentityVerificationNearDuplicateTrustedText(left, right) {
  const leftText = normalizeIdentityVerificationTrustedText(left);
  const rightText = normalizeIdentityVerificationTrustedText(right);
  if (!leftText || !rightText || leftText === rightText) {
    return leftText === rightText;
  }
  const shorter = leftText.length <= rightText.length ? leftText : rightText;
  const longer = leftText.length > rightText.length ? leftText : rightText;
  if (shorter.length < 32) {
    return false;
  }
  const lengthRatio = shorter.length / Math.max(1, longer.length);
  return lengthRatio >= 0.58 && (
    longer.startsWith(shorter) ||
    longer.endsWith(shorter) ||
    (lengthRatio >= 0.78 && longer.includes(shorter))
  );
}

function buildIdentityVerificationTrustedTextSources(article) {
  const rawSources = [
    { source: "title", text: article?.title || "" },
    { source: "normalizedTitle", text: article?.normalizedTitle || "" },
    { source: "summary", text: article?.summary || "" },
    { source: "summaryShort", text: article?.summaryShort || "" },
    { source: "contentSnippet", text: article?.contentSnippet || "" },
  ]
    .map((entry) => ({
      ...entry,
      normalizedText: normalizeIdentityVerificationTrustedText(entry.text),
    }))
    .filter((entry) => entry.normalizedText);

  const kept = [];
  const removed = [];
  rawSources.forEach((entry) => {
    const duplicateIndex = kept.findIndex((keptEntry) => {
      if (keptEntry.normalizedText === entry.normalizedText) {
        return true;
      }
      const bothTitleFields = ["title", "normalizedTitle"].includes(keptEntry.source) &&
        ["title", "normalizedTitle"].includes(entry.source);
      return !bothTitleFields && isIdentityVerificationNearDuplicateTrustedText(keptEntry.normalizedText, entry.normalizedText);
    });

    if (duplicateIndex === -1) {
      kept.push(entry);
      return;
    }

    const duplicateEntry = kept[duplicateIndex];
    const currentIsLonger = entry.normalizedText.length > duplicateEntry.normalizedText.length;
    const replaceDuplicate =
      currentIsLonger &&
      !["title", "normalizedTitle"].includes(duplicateEntry.source);

    if (replaceDuplicate) {
      removed.push({
        source: duplicateEntry.source,
        duplicateOf: entry.source,
        reason: duplicateEntry.normalizedText === entry.normalizedText ? "exact_duplicate" : "near_duplicate_shorter_text",
        text: duplicateEntry.normalizedText.slice(0, 220),
      });
      kept[duplicateIndex] = entry;
      return;
    }

    removed.push({
      source: entry.source,
      duplicateOf: duplicateEntry.source,
      reason: duplicateEntry.normalizedText === entry.normalizedText ? "exact_duplicate" : "near_duplicate_shorter_text",
      text: entry.normalizedText.slice(0, 220),
    });
  });

  return {
    sourceMap: Object.fromEntries(kept.map((entry) => [entry.source, entry.normalizedText])),
    deduplicatedTrustedSources: kept.map((entry) => ({
      source: entry.source,
      textLength: entry.normalizedText.length,
      excerpt: entry.normalizedText.slice(0, 240),
    })),
    removedDuplicateTrustedSources: removed,
  };
}

function evaluateIdentityVerificationContextDependentMatches(trustedTextSources) {
  const candidateMatches = collectIdentityVerificationSourceMatches(
    trustedTextSources,
    IDENTITY_VERIFICATION_CONTEXT_DEPENDENT_TERMS
  );
  const candidatesBySignal = new Map(candidateMatches.map((match) => [match.signal, match]));
  const matches = [];
  const failures = [];

  IDENTITY_VERIFICATION_CONTEXT_DEPENDENT_RULES.forEach((rule) => {
    const matchedRuleTerms = normalizeKeywordList(rule.terms)
      .map((term) => candidatesBySignal.get(term))
      .filter(Boolean);
    if (!matchedRuleTerms.length) {
      return;
    }

    const contextMatches = collectIdentityVerificationSourceMatches(
      trustedTextSources,
      rule.context
    );
    matchedRuleTerms.forEach((termMatch) => {
      const entry = {
        signal: termMatch.signal,
        sources: termMatch.sources || [],
        requiredContextSignals: normalizeKeywordList(rule.context),
        matchedContextSignals: flattenIdentityVerificationSignals(contextMatches),
        contextSignalSources: getIdentityVerificationSignalSourceSummary(contextMatches),
        rejectionReason: rule.rejectionReason,
      };
      if (contextMatches.length) {
        matches.push(entry);
      } else {
        failures.push(entry);
      }
    });
  });

  return { matches, failures };
}

function mergeIdentityVerificationSourceMatches(matches = []) {
  const merged = new Map();
  matches.forEach((match) => {
    const signal = match?.signal;
    if (!signal) {
      return;
    }
    const existing = merged.get(signal) || {
      signal,
      sources: [],
    };
    (match.sources || []).forEach((source) => {
      if (source && !existing.sources.includes(source)) {
        existing.sources.push(source);
      }
    });
    merged.set(signal, existing);
  });
  return Array.from(merged.values());
}

function getIdentityVerificationMatchSources(match) {
  return Array.isArray(match?.sources) ? match.sources.filter(Boolean) : [];
}

function identityVerificationMatchHasSource(match, sources = []) {
  const allowedSources = new Set(sources);
  return getIdentityVerificationMatchSources(match).some((source) => allowedSources.has(source));
}

function isSnippetOnlyIdentityVerificationMatch(match) {
  if (match?.signal !== "identity verification") {
    return false;
  }
  const sources = getIdentityVerificationMatchSources(match);
  return sources.length > 0 &&
    sources.every((source) => IDENTITY_VERIFICATION_SNIPPET_AUTHORITY_SOURCES.includes(source)) &&
    !sources.some((source) => IDENTITY_VERIFICATION_TITLE_AUTHORITY_SOURCES.includes(source));
}

function evaluateSnippetOnlyIdentityVerificationContext(trustedTextSources) {
  const matchedGroups = [];
  const matchedSignals = [];
  const matchedSignalSources = [];

  IDENTITY_VERIFICATION_SNIPPET_CONTEXT_GROUPS.forEach((group) => {
    const matches = collectIdentityVerificationSourceMatches(trustedTextSources, group.terms);
    if (!matches.length) {
      return;
    }
    matchedGroups.push(group.group);
    flattenIdentityVerificationSignals(matches).forEach((signal) => {
      if (!matchedSignals.includes(signal)) {
        matchedSignals.push(signal);
      }
    });
    matchedSignalSources.push(...getIdentityVerificationSignalSourceSummary(matches, trustedTextSources));
  });

  const operationalIdentityMatches = collectIdentityVerificationSourceMatches(
    trustedTextSources,
    IDENTITY_VERIFICATION_SNIPPET_OPERATIONAL_IDENTITY_CONTEXT_TERMS
  );
  const operationalMatches = collectIdentityVerificationSourceMatches(
    trustedTextSources,
    IDENTITY_VERIFICATION_SNIPPET_OPERATIONAL_TERMS
  );
  if (operationalIdentityMatches.length && operationalMatches.length) {
    matchedGroups.push("operational_implementation");
    [
      ...flattenIdentityVerificationSignals(operationalIdentityMatches),
      ...flattenIdentityVerificationSignals(operationalMatches),
    ].forEach((signal) => {
      if (!matchedSignals.includes(signal)) {
        matchedSignals.push(signal);
      }
    });
    matchedSignalSources.push(
      ...getIdentityVerificationSignalSourceSummary(operationalIdentityMatches, trustedTextSources),
      ...getIdentityVerificationSignalSourceSummary(operationalMatches, trustedTextSources)
    );
  }

  return {
    passed: matchedGroups.length > 0,
    matchedGroups,
    matchedSignals,
    matchedSignalSources: mergeIdentityVerificationSourceMatches(matchedSignalSources),
  };
}

function normalizeIdentityVerificationAuthoritativeMatches(matches = []) {
  const normalized = mergeIdentityVerificationSourceMatches(matches);
  const signalSet = new Set(normalized.map((match) => match.signal));
  const suppressed = [];
  const kept = normalized.filter((match) => {
    const suppression = IDENTITY_VERIFICATION_LONGEST_MATCH_SUPPRESSION_PAIRS.find(([shorter, longer]) =>
      match.signal === shorter && signalSet.has(longer)
    );
    if (!suppression) {
      return true;
    }
    suppressed.push({
      signal: suppression[0],
      suppressedBy: suppression[1],
    });
    return false;
  });
  return {
    matches: kept,
    suppressed,
  };
}

function flattenIdentityVerificationSignals(matches = []) {
  return matches.map((match) => match.signal).filter(Boolean);
}

function getIdentityVerificationSignalSourceSummary(matches = [], sourceMap = null) {
  return matches.map((match) => ({
    signal: match.signal,
    sources: match.sources || [],
    ...(sourceMap
      ? {
          sourceExcerpts: (match.sources || []).map((source) => ({
            source,
            textLength: normalizeIdentityVerificationTrustedText(sourceMap[source]).length,
            excerpt: getIdentityVerificationMatchedExcerpt(sourceMap[source], match.signal),
          })),
        }
      : {}),
  }));
}

function getIdentityVerificationSourceTrustEvidence(article) {
  return getCachedArticleValue(article, "identityVerificationSourceTrustEvidence", () => {
    const context = getPersonalBoostContext(article);
    const trustedSourceDetails = buildIdentityVerificationTrustedTextSources(article);
    const trustedTextSources = trustedSourceDetails.sourceMap;
    const supportingTextSources = {
      tags: context.tagText,
      metadata: context.metadataText,
      source: [context.sourceText, context.domainText].filter(Boolean).join(" "),
    };
    const allTextSources = {
      ...trustedTextSources,
      ...supportingTextSources,
    };
    const rawIndependentAuthoritativeMatches = collectIdentityVerificationSourceMatches(
      trustedTextSources,
      IDENTITY_VERIFICATION_INDEPENDENT_AUTHORITATIVE_TERMS
    );
    const identityVerificationRawMatch = rawIndependentAuthoritativeMatches.find((match) =>
      match.signal === "identity verification"
    );
    const titleIdentityVerificationMatched = identityVerificationMatchHasSource(
      identityVerificationRawMatch,
      IDENTITY_VERIFICATION_TITLE_AUTHORITY_SOURCES
    );
    const snippetIdentityVerificationMatched = identityVerificationMatchHasSource(
      identityVerificationRawMatch,
      IDENTITY_VERIFICATION_SNIPPET_AUTHORITY_SOURCES
    );
    const snippetOnlyIdentityVerificationMatched = isSnippetOnlyIdentityVerificationMatch(identityVerificationRawMatch);
    const snippetOnlyIdentityVerificationContext = evaluateSnippetOnlyIdentityVerificationContext(trustedTextSources);
    const snippetOnlyIdentityVerificationContextPassed =
      snippetOnlyIdentityVerificationMatched && snippetOnlyIdentityVerificationContext.passed;
    const snippetOnlyIdentityVerificationBlocked =
      snippetOnlyIdentityVerificationMatched && !snippetOnlyIdentityVerificationContextPassed;
    const sourceSensitiveIndependentMatches = rawIndependentAuthoritativeMatches.filter((match) =>
      match.signal !== "identity verification" ||
      titleIdentityVerificationMatched ||
      !snippetOnlyIdentityVerificationMatched ||
      snippetOnlyIdentityVerificationContextPassed
    );
    const normalizedIndependentAuthoritativeEvaluation =
      normalizeIdentityVerificationAuthoritativeMatches(sourceSensitiveIndependentMatches);
    const independentAuthoritativeMatches = normalizedIndependentAuthoritativeEvaluation.matches;
    const longestMatchSuppressedSignals = normalizedIndependentAuthoritativeEvaluation.suppressed;
    const contextDependentEvaluation = evaluateIdentityVerificationContextDependentMatches(trustedTextSources);
    const contextDependentMatches = contextDependentEvaluation.matches.map((match) => ({
      signal: match.signal,
      sources: match.sources,
    }));
    const authoritativeMatches = mergeIdentityVerificationSourceMatches([
      ...independentAuthoritativeMatches,
      ...contextDependentMatches,
    ]);
    const supportingMatches = collectIdentityVerificationSourceMatches(
      allTextSources,
      IDENTITY_VERIFICATION_SUPPORTING_TERMS
    );
    const professionalMatches = collectIdentityVerificationSourceMatches(
      allTextSources,
      IDENTITY_VERIFICATION_PROFESSIONAL_RELEVANCE_TERMS
    );
    const noiseMatches = collectIdentityVerificationSourceMatches(
      allTextSources,
      IDENTITY_VERIFICATION_NOISE_TERMS
    );
    const authoritativeSignals = flattenIdentityVerificationSignals(authoritativeMatches);
    const independentlyAuthoritativeSignals = flattenIdentityVerificationSignals(independentAuthoritativeMatches);
    const rawAuthoritativeSignals = flattenIdentityVerificationSignals(rawIndependentAuthoritativeMatches);
    const normalizedAuthoritativeSignals = independentlyAuthoritativeSignals.slice();
    const contextDependentSignals = Array.from(new Set([
      ...contextDependentEvaluation.matches.map((match) => match.signal),
      ...contextDependentEvaluation.failures.map((failure) => failure.signal),
    ]));
    const supportingSignals = flattenIdentityVerificationSignals(supportingMatches)
      .filter((signal) => !authoritativeSignals.includes(signal));
    const professionalSignals = flattenIdentityVerificationSignals(professionalMatches);
    const noiseSignals = flattenIdentityVerificationSignals(noiseMatches);
    const verificationFlowMatched = authoritativeSignals.length > 0;
    const specificityGatePassed = verificationFlowMatched;
    const professionalContextMatched = professionalSignals.length > 0 || supportingSignals.length > 0;
    const threshold = Number(DIGITAL_SUBGROUP_HYBRID_FILTERS.identity_verification?.minimumInterestScore) || 20;
    const supportingBonus = Math.min(10, supportingSignals.length * 2);
    const professionalBonus = Math.min(8, professionalSignals.length * 2);
    const noisePenalty = verificationFlowMatched ? Math.min(12, noiseSignals.length * 3) : Math.min(30, noiseSignals.length * 6);
    const finalScore = verificationFlowMatched
      ? Math.max(0, Math.round(24 + supportingBonus + professionalBonus - noisePenalty))
      : Math.max(0, Math.round(Math.min(threshold - 1, supportingBonus + professionalBonus - noisePenalty)));
    let rejectionReason = "";
    if (!verificationFlowMatched) {
      if (noiseSignals.length > 0) {
        rejectionReason = "noise_without_authoritative_verification_evidence";
      } else if (contextDependentEvaluation.failures.length > 0) {
        rejectionReason = "context_dependent_verification_signal_without_trusted_context";
      } else if (supportingSignals.length > 0) {
        rejectionReason = "supporting_context_without_authoritative_verification_evidence";
      } else if (professionalSignals.length > 0) {
        rejectionReason = "professional_context_without_verification_flow";
      } else {
        rejectionReason = "missing_authoritative_verification_evidence";
      }
    } else if (noiseSignals.length >= 3 && finalScore < threshold) {
      rejectionReason = "verification_noise_dominates";
    }
    const passed = verificationFlowMatched && finalScore >= threshold && !rejectionReason;
    const passReason = passed
      ? titleIdentityVerificationMatched && independentlyAuthoritativeSignals.includes("identity verification")
        ? "title_identity_verification"
        : snippetOnlyIdentityVerificationContextPassed && independentlyAuthoritativeSignals.includes("identity verification")
          ? "snippet_identity_verification_with_trusted_context"
          : independentlyAuthoritativeSignals.length > 0
            ? "specific_authoritative_verification_phrase"
            : professionalContextMatched
              ? "context_dependent_authoritative_verification_evidence_with_professional_context"
              : "context_dependent_authoritative_verification_evidence"
      : "";
    const supportingOnlyRejected = !verificationFlowMatched && supportingSignals.length > 0;
    const metadataOnlyRejected = !verificationFlowMatched && supportingMatches.some((match) =>
      (match.sources || []).some((source) => source === "tags" || source === "metadata" || source === "source")
    );
    const professionalContextWithoutFlowRejected = !verificationFlowMatched && professionalSignals.length > 0;
    const noiseRejected = !verificationFlowMatched && noiseSignals.length > 0;

    return Object.freeze({
      independentlyAuthoritativeSignals: Object.freeze(independentlyAuthoritativeSignals.slice(0, 16)),
      independentAuthoritativeSignalSources: Object.freeze(getIdentityVerificationSignalSourceSummary(independentAuthoritativeMatches, trustedTextSources).slice(0, 16)),
      rawAuthoritativeSignals: Object.freeze(rawAuthoritativeSignals.slice(0, 16)),
      rawAuthoritativeSignalSources: Object.freeze(getIdentityVerificationSignalSourceSummary(rawIndependentAuthoritativeMatches, trustedTextSources).slice(0, 16)),
      normalizedAuthoritativeSignals: Object.freeze(normalizedAuthoritativeSignals.slice(0, 16)),
      normalizedAuthoritativeSignalSources: Object.freeze(getIdentityVerificationSignalSourceSummary(independentAuthoritativeMatches, trustedTextSources).slice(0, 16)),
      snippetOnlyIdentityVerificationMatched,
      snippetOnlyIdentityVerificationContextSignals: Object.freeze(snippetOnlyIdentityVerificationContext.matchedSignals.slice(0, 16)),
      snippetOnlyIdentityVerificationContextSignalSources: Object.freeze(
        getIdentityVerificationSignalSourceSummary(snippetOnlyIdentityVerificationContext.matchedSignalSources, trustedTextSources).slice(0, 16)
      ),
      snippetOnlyIdentityVerificationContextPassed,
      snippetOnlyIdentityVerificationBlocked,
      identityVerificationSourceAuthority: titleIdentityVerificationMatched
        ? "title_identity_verification"
        : snippetOnlyIdentityVerificationContextPassed
          ? "snippet_identity_verification_with_trusted_context"
          : snippetOnlyIdentityVerificationBlocked
            ? "snippet_identity_verification_blocked_without_trusted_context"
            : "specific_or_context_dependent_authority",
      titleIdentityVerificationMatched,
      snippetIdentityVerificationMatched,
      longestMatchSuppressedSignals: Object.freeze(longestMatchSuppressedSignals.slice(0, 16).map((entry) => Object.freeze({ ...entry }))),
      contextDependentSignals: Object.freeze(contextDependentSignals.slice(0, 16)),
      contextDependentSignalMatches: Object.freeze(contextDependentEvaluation.matches.slice(0, 16).map((match) => Object.freeze({
        signal: match.signal,
        sources: Object.freeze((match.sources || []).slice()),
        matchedContextSignals: Object.freeze((match.matchedContextSignals || []).slice(0, 12)),
        contextSignalSources: Object.freeze((match.contextSignalSources || []).slice(0, 12)),
      }))),
      contextDependentSignalFailures: Object.freeze(contextDependentEvaluation.failures.slice(0, 16).map((failure) => Object.freeze({
        signal: failure.signal,
        sources: Object.freeze((failure.sources || []).slice()),
        requiredContextSignals: Object.freeze((failure.requiredContextSignals || []).slice(0, 12)),
        rejectionReason: failure.rejectionReason,
      }))),
      authoritativeSignals: Object.freeze(authoritativeSignals.slice(0, 16)),
      authoritativeSignalSources: Object.freeze(getIdentityVerificationSignalSourceSummary(authoritativeMatches, trustedTextSources).slice(0, 16)),
      authoritativeVerificationSignals: Object.freeze(authoritativeSignals.slice(0, 16)),
      authoritativeVerificationSignalSources: Object.freeze(getIdentityVerificationSignalSourceSummary(authoritativeMatches, trustedTextSources).slice(0, 16)),
      deduplicatedTrustedSources: Object.freeze(trustedSourceDetails.deduplicatedTrustedSources.slice(0, 8).map((entry) => Object.freeze(entry))),
      removedDuplicateTrustedSources: Object.freeze(trustedSourceDetails.removedDuplicateTrustedSources.slice(0, 8).map((entry) => Object.freeze(entry))),
      supportingSignals: Object.freeze(supportingSignals.slice(0, 16)),
      supportingSignalSources: Object.freeze(getIdentityVerificationSignalSourceSummary(supportingMatches).slice(0, 16)),
      supportingIdentitySignals: Object.freeze(supportingSignals.slice(0, 16)),
      professionalSignals: Object.freeze(professionalSignals.slice(0, 16)),
      professionalVerificationSignals: Object.freeze(professionalSignals.slice(0, 16)),
      noiseSignals: Object.freeze(noiseSignals.slice(0, 16)),
      noiseVerificationSignals: Object.freeze(noiseSignals.slice(0, 16)),
      verificationFlowMatched,
      specificityGatePassed,
      professionalContextMatched,
      finalScore,
      threshold,
      passed,
      rejected: !passed,
      passReason,
      rejectionReason,
      identityVerificationEvidenceAuthority: verificationFlowMatched
        ? titleIdentityVerificationMatched && independentlyAuthoritativeSignals.includes("identity verification")
          ? "trusted_article_text_title_identity_verification"
          : snippetOnlyIdentityVerificationContextPassed && independentlyAuthoritativeSignals.includes("identity verification")
            ? "trusted_article_text_snippet_identity_verification_with_context"
            : independentlyAuthoritativeSignals.length > 0
          ? "trusted_article_text_independent"
          : "trusted_article_text_context_dependent"
        : "supporting_or_metadata_only",
      personalDashboardUsedSharedEvidence: true,
      professionalGuardUsedSharedEvidence: true,
      supportingOnlyRejected,
      metadataOnlyRejected,
      professionalContextWithoutFlowRejected,
      noiseRejected,
    });
  });
}

function getIdentityVerificationPersonalDashboardScoringAlignment(article, rawScore) {
  const evidence = getIdentityVerificationSourceTrustEvidence(article);
  const raw = Math.round(Number(rawScore) || 0);
  const finalScore = evidence.passed
    ? Math.max(evidence.finalScore, Math.min(raw, evidence.threshold + 10))
    : Math.min(evidence.finalScore, Math.max(0, evidence.threshold - 1));

  return Object.freeze({
    strongIdentityVerificationSignals: evidence.authoritativeVerificationSignals,
    independentlyAuthoritativeSignals: evidence.independentlyAuthoritativeSignals,
    rawAuthoritativeSignals: evidence.rawAuthoritativeSignals,
    normalizedAuthoritativeSignals: evidence.normalizedAuthoritativeSignals,
    snippetOnlyIdentityVerificationMatched: evidence.snippetOnlyIdentityVerificationMatched,
    snippetOnlyIdentityVerificationContextSignals: evidence.snippetOnlyIdentityVerificationContextSignals,
    snippetOnlyIdentityVerificationContextPassed: evidence.snippetOnlyIdentityVerificationContextPassed,
    snippetOnlyIdentityVerificationBlocked: evidence.snippetOnlyIdentityVerificationBlocked,
    identityVerificationSourceAuthority: evidence.identityVerificationSourceAuthority,
    titleIdentityVerificationMatched: evidence.titleIdentityVerificationMatched,
    snippetIdentityVerificationMatched: evidence.snippetIdentityVerificationMatched,
    longestMatchSuppressedSignals: evidence.longestMatchSuppressedSignals,
    contextDependentSignals: evidence.contextDependentSignals,
    contextDependentSignalMatches: evidence.contextDependentSignalMatches,
    contextDependentSignalFailures: evidence.contextDependentSignalFailures,
    deduplicatedTrustedSources: evidence.deduplicatedTrustedSources,
    removedDuplicateTrustedSources: evidence.removedDuplicateTrustedSources,
    contextOnlyIdentitySignals: evidence.supportingIdentitySignals,
    genericVerificationSignals: evidence.supportingIdentitySignals.filter((signal) => signal.includes("verification")),
    genericVerificationContextSignals: evidence.supportingIdentitySignals,
    unrelatedVerificationSignals: evidence.noiseVerificationSignals,
    negativeIdentityVerificationSignals: evidence.noiseVerificationSignals,
    identityVerificationRawScore: raw,
    identityVerificationPenalty: Math.max(0, raw - finalScore),
    identityVerificationFinalScore: finalScore,
    identityVerificationThreshold: evidence.threshold,
    identityVerificationPassed: evidence.passed && finalScore >= evidence.threshold,
    identityVerificationSharedEvidence: evidence,
  });
}

function getBanknoteSourceAuthority(article) {
  return getCachedArticleValue(article, "banknoteSourceAuthority", () => {
    const context = getPersonalBoostContext(article);
    const sourceFingerprint = `${context.sourceText} ${context.domainText} ${context.metadataText}`;
    const hasAny = (values = []) => values.some((value) => textMatchesKeyword(sourceFingerprint, value));

    let level = "medium";
    let multiplier = 1.0;

    if (hasAny(BANKNOTE_SOURCE_AUTHORITY.veryHigh)) {
      level = "very_high";
      multiplier = 2.4;
    } else if (hasAny(BANKNOTE_SOURCE_AUTHORITY.high)) {
      level = "high";
      multiplier = 1.8;
    } else if (hasAny(BANKNOTE_SOURCE_AUTHORITY.veryLow)) {
      level = "very_low";
      multiplier = 0.15;
    } else if (hasAny(BANKNOTE_SOURCE_AUTHORITY.low)) {
      level = "low";
      multiplier = 0.45;
    }

    return {
      level,
      multiplier,
    };
  });
}

function getPersonalDashboardSelectedDomainConfig() {
  const selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests);
  const mainDomainSelections = new Map();
  const sharedInterestSelections = [];

  selectedInterests.forEach((interestId) => {
    const interest = PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId);
    if (!interest) {
      return;
    }

    if (PERSONAL_DASHBOARD_MAIN_DOMAIN_GROUP_IDS.has(interest.groupId)) {
      const existing = mainDomainSelections.get(interest.groupId) || [];
      existing.push(interestId);
      mainDomainSelections.set(interest.groupId, existing);
      return;
    }

    if (interest.groupId === PERSONAL_DASHBOARD_SHARED_GROUP_ID) {
      sharedInterestSelections.push(interestId);
    }
  });

  return {
    selectedInterests,
    mainDomainSelections,
    sharedInterestSelections,
  };
}

function getEffectivePersonalDashboardDomains() {
  const { mainDomainSelections, sharedInterestSelections } = getPersonalDashboardSelectedDomainConfig();
  const selectedDomains = Array.from(mainDomainSelections.keys());
  return selectedDomains.length
    ? selectedDomains
      : sharedInterestSelections.length
        ? ["banknote_intelligence", "identity_documents"]
        : [];
}

function mapPersonalDashboardGroupToMainDomain(groupId) {
  if (groupId === "banknote_intelligence") {
    return "banknotes";
  }
  if (groupId === "identity_documents") {
    return "identity_documents";
  }
  if (groupId === "digital_identity_biometrics") {
    return "digital_identity_biometrics";
  }
  if (groupId === PERSONAL_DASHBOARD_SHARED_GROUP_ID) {
    return "shared_security";
  }
  return "unknown";
}

function getSelectedMainDomains(selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests)) {
  const normalizedInterests = normalizePersonalDashboardInterests(selectedInterests);
  const mainDomains = new Set();

  normalizedInterests.forEach((interestId) => {
    const groupId = PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId)?.groupId || "";
    const mappedDomain = mapPersonalDashboardGroupToMainDomain(groupId);
    if (mappedDomain === "banknotes" || mappedDomain === "identity_documents" || mappedDomain === "digital_identity_biometrics") {
      mainDomains.add(mappedDomain);
    }
  });

  return Array.from(mainDomains);
}

function resolvePersonalDashboardParentChildInterests(selectedInterests, groupId) {
  const normalizedInterests = normalizePersonalDashboardInterests(selectedInterests);
  const parentId = PERSONAL_DASHBOARD_PARENT_INTEREST_BY_GROUP.get(groupId) || "";
  const groupInterestIds = normalizedInterests.filter(
    (interestId) => PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId)?.groupId === groupId
  );
  const hasParent = Boolean(parentId && groupInterestIds.includes(parentId));
  const childIds = groupInterestIds.filter((interestId) => interestId !== parentId);
  const parentActsAsDomainGate = hasParent && childIds.length > 0;

  return {
    parentId,
    hasParent,
    childIds,
    groupInterestIds,
    parentActsAsDomainGate,
    effectiveInterestIds: parentActsAsDomainGate ? childIds : groupInterestIds,
  };
}

function isBanknotesOnlyPersonalSelection(selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests)) {
  const selectedMainDomains = getSelectedMainDomains(selectedInterests);
  return selectedMainDomains.length === 1 && selectedMainDomains[0] === "banknotes";
}

function isBanknoteAuthoritySource(article) {
  return getCachedArticleValue(article, "isBanknoteAuthoritySource", () => {
    return getBanknoteSourceAuthority(article).level === "very_high";
  });
}

function getDigitalSubgroupHybridAssessment(article, interestId) {
  return getCachedArticleValue(article, `digitalSubgroupHybrid:${interestId}`, () => {
    const interest = PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId);
    if (!interest || interest.groupId !== "digital_identity_biometrics") {
      return {
        beforeIncluded: false,
        included: false,
        directMatch: false,
        hybridMatch: false,
        excludedWeakMatch: false,
        directStrongHits: 0,
        directWeakHits: 0,
        relatedHits: 0,
        interestScore: 0,
        domainScore: 0,
      };
    }

    const context = getPersonalBoostContext(article);
    const domainContext = getPersonalDomainContextProfile(context, "digital_identity_biometrics");
    const interestScore = computePersonalInterestBoost(article, interestId).score;
    const config = DIGITAL_SUBGROUP_HYBRID_FILTERS[interestId] || {
      minimumDomainScore: 11,
      minimumInterestScore: 20,
      related: [],
    };
    const strongKeywords = Array.isArray(interest.strong) ? interest.strong : [];
    const weakKeywords = Array.isArray(interest.weak) ? interest.weak : [];
    const relatedKeywords = Array.isArray(config.related) ? config.related : [];
    const preferredKeywords = Array.isArray(config.preferred) ? config.preferred : [];
    const crossKeywords = Array.isArray(config.cross) ? config.cross : [];

    const directStrongHits =
      countBoostKeywordMatches(context.titleText, strongKeywords) +
      countBoostKeywordMatches(context.tagText, strongKeywords) +
      countBoostKeywordMatches(context.metadataText, strongKeywords) +
      countBoostKeywordMatches(context.bodyText, strongKeywords);
    const directWeakHits =
      countBoostKeywordMatches(context.titleText, weakKeywords) +
      countBoostKeywordMatches(context.tagText, weakKeywords) +
      countBoostKeywordMatches(context.metadataText, weakKeywords) +
      countBoostKeywordMatches(context.bodyText, weakKeywords);
    const relatedHits =
      countBoostKeywordMatches(context.titleText, relatedKeywords) +
      countBoostKeywordMatches(context.tagText, relatedKeywords) +
      countBoostKeywordMatches(context.metadataText, relatedKeywords) +
      countBoostKeywordMatches(context.bodyText, relatedKeywords);
    const preferredHits =
      countBoostKeywordMatches(context.titleText, preferredKeywords) +
      countBoostKeywordMatches(context.tagText, preferredKeywords) +
      countBoostKeywordMatches(context.metadataText, preferredKeywords) +
      countBoostKeywordMatches(context.bodyText, preferredKeywords);
    const crossHits =
      countBoostKeywordMatches(context.titleText, crossKeywords) +
      countBoostKeywordMatches(context.tagText, crossKeywords) +
      countBoostKeywordMatches(context.metadataText, crossKeywords) +
      countBoostKeywordMatches(context.bodyText, crossKeywords);
    const minimumPreferredHits = Number(config.minimumPreferredHits || 0);
    const minimumNetEvidence = Number(config.minimumNetEvidence || 0);
    const netEvidence = (preferredHits + relatedHits + directStrongHits + directWeakHits) - crossHits;
    const preferredSatisfied = minimumPreferredHits <= 0 || preferredHits >= minimumPreferredHits;
    const conflictDominates = crossHits > 0 && netEvidence < minimumNetEvidence;
    const directStrongMatch = directStrongHits > 0;
    const directWeakOnlyMatch =
      !directStrongMatch &&
      directWeakHits > 0 &&
      interestScore >= config.minimumInterestScore &&
      preferredSatisfied &&
      !conflictDominates;

    const directMatch = directStrongMatch || directWeakOnlyMatch;
    const hybridMatch =
      !directMatch &&
      domainContext.score >= config.minimumDomainScore &&
      interestScore >= config.minimumInterestScore &&
      (directWeakHits > 0 || relatedHits > 0 || preferredHits > 0) &&
      preferredSatisfied &&
      netEvidence >= minimumNetEvidence &&
      !conflictDominates;
    const beforeIncluded = interestScore >= DIGITAL_SUBGROUP_BASELINE_MINIMUM_SCORE;
    const identityVerificationSharedEvidence = interestId === "identity_verification"
      ? getIdentityVerificationSourceTrustEvidence(article)
      : null;
    const included = identityVerificationSharedEvidence
      ? identityVerificationSharedEvidence.passed
      : directMatch || hybridMatch;

    return {
      beforeIncluded,
      included,
      directMatch: identityVerificationSharedEvidence ? identityVerificationSharedEvidence.verificationFlowMatched : directMatch,
      hybridMatch: identityVerificationSharedEvidence ? false : hybridMatch,
      excludedWeakMatch: beforeIncluded && !included,
      directStrongHits,
      directWeakHits,
      relatedHits,
      preferredHits,
      crossHits,
      netEvidence,
      interestScore: identityVerificationSharedEvidence ? identityVerificationSharedEvidence.finalScore : interestScore,
      domainScore: domainContext.score,
      ...(identityVerificationSharedEvidence
        ? {
            sharedEvidenceUsed: true,
            independentlyAuthoritativeSignals: identityVerificationSharedEvidence.independentlyAuthoritativeSignals,
            rawAuthoritativeSignals: identityVerificationSharedEvidence.rawAuthoritativeSignals,
            normalizedAuthoritativeSignals: identityVerificationSharedEvidence.normalizedAuthoritativeSignals,
            snippetOnlyIdentityVerificationMatched: identityVerificationSharedEvidence.snippetOnlyIdentityVerificationMatched,
            snippetOnlyIdentityVerificationContextSignals: identityVerificationSharedEvidence.snippetOnlyIdentityVerificationContextSignals,
            snippetOnlyIdentityVerificationContextPassed: identityVerificationSharedEvidence.snippetOnlyIdentityVerificationContextPassed,
            snippetOnlyIdentityVerificationBlocked: identityVerificationSharedEvidence.snippetOnlyIdentityVerificationBlocked,
            identityVerificationSourceAuthority: identityVerificationSharedEvidence.identityVerificationSourceAuthority,
            titleIdentityVerificationMatched: identityVerificationSharedEvidence.titleIdentityVerificationMatched,
            snippetIdentityVerificationMatched: identityVerificationSharedEvidence.snippetIdentityVerificationMatched,
            longestMatchSuppressedSignals: identityVerificationSharedEvidence.longestMatchSuppressedSignals,
            contextDependentSignals: identityVerificationSharedEvidence.contextDependentSignals,
            contextDependentSignalMatches: identityVerificationSharedEvidence.contextDependentSignalMatches,
            contextDependentSignalFailures: identityVerificationSharedEvidence.contextDependentSignalFailures,
            authoritativeVerificationSignals: identityVerificationSharedEvidence.authoritativeVerificationSignals,
            supportingIdentitySignals: identityVerificationSharedEvidence.supportingIdentitySignals,
            noiseVerificationSignals: identityVerificationSharedEvidence.noiseVerificationSignals,
            deduplicatedTrustedSources: identityVerificationSharedEvidence.deduplicatedTrustedSources,
            removedDuplicateTrustedSources: identityVerificationSharedEvidence.removedDuplicateTrustedSources,
            identityVerificationEvidenceAuthority: identityVerificationSharedEvidence.identityVerificationEvidenceAuthority,
            passReason: identityVerificationSharedEvidence.passReason,
            rejectionReason: identityVerificationSharedEvidence.rejectionReason,
          }
        : {}),
    };
  });
}

