function shouldApplyIdentityVerificationProfessionalGuard(selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests)) {
  const normalizedInterests = normalizePersonalDashboardInterests(selectedInterests);
  const selectedMainDomains = getSelectedMainDomains(normalizedInterests);
  return selectedMainDomains.includes("digital_identity_biometrics") &&
    normalizedInterests.includes("identity_verification");
}

function getIdentityVerificationProfessionalGuardAssessment(article, options = {}) {
  const selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests);
  const enabled = Boolean(options.forceEnabled) ||
    shouldApplyIdentityVerificationProfessionalGuard(selectedInterests);
  const sharedEvidence = getIdentityVerificationSourceTrustEvidence(article);
  const selectedIdentityVerificationAssessment = getDigitalSubgroupHybridAssessment(article, "identity_verification");
  const matchedStrongSignals = sharedEvidence.authoritativeVerificationSignals || [];
  const matchedUseCaseTerms = sharedEvidence.supportingIdentitySignals || [];
  const matchedEventContextTerms = sharedEvidence.professionalVerificationSignals || [];
  const matchedVendorSignals = matchedUseCaseTerms.filter((signal) =>
    IDENTITY_VERIFICATION_SUPPORTING_TERMS.includes(signal) &&
    [
      "jumio",
      "onfido",
      "entrust",
      "regula",
      "veriff",
      "sumsub",
      "idnow",
      "persona",
      "trulioo",
      "socure",
      "mitek",
      "iproov",
      "facephi",
      "shufti",
      "incode",
      "idemia",
      "thales",
    ].includes(signal)
  );
  const matchedVendorContextTerms = matchedUseCaseTerms.filter((signal) => signal.includes("verification") || signal.includes("credential") || signal.includes("kyc") || signal.includes("onboarding"));
  const matchedAgeVerificationTerms = matchedStrongSignals.filter((signal) => signal.includes("age"));
  const matchedAgeTechnologyTerms = matchedStrongSignals.filter((signal) => signal.includes("age") || signal.includes("biometric age"));
  const matchedGenericVerificationNoiseTerms = sharedEvidence.noiseVerificationSignals || [];
  const matchedAuthenticationNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("authentication") || signal.includes("login") || signal.includes("passkey"));
  const matchedGenericBiometricsNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("biometric") || signal.includes("facial recognition"));
  const matchedGenericDigitalIdentityNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("digital identity"));
  const matchedGovernmentIdentityNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("government") || signal.includes("legislation") || signal.includes("transformation"));
  const matchedCredentialIssuanceNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("credential issuance"));
  const matchedAiAgentNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("ai agent") || signal.includes("human intent") || signal.includes("agentic"));
  const matchedVoiceThreatNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("voice") || signal.includes("deepfake threat"));
  const matchedContextOnlyTerms = matchedUseCaseTerms;
  const matchedAgePolicyNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("political") || signal.includes("policy"));
  const matchedSoftwareDeviceNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("software") || signal.includes("device"));
  const matchedTutorialNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("tutorial") || signal.includes("guide") || signal.includes("what is"));
  const matchedWrongDomainNoiseTerms = matchedGenericVerificationNoiseTerms.filter((signal) => signal.includes("passport renewal") || signal.includes("payment") || signal.includes("transaction"));
  const hasStrongIdentityVerification = sharedEvidence.verificationFlowMatched;
  const hasUseCaseContext = matchedUseCaseTerms.length > 0;
  const hasEventContext = matchedEventContextTerms.length > 0;
  const hasVendorIdentityContext = matchedVendorSignals.length > 0 && matchedVendorContextTerms.length > 0;
  const hasAgeVerificationTechnology = matchedAgeVerificationTerms.length > 0;
  const verificationFlowMatched = sharedEvidence.verificationFlowMatched;
  const hasVendorProfessionalEvent = hasVendorIdentityContext && hasEventContext;
  const vendorRescueApproved = false;
  const specificityGatePassed = sharedEvidence.specificityGatePassed;
  const genericRescueCandidate = hasUseCaseContext ||
    hasEventContext ||
    hasVendorIdentityContext ||
    matchedContextOnlyTerms.length > 0 ||
    selectedIdentityVerificationAssessment.included;
  const genericRescueAttempted = Boolean(genericRescueCandidate);
  const genericRescueBlockedWithoutVerificationFlow = genericRescueCandidate && !specificityGatePassed;
  const vendorRescueBlocked = hasVendorProfessionalEvent && !specificityGatePassed;
  const professionalIdentityVerificationMatched = specificityGatePassed;
  const tutorialNoise = matchedTutorialNoiseTerms.length > 0 && !specificityGatePassed;
  const agePolicyNoise = matchedAgePolicyNoiseTerms.length > 0 && !specificityGatePassed;
  const softwareDeviceNoise = matchedSoftwareDeviceNoiseTerms.length > 0 && !specificityGatePassed;
  const authenticationNoise = matchedAuthenticationNoiseTerms.length > 0 && !specificityGatePassed;
  const genericBiometricsNoise = matchedGenericBiometricsNoiseTerms.length > 0 && !specificityGatePassed;
  const genericDigitalIdentityNoise = matchedGenericDigitalIdentityNoiseTerms.length > 0 && !specificityGatePassed;
  const governmentIdentityNoise = matchedGovernmentIdentityNoiseTerms.length > 0 && !specificityGatePassed;
  const credentialIssuanceNoise = matchedCredentialIssuanceNoiseTerms.length > 0 && !specificityGatePassed;
  const aiAgentVerificationNoise = matchedAiAgentNoiseTerms.length > 0 && !specificityGatePassed;
  const voiceThreatNoise = matchedVoiceThreatNoiseTerms.length > 0 && !specificityGatePassed;
  const contextOnlyNoise = sharedEvidence.supportingOnlyRejected;
  const genericVerificationNoise = matchedGenericVerificationNoiseTerms.length > 0 && !specificityGatePassed;
  const wrongDomainNoise = (matchedWrongDomainNoiseTerms.length > 0 || voiceThreatNoise) && !specificityGatePassed;
  const hardNegativeSignals = sharedEvidence.noiseVerificationSignals || [];
  const rejectionReason = enabled ? sharedEvidence.rejectionReason : "";
  const passed = !enabled || sharedEvidence.passed;
  const passReason = !passed
    ? ""
    : sharedEvidence.passReason || "authoritative_verification_evidence";
  const stageResult = passed ? "passed" : "rejected";
  const verificationFlowSignals = Object.freeze([
    ...matchedStrongSignals,
  ].slice(0, 12));
  const genericContextSignals = Object.freeze(matchedContextOnlyTerms.slice(0, 12));
  const vendorSignals = Object.freeze(matchedVendorSignals.slice(0, 12));
  const professionalEventSignals = Object.freeze(matchedEventContextTerms.slice(0, 12));
  const frozenHardNegativeSignals = Object.freeze(hardNegativeSignals.slice(0, 12));
  const authoritativeDecision = Object.freeze({
    passed,
    rejected: enabled && !passed,
    stageResult,
    passReason,
    rejectionReason,
    verificationFlowMatched,
    specificityGatePassed,
    verificationFlowSignals,
    specificitySignals: verificationFlowSignals,
    genericContextSignals,
    contextOnlySignals: genericContextSignals,
    vendorSignals,
    professionalEventSignals,
    hardNegativeSignals: frozenHardNegativeSignals,
    genericRescueAttempted,
    genericRescueBlocked: genericRescueBlockedWithoutVerificationFlow,
    genericRescueBlockedWithoutVerificationFlow,
    vendorRescueBlocked,
    finalPassReason: passReason,
    finalRejectionReason: rejectionReason,
    decisionAuthority: "identity_verification_professional_guard",
    sharedEvidence,
  });

  return Object.freeze({
    enabled,
    branch: options.branch || "",
    selectedInterests: Object.freeze(selectedInterests.slice()),
    title: article?.title || "Untitled article",
    source: getIdentityNoiseGuardSource(article),
    passed: authoritativeDecision.passed,
    rejected: authoritativeDecision.rejected,
    stageResult: authoritativeDecision.stageResult,
    decisionAuthority: authoritativeDecision.decisionAuthority,
    authoritativeDecision,
    rejectionReason,
    rejectionCategory: rejectionReason ? "identity_verification_professional_relevance" : "",
    hasStrongIdentityVerification,
    hasUseCaseContext,
    hasEventContext,
    hasVendorIdentityContext,
    hasVendorProfessionalEvent,
    hasAgeVerificationTechnology,
    verificationFlowMatched,
    specificityGatePassed,
    vendorRescueApproved,
    vendorRescueBlocked,
    genericRescueAttempted,
    genericRescueBlocked: authoritativeDecision.genericRescueBlocked,
    genericRescueBlockedWithoutVerificationFlow,
    professionalIdentityVerificationMatched,
    passReason: authoritativeDecision.passReason,
    finalPassReason: authoritativeDecision.finalPassReason,
    finalRejectionReason: authoritativeDecision.finalRejectionReason,
    tutorialNoise,
    agePolicyNoise,
    softwareDeviceNoise,
    authenticationNoise,
    genericBiometricsNoise,
    genericDigitalIdentityNoise,
    governmentIdentityNoise,
    credentialIssuanceNoise,
    aiAgentVerificationNoise,
    voiceThreatNoise,
    contextOnlyNoise,
    genericVerificationNoise,
    wrongDomainNoise,
    matchedStrongSignals: Object.freeze(matchedStrongSignals.slice(0, 12)),
    matchedUseCaseTerms: Object.freeze(matchedUseCaseTerms.slice(0, 12)),
    matchedEventContextTerms: Object.freeze(matchedEventContextTerms.slice(0, 12)),
    matchedVendorSignals: Object.freeze(matchedVendorSignals.slice(0, 12)),
    matchedVendorContextTerms: Object.freeze(matchedVendorContextTerms.slice(0, 12)),
    matchedAgeVerificationTerms: Object.freeze(matchedAgeVerificationTerms.slice(0, 12)),
    matchedAgeTechnologyTerms: Object.freeze(matchedAgeTechnologyTerms.slice(0, 12)),
    matchedGenericVerificationNoiseTerms: Object.freeze(matchedGenericVerificationNoiseTerms.slice(0, 12)),
    matchedAuthenticationNoiseTerms: Object.freeze(matchedAuthenticationNoiseTerms.slice(0, 12)),
    matchedGenericBiometricsNoiseTerms: Object.freeze(matchedGenericBiometricsNoiseTerms.slice(0, 12)),
    matchedGenericDigitalIdentityNoiseTerms: Object.freeze(matchedGenericDigitalIdentityNoiseTerms.slice(0, 12)),
    matchedGovernmentIdentityNoiseTerms: Object.freeze(matchedGovernmentIdentityNoiseTerms.slice(0, 12)),
    matchedCredentialIssuanceNoiseTerms: Object.freeze(matchedCredentialIssuanceNoiseTerms.slice(0, 12)),
    matchedAiAgentNoiseTerms: Object.freeze(matchedAiAgentNoiseTerms.slice(0, 12)),
    matchedVoiceThreatNoiseTerms: Object.freeze(matchedVoiceThreatNoiseTerms.slice(0, 12)),
    matchedContextOnlyTerms: Object.freeze(matchedContextOnlyTerms.slice(0, 12)),
    matchedAgePolicyNoiseTerms: Object.freeze(matchedAgePolicyNoiseTerms.slice(0, 12)),
    matchedSoftwareDeviceNoiseTerms: Object.freeze(matchedSoftwareDeviceNoiseTerms.slice(0, 12)),
    matchedTutorialNoiseTerms: Object.freeze(matchedTutorialNoiseTerms.slice(0, 12)),
    matchedWrongDomainNoiseTerms: Object.freeze(matchedWrongDomainNoiseTerms.slice(0, 12)),
    verificationFlowSignals,
    specificitySignals: verificationFlowSignals,
    genericContextSignals,
    contextOnlySignals: genericContextSignals,
    vendorSignals,
    professionalEventSignals,
    hardNegativeSignals: frozenHardNegativeSignals,
    identityVerificationHybridAssessment: selectedIdentityVerificationAssessment,
    sharedEvidence,
    independentlyAuthoritativeSignals: sharedEvidence.independentlyAuthoritativeSignals,
    independentAuthoritativeSignalSources: sharedEvidence.independentAuthoritativeSignalSources,
    rawAuthoritativeSignals: sharedEvidence.rawAuthoritativeSignals,
    rawAuthoritativeSignalSources: sharedEvidence.rawAuthoritativeSignalSources,
    normalizedAuthoritativeSignals: sharedEvidence.normalizedAuthoritativeSignals,
    normalizedAuthoritativeSignalSources: sharedEvidence.normalizedAuthoritativeSignalSources,
    snippetOnlyIdentityVerificationMatched: sharedEvidence.snippetOnlyIdentityVerificationMatched,
    snippetOnlyIdentityVerificationContextSignals: sharedEvidence.snippetOnlyIdentityVerificationContextSignals,
    snippetOnlyIdentityVerificationContextPassed: sharedEvidence.snippetOnlyIdentityVerificationContextPassed,
    snippetOnlyIdentityVerificationBlocked: sharedEvidence.snippetOnlyIdentityVerificationBlocked,
    identityVerificationSourceAuthority: sharedEvidence.identityVerificationSourceAuthority,
    titleIdentityVerificationMatched: sharedEvidence.titleIdentityVerificationMatched,
    snippetIdentityVerificationMatched: sharedEvidence.snippetIdentityVerificationMatched,
    longestMatchSuppressedSignals: sharedEvidence.longestMatchSuppressedSignals,
    contextDependentSignals: sharedEvidence.contextDependentSignals,
    contextDependentSignalMatches: sharedEvidence.contextDependentSignalMatches,
    contextDependentSignalFailures: sharedEvidence.contextDependentSignalFailures,
    authoritativeVerificationSignals: sharedEvidence.authoritativeVerificationSignals,
    authoritativeVerificationSignalSources: sharedEvidence.authoritativeVerificationSignalSources,
    deduplicatedTrustedSources: sharedEvidence.deduplicatedTrustedSources,
    removedDuplicateTrustedSources: sharedEvidence.removedDuplicateTrustedSources,
    supportingIdentitySignals: sharedEvidence.supportingIdentitySignals,
    supportingSignalSources: sharedEvidence.supportingSignalSources,
    professionalVerificationSignals: sharedEvidence.professionalVerificationSignals,
    noiseVerificationSignals: sharedEvidence.noiseVerificationSignals,
    identityVerificationEvidenceAuthority: sharedEvidence.identityVerificationEvidenceAuthority,
    personalDashboardUsedSharedEvidence: true,
    professionalGuardUsedSharedEvidence: true,
  });
}

function shouldApplyDigitalIdentityProfessionalGuard(selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests)) {
  const normalizedInterests = normalizePersonalDashboardInterests(selectedInterests);
  const selectedMainDomains = getSelectedMainDomains(normalizedInterests);
  return selectedMainDomains.length === 1 &&
    selectedMainDomains[0] === "digital_identity_biometrics" &&
    normalizedInterests.includes("digital_identity");
}

function shouldApplyDigitalIdentityProfessionalGuardBooleanGate(selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests)) {
  const normalizedInterests = normalizePersonalDashboardInterests(selectedInterests);
  const selectedMainDomains = getSelectedMainDomains(normalizedInterests);
  return selectedMainDomains.includes("digital_identity_biometrics") &&
    normalizedInterests.includes("digital_identity");
}

function getDigitalIdentityProfessionalGuardBooleanGateAssessment(article, selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests)) {
  const normalizedInterests = normalizePersonalDashboardInterests(selectedInterests);
  if (!shouldApplyDigitalIdentityProfessionalGuardBooleanGate(normalizedInterests)) {
    return null;
  }

  const selectedDigitalInterests = normalizedInterests.filter(
    (interestId) => PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId)?.groupId === "digital_identity_biometrics"
  );
  const legacyDigitalIdentityMatched =
    getArticleDominantDomain(article) === "digital_identity_biometrics" ||
    selectedDigitalInterests.some((interestId) => getDigitalSubgroupHybridAssessment(article, interestId).included);

  if (!legacyDigitalIdentityMatched) {
    return null;
  }

  return getDigitalIdentityProfessionalGuardAssessment(article, {
    branch: "personal_dashboard_boolean",
    forceEnabled: true,
  });
}

function getDigitalIdentityProfessionalGuardAssessment(article, options = {}) {
  const selectedInterests = normalizePersonalDashboardInterests(state.personalDashboard.interests);
  const enabled = Boolean(options.forceEnabled) || shouldApplyDigitalIdentityProfessionalGuard(selectedInterests);
  const context = getPersonalBoostContext(article);
  const haystack = [
    context.titleText,
    context.tagText,
    context.metadataText,
    context.bodyText,
  ]
    .filter(Boolean)
    .join(" ");
  const contentHaystack = [
    context.titleText,
    context.bodyText,
  ]
    .filter(Boolean)
    .join(" ");
  const matchedStrongTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_STRONG_TERMS)
    .filter((term) => textMatchesKeyword(haystack, term));
  const matchedCoreTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_CORE_TERMS)
    .filter((term) => textMatchesKeyword(contentHaystack, term));
  const matchedSupportTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_SUPPORT_TERMS)
    .filter((term) => textMatchesKeyword(haystack, term));
  const matchedVendorTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_VENDOR_TERMS)
    .filter((term) => textMatchesKeyword(contentHaystack, term));
  const matchedNoiseTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_NOISE_TERMS)
    .filter((term) => textMatchesKeyword(haystack, term));
  const matchedVerificationTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_VERIFICATION_TERMS)
    .filter((term) => textMatchesKeyword(contentHaystack, term));
  const matchedProfessionalContextTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_CONTEXT_TERMS)
    .filter((term) => textMatchesKeyword(contentHaystack, term));
  const matchedVendorContextTerms = normalizeKeywordList(DIGITAL_IDENTITY_PROFESSIONAL_VENDOR_CONTEXT_TERMS)
    .filter((term) => textMatchesKeyword(contentHaystack, term));
  const domainScore = getPersonalDomainContextProfile(context, "digital_identity_biometrics").score;
  const interestBoost = Number(computePersonalInterestBoost(article, "digital_identity")?.score) || 0;
  const hasStrongProfessionalEvidence = matchedStrongTerms.length > 0;
  const hasCoreDigitalIdentitySignal = matchedCoreTerms.length > 0;
  const hasContextualVerificationEvidence = matchedVerificationTerms.length > 0 &&
    matchedProfessionalContextTerms.length > 0;
  const hasVendorProfessionalEvidence = matchedVendorTerms.length > 0 &&
    matchedVendorContextTerms.length > 0;
  const finalGatePassed = hasCoreDigitalIdentitySignal ||
    hasContextualVerificationEvidence ||
    hasVendorProfessionalEvidence;
  const hasGenericIdentityDocumentSignalOnly = !finalGatePassed && (
    matchedSupportTerms.some((term) => [
      "passport",
      "id card",
      "identity card",
      "national id",
    ].includes(term)) ||
    matchedStrongTerms.some((term) => [
      "government identity",
      "public sector identity",
    ].includes(term))
  );
  const hasBiometricWeakSignal = !finalGatePassed &&
    (textMatchesKeyword(haystack, "biometric") || textMatchesKeyword(haystack, "biometrics"));
  const hasProfessionalSourceOnlySignal = !finalGatePassed &&
    domainScore >= 14 &&
    matchedStrongTerms.length === 0 &&
    matchedSupportTerms.length === 0 &&
    matchedVerificationTerms.length === 0 &&
    matchedVendorTerms.length === 0;
  const scoreOnlySupport = !finalGatePassed &&
    !hasContextualVerificationEvidence &&
    !hasVendorProfessionalEvidence &&
    (matchedSupportTerms.length > 0 || matchedVerificationTerms.length > 0) &&
    (interestBoost >= 24 || domainScore >= 14);
  const hasSupportedProfessionalEvidence = hasContextualVerificationEvidence || hasVendorProfessionalEvidence;
  const weakOnlyRejected = enabled &&
    !finalGatePassed &&
    (
      matchedStrongTerms.length > 0 ||
      matchedSupportTerms.length > 0 ||
      matchedVerificationTerms.length > 0 ||
      interestBoost > 0 ||
      domainScore > 0
    );
  const noiseDominates = matchedNoiseTerms.length > 0 && !finalGatePassed;
  let rejectionReason = "";
  if (enabled) {
    if (noiseDominates) {
      rejectionReason = "generic cyber/enterprise identity noise without professional digital identity evidence";
    } else if (hasGenericIdentityDocumentSignalOnly) {
      rejectionReason = "generic_identity_document_signal_only";
    } else if (hasBiometricWeakSignal) {
      rejectionReason = "biometric_without_identity_platform";
    } else if (hasProfessionalSourceOnlySignal) {
      rejectionReason = "professional_source_only";
    } else if (scoreOnlySupport) {
      rejectionReason = "generic digital identity score without professional evidence";
    } else if (weakOnlyRejected) {
      rejectionReason = "weak-only digital identity evidence without core, verification-context, or vendor-context evidence";
    } else if (!hasStrongProfessionalEvidence && !hasSupportedProfessionalEvidence) {
      rejectionReason = "missing professional digital identity evidence";
    }
  }
  const passed = !enabled || finalGatePassed;

  return Object.freeze({
    enabled,
    branch: options.branch || "",
    selectedInterests: Object.freeze(selectedInterests.slice()),
    selectedDigitalIdentityInterests: Object.freeze(selectedInterests.filter(
      (interestId) => PERSONAL_DASHBOARD_INTEREST_MAP.get(interestId)?.groupId === "digital_identity_biometrics"
    )),
    title: article?.title || "Untitled article",
    source: getIdentityNoiseGuardSource(article),
    passed,
    rejected: enabled && !passed,
    rejectionReason,
    rejectionCategory: rejectionReason ? "digital_identity_professional_relevance" : "",
    hasStrongProfessionalEvidence,
    hasCoreDigitalIdentitySignal,
    hasSupportedProfessionalEvidence,
    hasContextualVerificationEvidence,
    hasVendorProfessionalEvidence,
    finalGatePassed,
    hasGenericIdentityDocumentSignalOnly,
    hasBiometricWeakSignal,
    hasProfessionalSourceOnlySignal,
    scoreOnlySupport,
    weakOnlyRejected,
    noiseDominates,
    matchedCoreTerms: Object.freeze(matchedCoreTerms.slice(0, 12)),
    matchedStrongTerms: Object.freeze(matchedStrongTerms.slice(0, 12)),
    matchedSupportTerms: Object.freeze(matchedSupportTerms.slice(0, 12)),
    matchedVendorTerms: Object.freeze(matchedVendorTerms.slice(0, 12)),
    matchedNoiseTerms: Object.freeze(matchedNoiseTerms.slice(0, 12)),
    matchedVerificationTerms: Object.freeze(matchedVerificationTerms.slice(0, 12)),
    matchedProfessionalContextTerms: Object.freeze(matchedProfessionalContextTerms.slice(0, 12)),
    matchedVendorContextTerms: Object.freeze(matchedVendorContextTerms.slice(0, 12)),
    domainScore,
    interestBoost,
    dominantDomain: getArticleDominantDomain(article),
  });
}

function articlePassesDigitalIdentityProfessionalRelevance(article, options = {}) {
  return getDigitalIdentityProfessionalGuardAssessment(article, options).passed;
}

function getDigitalIdentityProfessionalGuardRejectionCategory(assessment = {}) {
  const reason = String(assessment?.rejectionReason || "");
  if (reason === "generic_identity_document_signal_only") {
    return "generic_identity_document_signal_only";
  }
  if (reason === "biometric_without_identity_platform") {
    return "biometric_without_digital_identity_context";
  }
  if (reason === "professional_source_only") {
    return "professional_source_only";
  }
  return "weak_digital_identity_signal";
}

